  { "Spell", "Touch of Elune", 278080, 37040, "Classless", "", "Place the Touch of Elune on an enemy. For the next 10 sec, casting Wrath, Starfire and Starsurge spells to other targets also triggers them on the target marked by your Touch of Elune.", "Epic", 640, nil, 0, false, 10, true },
  { "Spell", "Glacial Burst", 278145, 37050, "Classless", "Rank 1", "You hurl a shard of glacier at the target, dealing 467 Frost damage. If your Flame Shock is on the target, Glacial Burst deals a critical strike.  This uses Lava Burst modifiers.", "Rare", 156, nil, 0, false, 22, true },
  { "Spell", "Grove Shot", 278240, 37063, "Classless", "Rank 1", "Requires   Path of Healing   Inject a bolt infused with medicinal energies into a friendly target healing for 189 as Nature.    Scales with Steady Shot modifiers.", "Rare", 249, nil, 0, false, 10, true },
