  { "Spell", "Wraith", 284732, 37530, "Classless", "Rank 1", "Finishing move that haunts your target, dealing damage and increasing the damage of your Physical damage-over-time effects against it.   When Wraith ends or is dispelled, it heals you for 100% of the direct damage done.    1 point : 169 Physical damage; 2% increase for 12 sec    2 points: 308 Physical damage; 4% increase for 12 sec    3 points: 446 Physical damage; 6% increase for 12 sec    4 points: 584 Shadow damage; 8% increase for 12 sec    5 points: 723 Physical damage; 10% increase for 12 sec    This uses Haunt modifiers.", "Legendary", 40, nil, 3, false, 40, true },
  { "Spell", "Temporal Rift", 284758, 37534, "Classless", "Rank 1", "Create a temporal rift that explodes after 4 seconds, dealing 150 to 157 Arcane damage to enemies within 10 yards.     Max 3 charges. 10 seconds recharge timer.    This uses Arcane Explosion modifiers.", "Rare", 343, nil, 0, false, 12, true },
