  { "Spell", "Megafrost", 284822, 37543, "Classless", "Rank 1", "Finishing move that deals Frost damage around the caster and freezes enemies per combo point:    1 point : 33 damage and freezes enemies for 1 sec    2 points: 59 damage and freezes enemies for 2 sec    3 points: 85 damage and freezes enemies for 3 sec    4 points: 111 damage and freezes enemies for 4 sec    5 points: 138 damage and freezes enemies for 5 sec    Scales from modifiers to Frost Nova. Fingers of Frost allows casting at no combo points.", "Epic", 109, nil, 0, false, 10, true },
  { "Spell", "Ironsand", 284834, 37545, "Classless", "Rank 1", "Channel an ironsand storm around you, dealing 83 Nature damage every second to nearby enemies, slowing them by 15% and causing them to suffer 9 to 13 Bleed damage every second, stacking up to 3 times.", "Rare", 999, nil, 0, false, 30, true },
