  { "Spell", "Curse of Doom", 603, 40044, "Warlock", "Rank 1", "Curses the target with impending doom, causing 1518 Shadow damage after 1 min. If the target yields experience or honor when it dies from this damage, a Doomguard will be summoned.      Cannot be cast on players.", "Normal", 234, nil, 0, false, 40, true },
  { "Spell", "Dampen Magic", 604, 40045, "Mage", "Rank 1", "Dampens magic used against the targeted party member, decreasing magic damage taken by 5% and healing spells by 5%.  Lasts 10 min.  This ability is usable while shapeshifted.", "Uncommon", 421, nil, 0, false, 12, true },
  { "Spell", "Lay on Hands", 633, 40046, "Paladin", "Rank 1", "Heals a friendly target for an amount equal of 100% of your maximum health. The target cannot be targeted by Divine Shield, Hand of Protection, or Lay on Hands again for 2 min.    Cannot be used within 30 sec of using Avenging Wrath.", "Legendary", 0, nil, 0, false, 10, true },
  { "Spell", "Holy Light", 635, 40047, "Paladin", "Rank 1", "Heals a friendly target for 31 to 39.", "Normal", 452, nil, 0, false, 1, true },
  { "Spell", "Divine Shield", 642, 40048, "Paladin", "", "Protects you from all damage and spells for 12 sec, but reduces your damage by 50%.    Once protected, the target cannot be targeted by Divine Shield, Hand of Protection or Lay on Hands again for 2 min.", "Legendary", 46, nil, 0, false, 34, true },
  { "Spell", "Disarm", 676, 40049, "Warrior", "", "Disarm the enemy, removing their weapons, shields, or other equipment for 6 sec.", "Epic", 15, nil, 1, false, 16, true },
  { "Spell", "Shadow Bolt", 686, 40050, "Warlock", "Rank 1", "Sends a shadowy bolt at the enemy, causing 17 to 23 Shadow damage.", "Normal", 234, nil, 0, false, 1, true },
  { "Spell", "Summon Imp", 688, 40051, "Warlock", "Summon", "Summons an Imp under the command of the Warlock.", "Rare", 999, nil, 0, false, 1, true },
  { "Spell", "Drain Life", 689, 40052, "Warlock", "Rank 1", "Transfers 10 health every 0.98 sec from the target to the caster.  Lasts 4.88 sec.", "Normal", 265, nil, 0, false, 14, true },
  { "Spell", "Create Soulstone", 693, 40053, "Warlock", "Rank 1", "Creates a Minor Soulstone. The Soulstone can be used to store one target's soul.  If the target dies while his soul is stored, he will be able to resurrect with 400 health and 700 mana.  Conjured items disappear if logged out for more than 15 minutes.", "Uncommon", 1062, nil, 0, false, 18, true },
  { "Spell", "Mocking Blow", 694, 40054, "Warrior", "", "A mocking attack, dealing weapon damage, that causes a moderate amount of threat and forces the target to focus attacks on you for 6 sec.", "Rare", 10, nil, 1, false, 16, true },
  { "Spell", "Ritual of Summoning", 698, 40055, "Warlock", "", "Begins a ritual that creates a summoning portal. The summoning portal can be used by 2 party or raid members to summon a targeted party or raid member.      The ritual portal requires the caster and 2 additional party or raid members to complete.     In order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete.     Cannot be used in High-Risk mode", "Normal", 187, nil, 0, false, 20, true },
  { "Spell", "Curse of Weakness", 702, 40056, "Warlock", "Rank 1", "Target's attack power is reduced by 21 and armor is reduced by 5% for 2 min. Only one Curse per Warlock can be active on any one target.  Does not stack with other similar effects.", "Uncommon", 156, nil, 0, false, 1, true },
  { "Spell", "Garrote", 703, 40057, "Rogue", "Rank 1", "When attacking from stealth, inflicts 18 damage to an enemy every 3 sec. for 18 sec and silences the enemy for 2 sec. Awards 1 combo point.", "Normal", 50, nil, 3, false, 12, true },
  { "Spell", "Banish", 710, 40058, "Warlock", "Rank 1", "Banishes the enemy target, preventing all action but making it invulnerable for up to 20 sec. Only one target can be banished at a time. Casting Banish on a banished target will cancel the spell. Only works on Demons and Elementals.    Lasts 6 seconds on players.", "Rare", 124, nil, 0, false, 28, true },
  { "Spell", "Tranquility", 740, 40059, "Druid", "Rank 1", "Heals all nearby group members for 147 every 1.95 seconds for 7.81 sec.  Caster must channel to maintain the spell.", "Epic", 1093, nil, 0, false, 20, true },
  { "Spell", "Health Funnel", 755, 40060, "Warlock", "Rank 1", "Gives 12 health to the caster's pet every second for 9.77 sec as long as the caster channels.", "Normal", 5, nil, -2, false, 10, true },
  { "Spell", "Conjure Mana Gem", 759, 40061, "Mage", "Rank 1", "Conjures a mana agate that can be used to instantly restore 314 to 337 mana. 3 charges.", "Rare", 1171, nil, 0, false, 28, true },
  { "Spell", "Faerie Fire", 770, 40062, "Druid", "", "Decrease the armor of the target by 5% for 40 sec (20 seconds on players). While affected, the target cannot stealth or turn invisible.   Does not stack with other similar effects.", "Rare", 124, nil, 0, false, 14, true },
  { "Spell", "Rend", 772, 40063, "Warrior", "Rank 1", "Wounds the target causing them to bleed for 25 damage plus an additional 177 (based on weapon damage) over 15 sec.", "Normal", 10, nil, 1, false, 1, true },
  { "Spell", "Rejuvenation", 774, 40064, "Druid", "Rank 1", "Heals the target for 25 over 15 sec.", "Normal", 281, nil, 0, false, 1, true },
  { "Spell", "Disengage", 781, 40066, "Hunter", "", "You attempt to disengage from combat, leaping backwards.  This ability is usable while shapeshifted.", "Legendary", 78, nil, 0, false, 16, true },
  { "Spell", "Travel Form", 783, 40067, "Druid", "Shapeshift", "Shapeshift into travel form, increasing movement speed by 40%.  Also protects the caster from Polymorph effects. Only usable outdoors.  The act of shapeshifting frees the caster of movement impairing and Polymorph effects.", "Legendary", 203, nil, 0, false, 16, true },
  { "Spell", "Cleave", 845, 40068, "Warrior", "Rank 1", "A sweeping attack that does your weapon damage plus 13 to the target and his nearest ally.", "Normal", 20, nil, 1, false, 16, true },
  { "Spell", "Hammer of Justice", 853, 40069, "Paladin", "", "Stuns the target for 3 sec and interrupts non-player spellcasting for 3 sec.", "Epic", 46, nil, 0, false, 10, true },
  { "Spell", "Shield Wall", 871, 40070, "Warrior", "", "Reduces all damage taken by 60% for 12 sec.", "Legendary", 0, nil, 1, false, 28, true },
  { "Spell", "Exorcism", 879, 40071, "Paladin", "Rank 1", "Causes 349 to 363 Holy damage to an enemy target. Using Exorcism on an Undead or Demon will stun the target for 3 sec.", "Normal", 124, nil, 0, false, 20, true },
  { "Spell", "Pick Pocket", 921, 40072, "Rogue", "", "Pick the target's pocket, taking loot from them!", "Normal", 0, nil, 0, false, 10, true },
  { "Spell", "Shadow Protection", 976, 40073, "Priest", "Rank 1", "Increases the target's resistance to Shadow spells by 30 for 30 min.", "Uncommon", 484, nil, 0, false, 30, true },
  { "Spell", "Curse of Agony", 980, 40074, "Warlock", "Rank 1", "Curses the target with agony, causing 36 Shadow damage over 24 sec.  This damage is dealt slowly at first, and builds up as the Curse reaches its full duration. Only one Curse per Warlock can be active on any one target.", "Normal", 156, nil, 0, false, 1, true },
  { "Spell", "Eyes of the Beast", 1002, 40075, "Hunter", "", "Take direct control of your pet and see through its eyes for 1 min.  This ability is usable while shapeshifted.", "Normal", 15, nil, 0, false, 14, true },
  { "Spell", "Amplify Magic", 1008, 40076, "Mage", "Rank 1", "Amplifies magic used against the targeted party member, increasing magic damage taken by 5% and healing spells by 5%.  Lasts 10 min.  This ability is usable while shapeshifted.", "Uncommon", 421, nil, 0, false, 18, true },
  { "Spell", "Hand of Protection", 1022, 40077, "Paladin", "", "A targeted party or raid member is protected from all physical attacks, Interrupt and Silence mechanics for 6 sec, but during that time they cannot attack or use physical abilities. This also removes any Stun effects on use.  Once protected, the target cannot be targeted by Divine Shield, Hand of Protection or Lay on Hands again for 2 min.    Cannot be used within 30 sec of using Avenging Wrath.", "Legendary", 93, nil, 0, false, 10, true },
  { "Spell", "Hand of Salvation", 1038, 40078, "Paladin", "", "Places a Hand on the party or raid member, reducing their total threat by 2% every 1 sec. for 10 sec.  Players may only have one Hand on them per Paladin at any one time.", "Epic", 93, nil, 0, false, 26, true },
  { "Spell", "Hand of Freedom", 1044, 40079, "Paladin", "", "Places a Hand on the friendly target, granting immunity to movement impairing effects for 6 sec.", "Legendary", 93, nil, 0, false, 18, true },
  { "Spell", "Chain Heal", 1064, 40080, "Shaman", "Rank 1", "Heals the friendly target for 202 to 224, then jumps to heal additional nearby targets. If cast on a party member, the heal will only jump to other party members. Each jump reduces the effectiveness of the heal by 40%. Heals 3 total targets.", "Normal", 296, nil, 0, false, 40, true },
  { "Spell", "Aquatic Form", 1066, 40081, "Druid", "Shapeshift", "Shapeshift into aquatic form, increasing swim speed by 50% and allowing the druid to breathe underwater. Also protects the caster from Polymorph effects.", "Normal", 203, nil, 0, false, 16, true },
  { "Spell", "Rip", 1079, 40082, "Druid", "Rank 1", "Finishing move that causes damage over time.  Damage increases per combo point:     1 point  : 94 damage over 12 sec     2 points: 183 damage over 12 sec     3 points: 271 damage over 12 sec     4 points: 359 damage over 12 sec     5 points: 448 damage over 12 sec", "Normal", 30, nil, 3, false, 1, true },
  { "Spell", "Temporary Enslaved Demon", 1098, 40084, "Warlock", "Rank 1", "Enslaves the target demon, up to level 45, forcing it to do your bidding. While enslaved, the time between the demon's attacks is increased by 30% and its casting speed is slowed by 20%. Lasts up to 5 min.", "Rare", 421, nil, 0, false, 30, true },
  { "Spell", "Drain Soul", 1120, 40085, "Warlock", "Rank 1", "Drains the soul of the target dealing 55 Shadow damage over 14.65 sec. Deals Four times damage to targets at or below 25% health.    If the target dies while being drained, and yields experience or honor, the caster gains a Soul Shard.  Each time the Drain Soul damages the target, it also has a chance to generate a Soul Shard.  Soul Shards are required for other spells.    Deals three times damage to players.", "Normal", 218, nil, 0, false, 10, true },
  { "Spell", "Inferno", 1122, 40086, "Warlock", "Summon", "Summons a meteor from the Twisting Nether, causing 200 Fire damage and stunning all enemy targets in the area for 2 sec. An Infernal rises from the crater, under the command of the caster for 1 min.", "Epic", 1249, nil, 0, false, 34, true },
  { "Spell", "Hunter's Mark", 1130, 40088, "Hunter", "Rank 1", "Places the Hunter's Mark on the target, increasing the ranged attack power of all attackers against that target by 20.    The marked target can always be seen by the hunter whether it stealths or turns invisible, and appears on the mini-map. Lasts for 5 min.", "Rare", 31, nil, 0, false, 1, true },
  { "Spell", "Purify", 1152, 40089, "Paladin", "", "Purifies the friendly target, removing 1 disease effect and 1 poison effect.", "Normal", 93, nil, 0, false, 10, true },
  { "Spell", "Challenging Shout", 1161, 40090, "Warrior", "", "Forces all enemies within 10 yards to focus attacks on you for 6 sec.", "Normal", 5, nil, 1, false, 26, true },
  { "Spell", "Power Word: Fortitude", 1243, 40091, "Priest", "Rank 1", "Power infuses the target, increasing their Stamina by 3 for 30 min.   Does not stack with other similar effects.", "Uncommon", 421, nil, 0, false, 1, true },
  { "Spell", "Arcane Explosion", 1449, 40092, "Mage", "Rank 1", "Causes an explosion of arcane magic around the caster, causing 30 to 35 Arcane damage to all targets within 10 yards.", "Normal", 343, nil, 0, false, 12, true },
  { "Spell", "Life Tap", 1454, 40093, "Warlock", "Rank 1", "Converts 65 health into 70 mana.  Spell power increases the amount of mana returned.", "Rare", 0, nil, 0, false, 1, true },
  { "Spell", "Arcane Intellect", 1459, 40094, "Mage", "Rank 1", "Increases the target's Intellect by 2 and spell power by 2 for 30 min.   Does not stack with other similar effects.", "Uncommon", 484, nil, 0, false, 1, true },
  { "Spell", "Mana Shield", 1463, 40095, "Mage", "Rank 1", "Absorbs 120 damage, draining mana instead. Drains 1.5 mana per damage absorbed. Lasts 1 min.", "Epic", 109, nil, 0, false, 20, true },
  { "Spell", "Slam", 1464, 40096, "Warrior", "Rank 1", "Slams the opponent, causing 100% weapon damage plus 17.", "Normal", 15, nil, 1, false, 1, true },
  { "Spell", "Curse of the Elements", 1490, 40097, "Warlock", "Rank 1", "Curses the target for 5 min, reducing Arcane, Fire, Frost, Nature, and Shadow resistances by 45 and increasing magic damage taken by 8%.   Does not stack with other similar effects.", "Epic", 156, nil, 0, false, 32, true },
  { "Spell", "Mongoose Bite", 1495, 40098, "Hunter", "Rank 1", "Attack the enemy for 218 damage.", "Normal", 46, nil, 0, false, 1, true },
