  { "Spell", "Scare Beast", 1513, 40100, "Hunter", "Rank 1", "Scares a beast, causing it to run in fear for up to 10 sec.  Damage caused may interrupt the effect. Only one beast can be feared at a time.  This ability is usable while shapeshifted.", "Rare", 31, nil, 0, false, 10, true },
  { "Spell", "Fire Nova", 1535, 40101, "Shaman", "Rank 1", "Causes your active Fire Totem to emit a wave of flames, inflicting 53 to 62 Fire damage to enemies within 10 yards of the totem.    This ability is usable while shapeshifted.", "Normal", 281, nil, 0, false, 10, true },
  { "Spell", "Flare", 1543, 40102, "Hunter", "", "Exposes all hidden and invisible enemies within 10 yards of the targeted area for 20 sec.", "Rare", 31, nil, 0, false, 32, true },
  { "Spell", "Whirlwind", 1680, 40103, "Warrior", "", "In a whirlwind of steel you attack up to 4 enemies within 8 yards, causing 100% weapon damage plus 0 to 1 from both melee weapons to each enemy.", "Normal", 25, nil, 1, false, 14, true },
  { "Spell", "Levitate", 1706, 40104, "Priest", "", "Allows the friendly party or raid target to levitate, floating a few feet above the ground.  While levitating, the target will fall at a reduced speed and travel over water.  Any damage will cancel the effect.  Lasts 2 min.  This ability is usable while shapeshifted.", "Normal", 46, nil, 0, false, 34, true },
  { "Spell", "Curse of Tongues", 1714, 40105, "Warlock", "", "Forces the target to speak in Demonic, increasing the casting time of all spells by 25%. Lasts 30 sec.    Lasts 12 seconds on players.   Does not stack with other similar effects.", "Rare", 62, nil, 0, false, 26, true },
  { "Spell", "Hamstring", 1715, 40106, "Warrior", "", "Attack the enemy for 206 damage and maims the enemy, reducing movement speed by 50% for 15 sec. Lasts 10sec vs players.", "Rare", 10, nil, 1, false, 10, true },
  { "Spell", "Recklessness", 1719, 40107, "Warrior", "", "Your attack speed is increased by 30%, but all damage taken is increased by 10%. Your next 3 non-periodic Warrior abilities have an additional 100% to critically hit, 3 yards extra range and will cause you to charge toward your enemy if not in melee range already. Lasts for 8 sec.    Charges are not consumed versus monsters.    While active, the duration of stun and movement impairing effects on you is reduced by 50%.", "Epic", 0, nil, 1, false, 34, true },
  { "Spell", "Distract", 1725, 40108, "Rogue", "", "Throws a distraction, attracting the attention of all nearby monsters for 10 seconds.  Does not break stealth.", "Normal", 30, nil, 3, false, 10, true },
  { "Spell", "Sinister Strike", 1752, 40109, "Rogue", "Rank 1", "An instant strike that causes 3 damage in addition to 100% of your normal weapon damage (85% if a Two-Handed weapon is equipped). Awards 1 combo point.", "Normal", 45, nil, 3, false, 1, true },
  { "Spell", "Kick", 1766, 40110, "Rogue", "", "A quick kick that interrupts spellcasting and prevents any spell in that school from being cast for 4 sec.     This ability shares a cooldown with other interrupts.", "Epic", 25, nil, 3, false, 12, true },
  { "Spell", "Gouge", 1776, 40111, "Rogue", "", "Causes 216 damage, incapacitating the opponent for 4 sec, and turns off your attack.  Target must be facing you.  Any damage caused will revive the target. Awards 1 combo point.", "Epic", 45, nil, 3, false, 10, true },
  { "Spell", "Stealth", 1784, 40112, "Rogue", "", "Allows you to sneak around, but reduces your speed by 30%. Removes invulnerabilities when used. Lasts until cancelled.", "Epic", 0, nil, 0, false, 1, true },
  { "Spell", "Pick Lock", 1804, 40113, "Rogue", "", "Allows opening of locked chests and doors.", "Normal", 0, nil, 0, false, 12, true },
  { "Spell", "Rake", 1822, 40114, "Druid", "Rank 1", "Rake the target for 15 bleed damage and an additional 247 damage over 9 sec. Awards 1 combo point.", "Normal", 40, nil, 3, false, 18, true },
  { "Spell", "Cheap Shot", 1833, 40115, "Rogue", "", "Stuns the target for 4 sec. Must be stealthed. Awards 2 combo points.", "Epic", 60, nil, 3, false, 26, true },
  { "Spell", "Disarm Trap", 1842, 40116, "Rogue", "", "Disarm a hostile trap.", "Uncommon", 0, nil, 0, false, 30, true },
  { "Spell", "Dash", 1850, 40117, "Druid", "Rank 1", "Increases movement speed by 50% while in Cat Form for 15 sec. Does not break prowling.", "Legendary", 0, nil, 3, false, 12, true },
  { "Spell", "Vanish", 1856, 40118, "Rogue", "Rank 1", "Allows you to vanish from sight, entering an improved stealth mode for 10 sec.  Also breaks movement impairing effects.", "Epic", 0, nil, 3, false, 22, true },
  { "Spell", "Safe Fall", 1860, 40119, "Rogue", "Passive", "Reduces damage from falling.", "Normal", 0, nil, 0, false, 40, true },
  { "Spell", "Rupture", 1943, 40120, "Rogue", "Rank 1", "Finishing move that causes damage over time.  Lasts longer per combo point:     1 point  : 56 damage over 8 sec     2 points: 141 damage over 10 sec     3 points: 301 damage over 12 sec     4 points: 563 damage over 14 sec     5 points: 949 damage over 16 sec", "Normal", 25, nil, 3, false, 20, true },
  { "Spell", "Hellfire", 1949, 40121, "Warlock", "Rank 1", "Ignites the area surrounding the caster, causing 87 periodic Fire damage to herself and 87 periodic Fire damage to all nearby enemies every 0.98 sec. Lasts 14.65 sec.", "Normal", 999, nil, 0, false, 30, true },
  { "Spell", "Blink", 1953, 40122, "Mage", "", "Teleports the caster 20 yards forward, unless something is in the way.  Also frees the caster from stuns and bonds.", "Legendary", 328, nil, 0, false, 16, true },
  { "Spell", "Feint", 1966, 40123, "Rogue", "Rank 1", "Performs a feint, causing no damage but lowering your threat by a large amount, making the enemy less likely to attack you.  In addition, reduces the damage you take from area of effect attacks by 20% for 6 sec.", "Rare", 20, nil, 3, false, 12, true },
  { "Spell", "Serpent Sting", 1978, 40124, "Hunter", "Rank 1", "Stings the target, causing 191 Nature damage over 15 sec.", "Normal", 140, nil, 0, false, 1, true },
  { "Spell", "Resurrection", 2006, 40125, "Priest", "Rank 1", "Brings a dead player back to life with 70 health and 135 mana.  Cannot be cast when in combat.", "Normal", 937, nil, 0, false, 10, true },
  { "Spell", "Ancestral Spirit", 2008, 40126, "Shaman", "Rank 1", "Returns the spirit to the body, restoring a dead target to life with 65 health and 120 mana.  Cannot be cast when in combat.", "Normal", 1124, nil, 0, false, 10, true },
  { "Spell", "Greater Heal", 2050, 40127, "Priest", "Rank 1", "A slow casting spell that heals a single target for 29 to 36.", "Normal", 499, nil, 0, false, 1, true },
  { "Spell", "Flash Heal", 2061, 40128, "Priest", "Rank 1", "Heals a friendly target for 206 to 232.", "Normal", 281, nil, 0, false, 20, true },
