  { "Spell", "Blind", 2094, 40130, "Rogue", "", "Blinds the target, causing it to wander disoriented for up to 10 sec.  Any damage caused will remove the effect.", "Epic", 30, nil, 3, false, 34, true },
  { "Spell", "Mind Vision", 2096, 40131, "Priest", "Rank 1", "Allows the caster to see through the target's eyes for 1 min.  This ability is usable while shapeshifted.", "Normal", 46, nil, 0, false, 22, true },
  { "Spell", "Eviscerate", 2098, 40132, "Rogue", "Rank 1", "Finishing move that causes damage per combo point:     1 point  : 28-32 damage     2 points: 95-99 damage     3 points: 203-207 damage     4 points: 352-356 damage     5 points: 543-547 damage", "Normal", 35, nil, 3, false, 1, true },
  { "Spell", "Flamestrike", 2120, 40133, "Mage", "Rank 1", "Calls down a pillar of fire, burning all enemies within the area for 52 to 68 Fire damage and an additional 48 Fire damage over 8 sec.", "Normal", 546, nil, 0, false, 16, true },
  { "Spell", "Fire Blast", 2136, 40134, "Mage", "Rank 1", "Blasts the enemy for 25 to 29 Fire damage.", "Normal", 265, nil, 0, false, 1, true },
  { "Spell", "Counterspell", 2139, 40135, "Mage", "", "Counters the enemy's spell cast, preventing any spell from that school of magic from being cast for 8 sec. Generates a high amount of threat.     This ability shares a cooldown with other interrupts.", "Epic", 140, nil, 0, false, 16, true },
  { "Spell", "Earthbind Totem", 2484, 40136, "Shaman", "", "Summons an Earthbind Totem with 5 health at the feet of the caster for 45 sec that slows the movement speed of enemies within 10 yards.  This ability is usable while shapeshifted.", "Epic", 78, nil, 0, false, 10, true },
  { "Spell", "Shield Block", 2565, 40137, "Warrior", "", "Increases your chance to block and block value by 100% for 10 sec.", "Rare", 0, nil, 1, false, 1, true },
  { "Spell", "Hibernate", 2637, 40138, "Druid", "Rank 1", "Forces the enemy target to sleep for up to 20 sec.  Any damage will awaken the target. Only one target can be forced to hibernate at a time. Only works on Beasts and Dragonkin.", "Rare", 109, nil, 0, false, 18, true },
  { "Spell", "Multi-Shot", 2643, 40139, "Hunter", "Rank 1", "Fires several missiles, hitting 3 targets for 100% weapon damage.", "Normal", 140, nil, 0, false, 18, true },
  { "Spell", "Ghost Wolf", 2645, 40140, "Shaman", "", "Turns the caster into a Ghost Wolf, increasing speed by 30%. As a Ghost Wolf, effects that reduce movement speed may not bring you below your normal movement speed. Only usable outdoors.", "Legendary", 93, nil, 0, false, 12, true },
  { "Spell", "Remove Curse", 2782, 40142, "Druid", "", "Dispels 1 Curse from a friendly target.", "Rare", 124, nil, 0, false, 24, true },
  { "Spell", "Holy Wrath", 2812, 40143, "Paladin", "Rank 1", "Sends bolts of holy power in all directions, causing 238 to 250 Holy damage and stunning all Undead and Demon targets within 10 yards for 3 sec.", "Normal", 312, nil, 0, false, 26, true },
  { "Spell", "Bloodlust", 2825, 40144, "Shaman", "", "Increases melee and ranged attack speed by 30% and casting speed by 20% for all party and raid members.  Lasts 40 sec.  After the completion of this effect, those affected will become Sated and unable to benefit from Bloodlust again for 10 min.  This ability is usable while shapeshifted.", "Legendary", 406, nil, 0, false, 50, true },
  { "Spell", "Detect Traps", 2836, 40145, "Rogue", "Passive", "Greatly increased chance to detect traps.", "Uncommon", 0, nil, 0, false, 24, true },
  { "Spell", "Abolish Poison", 2893, 40147, "Druid", "", "Attempts to cure 1 poison effect on the target, and 1 more poison effect every 3 seconds for 12 sec.", "Rare", 203, nil, 0, false, 26, true },
  { "Spell", "Fire Elemental Totem", 2894, 40148, "Shaman", "", "Summons an elemental totem that calls forth a greater fire elemental to rain destruction on the caster's enemies.  Lasts 2 min.  This ability is usable while shapeshifted.", "Epic", 359, nil, 0, false, 40, true },
  { "Spell", "Soothe Animal", 2908, 40149, "Druid", "Rank 1", "Soothes the target beast, reducing the range at which it will attack you by 10 yards and reducing its attack speed by 20%. Only affects Beast and Dragonkin targets level 40 or lower. Lasts 30 sec.", "Normal", 93, nil, 0, false, 22, true },
  { "Spell", "Starfire", 2912, 40150, "Druid", "Rank 1", "Causes 127 to 155 Arcane damage to the target.", "Normal", 249, nil, 0, false, 20, true },
  { "Spell", "Devouring Plague", 2944, 40151, "Priest", "Rank 1", "Afflicts the target with a disease that causes 152 Shadow damage over 24 sec. 15% of damage caused by the Devouring Plague heals the caster. This spell can only affect one target at a time.", "Normal", 390, nil, 0, false, 20, true },
  { "Spell", "Scorch", 2948, 40152, "Mage", "Rank 1", "Scorch the enemy for 56 to 69 Fire damage.", "Normal", 124, nil, 0, false, 22, true },
  { "Spell", "Raptor Strike", 2973, 40153, "Hunter", "Rank 1", "A strong attack that increases melee damage by 5.", "Normal", 62, nil, 0, false, 1, true },
  { "Spell", "Wing Clip", 2974, 40154, "Hunter", "", "Maims the enemy, dealing 307 damage and reducing the target's movement speed by 50% for 10 sec.", "Rare", 93, nil, 0, false, 12, true },
  { "Spell", "Sprint", 2983, 40155, "Rogue", "Rank 1", "Increases your movement speed by 50% for 15 sec.  Does not break stealth.", "Legendary", 0, nil, 3, false, 10, true },
  { "Spell", "Viper Sting", 3034, 40156, "Hunter", "", "Stings the target, draining 4% mana over 8 sec (up to a maximum of 8% of the caster's maximum mana), and energizing you equal to the amount drained. Only one Sting per Hunter can be active on any one target.", "Rare", 124, nil, 0, false, 36, true },
  { "Spell", "Scorpid Sting", 3043, 40157, "Hunter", "", "Stings the target, reducing chance to hit with melee and ranged attacks by 3% for 20 sec. Only one Sting per Hunter can be active on any one target.    Does not stack with other similar effects.", "Uncommon", 171, nil, 0, false, 22, true },
  { "Spell", "Arcane Shot", 3044, 40158, "Hunter", "Rank 1", "An instant shot that causes 98 Arcane damage.", "Normal", 78, nil, 0, false, 1, true },
  { "Spell", "Rapid Fire", 3045, 40159, "Hunter", "", "Increases ranged attack speed by 40% for 15 sec.", "Epic", 46, nil, 0, false, 26, true },
  { "Spell", "Intervene", 3411, 40160, "Warrior", "", "Run at high speed towards a party or raid member, intercepting the next melee or ranged attack made against them and taunts up to 3 enemies attacking the target to attack you instead.", "Epic", 10, nil, 1, false, 30, true },
  { "Spell", "Cleanse", 4987, 40161, "Paladin", "", "Cleanses a friendly target, removing 1 poison effect, 1 disease effect and 1 magic effect.", "Epic", 93, nil, 0, false, 30, true },
  { "Spell", "Concussive Shot", 5116, 40162, "Hunter", "", "A shot that deals 90% weapon damage and dazes the target, slowing movement speed by 50% for 4 sec.", "Epic", 93, nil, 0, false, 10, true },
  { "Spell", "Drain Mana", 5138, 40163, "Warlock", "", "Transfers 3% of target's maximum mana every 0.98 sec from the target to the caster (up to a maximum of 6% of the caster's maximum mana every 0.98 sec).  Lasts 4.88 sec.", "Rare", 265, nil, 0, false, 24, true },
  { "Spell", "Arcane Missiles", 5143, 40164, "Mage", "Rank 1", "Launches Arcane Missiles at the enemy, causing 19 to 20 Arcane damage every 0.98 sec for 2.93 sec.", "Normal", 484, nil, 0, false, 1, true },
  { "Spell", "Wrath", 5176, 40165, "Druid", "Rank 1", "Causes 18 to 21 Nature damage to the target.", "Normal", 171, nil, 0, false, 1, true },
  { "Spell", "Healing Touch", 5185, 40166, "Druid", "Rank 1", "Heals a friendly target for 24 to 33.", "Normal", 515, nil, 0, false, 1, true },
  { "Spell", "Bash", 5211, 40168, "Druid", "Rank 1", "Stuns the target for 2 sec and interrupts non-player spellcasting for 3 sec.", "Epic", 10, nil, 1, false, 12, true },
  { "Spell", "Prowl", 5215, 40169, "Druid", "", "Allows the Druid to prowl around, but reduces your movement speed by 30%. Lasts until cancelled.", "Epic", 0, nil, 3, false, 10, true },
  { "Spell", "Tiger's Fury", 5217, 40170, "Druid", "Rank 1", "Adds 10 damage to your attacks and increases damage by 5% for 6 sec.", "Rare", 0, nil, 3, false, 24, true },
  { "Spell", "Shred", 5221, 40171, "Druid", "Rank 1", "Shred the target, causing 225% damage plus 15 to the target. Must be behind the target. Awards 1 combo point.  Effects which increase Bleed damage also increase Shred damage.", "Normal", 60, nil, 3, false, 10, true },
  { "Spell", "Intimidating Shout", 5246, 40173, "Warrior", "", "The caster shouts, causing up to 5 enemies within 8 yards to cower in fear for 8 seconds. The targeted enemy will be unable to move while cowering.  This ability is usable while shapeshifted.", "Epic", 25, nil, 1, false, 22, true },
  { "Spell", "Evasion", 5277, 40174, "Rogue", "Rank 1", "Increases your dodge chance by 50% and reduces the chance ranged attacks hit you by 50%. Lasts 15 sec.     This ability is usable while shapeshifted.", "Epic", 0, nil, 3, false, 10, true },
  { "Spell", "Execute", 5308, 40175, "Warrior", "Rank 1", "Attempt to finish off a wounded foe, causing 371 damage and converting each extra point of rage into 2 additional damage (up to a maximum cost of 30 rage). Only usable on enemies that have less than 20% health.", "Normal", 15, nil, 1, false, 16, true },
  { "Spell", "Feign Death", 5384, 40176, "Hunter", "", "Feign death which may trick enemies into ignoring you. Raid Bosses will see through this trick, but staying feigned will deceive them. Lasts up to 6 min.  This ability is usable while shapeshifted.", "Epic", 46, nil, 0, false, 30, true },
  { "Spell", "Howl of Terror", 5484, 40177, "Warlock", "Rank 1", "Howl, causing 5 enemies within 10 yds to flee in terror for 6 sec. Damage caused may interrupt the effect.", "Epic", 124, nil, 0, false, 30, true },
  { "Spell", "Conjure Water", 5504, 40178, "Mage", "Rank 1", "Conjures 20 bottles of water, providing the mage and her allies with something to drink.  Conjured items disappear if logged out for more than 15 minutes.", "Normal", 624, nil, 0, false, 1, true },
  { "Spell", "Searing Pain", 5676, 40179, "Warlock", "Rank 1", "Inflict searing pain on the enemy target, causing 35 to 43 Fire damage. Causes a high amount of threat.", "Normal", 124, nil, 0, false, 16, true },
  { "Spell", "Unending Breath", 5697, 40180, "Warlock", "", "Allows the target to breathe underwater for 30 min.  This ability is usable while shapeshifted.", "Normal", 31, nil, 0, false, 16, true },
  { "Spell", "Rain of Fire", 5740, 40181, "Warlock", "Rank 1", "Calls down a fiery rain to burn enemies in the area of effect for 488 Fire damage over 7.81 sec.", "Normal", 890, nil, 0, false, 20, true },
  { "Spell", "Fear", 5782, 40182, "Warlock", "Rank 1", "Strikes fear in the enemy, causing it to run in fear for up to 10 sec. (6 seconds on players). Damage caused may interrupt the effect. Only 1 target can be feared at a time.", "Epic", 187, nil, 0, false, 10, true },
  { "Spell", "Shiv", 5938, 40183, "Rogue", "", "Performs an instant off-hand weapon attack that automatically applies the poison from your off-hand weapon to the target.  Slower weapons require more Energy. Awards 1 combo point.", "Normal", 45, nil, 3, false, 40, true },
  { "Spell", "Create Healthstone", 6201, 40186, "Warlock", "Rank 1", "Creates a Minor Healthstone that can be used to instantly restore 100 health.  Conjured items disappear if logged out for more than 15 minutes.  This ability is usable while shapeshifted.", "Uncommon", 827, nil, 0, false, 10, true },
  { "Spell", "Thunder Clap", 6343, 40187, "Warrior", "Rank 1", "Blasts nearby enemies dealing 15 damage and increasing the time between their attacks by 10% for 10 sec. This ability causes additional threat.", "Normal", 20, nil, 1, false, 1, true },
  { "Spell", "Fear Ward", 6346, 40188, "Priest", "", "Wards the friendly target against Fear and Horror effects. The next Fear effect used against the target will fail, using up the ward.  Lasts 3 min.", "Epic", 46, nil, 0, false, 20, true },
  { "Spell", "Soul Fire", 6353, 40189, "Warlock", "Rank 1", "Burn the enemy's soul, causing 405 Fire damage.", "Normal", 140, nil, 0, false, 26, true },
  { "Spell", "Track Humanoids (Cat Form)", 5225, 40190, "Druid", "", "Shows the location of all nearby humanoids on the minimap. Only one form of tracking can be active at a time.", "Normal", 0, nil, 3, false, 32, true },
  { "Spell", "Pummel", 6552, 40191, "Warrior", "", "Pummel the target, interrupting spellcasting and preventing spells of that school from being cast for 4 sec.    This ability shares a cooldown with other interrupts.", "Epic", 10, nil, 1, false, 30, true },
  { "Spell", "Revenge", 6572, 40192, "Warrior", "Rank 1", "Instantly counterattack an enemy for 280 to 299 damage.  Revenge is only usable after the warrior blocks, dodges or parries an attack.", "Normal", 5, nil, 1, false, 12, true },
  { "Spell", "Sap", 6770, 40193, "Rogue", "Rank 1", "Incapacitates the target for up to 25 sec (10 seconds on players).  Must be stealthed. Only works on Humanoids that are not in combat.  Any damage caused will revive the target. Only 1 target may be sapped at a time.", "Epic", 65, nil, 3, false, 10, true },
  { "Spell", "Ravage", 6785, 40194, "Druid", "Rank 1", "Ravage the target, causing 385% damage plus 77 to the target. Must be prowling and behind the target. Awards 1 combo point.", "Normal", 60, nil, 3, false, 32, true },
  { "Spell", "Death Coil", 6789, 40195, "Warlock", "Rank 1", "Causes the enemy target to run in horror for 3 sec and causes 261 to 262 Shadow damage. The caster gains 300% of the damage caused in health.", "Epic", 359, nil, 0, false, 40, true },
  { "Spell", "Maul", 6807, 40196, "Druid", "Rank 1", "A strong attack that increases melee damage by 18 and causes a high amount of threat. Effects which increase Bleed damage also increase Maul damage.", "Normal", 15, nil, 1, false, 1, true },
  { "Spell", "Hand of Sacrifice", 6940, 40197, "Paladin", "", "Places a Hand on the party or raid member, transferring 30% damage taken to the caster.  Lasts 12 sec or until the caster has transferred 100% of their maximum health.", "Epic", 93, nil, 0, false, 36, true },
  { "Spell", "Redemption", 7328, 40198, "Paladin", "Rank 1", "Brings a dead player back to life with 65 health and 120 mana.  Cannot be cast when in combat.", "Normal", 999, nil, 0, false, 12, true },
  { "Spell", "Overpower", 7384, 40199, "Warrior", "", "Instantly overpower the enemy, causing 100% weapon damage. Only usable after the target dodges. The Overpower cannot be blocked, dodged or parried.", "Normal", 5, nil, 1, false, 10, true },
  { "Spell", "Lesser Healing Wave", 8004, 40200, "Shaman", "Rank 1", "Heals a friendly target for 112 to 126.", "Normal", 234, nil, 0, false, 20, true },
  { "Spell", "Earth Shock", 8042, 40201, "Shaman", "Rank 1", "Instantly shocks the target with concussive force, causing 17 to 19 Nature damage and reducing melee attack speed by 10% for 8 sec.   Does not stack with other similar effects.  This ability shares a cooldown with Shaman Shock spells.", "Normal", 234, nil, 0, false, 1, true },
  { "Spell", "Flame Shock", 8050, 40202, "Shaman", "Rank 1", "Instantly sears the target with fire, causing 25 Fire damage immediately and 42 Fire damage over 17.58 sec. This periodic damage may critically strike and will occur more rapidly based on the caster's spell haste.   This ability shares a cooldown with Shaman Shock spells.", "Normal", 265, nil, 0, false, 10, true },
  { "Spell", "Frost Shock", 8056, 40203, "Shaman", "Rank 1", "Instantly shocks the target with frost, causing 95 to 101 Frost damage and slowing movement speed by 50%. Lasts 8 sec. Causes a high amount of threat.  This ability shares a cooldown with other Shaman Shock spells.", "Epic", 281, nil, 0, false, 20, true },
  { "Spell", "Mind Blast", 8092, 40204, "Priest", "Rank 1", "Blasts the target for 42 to 46 Shadow damage.", "Normal", 265, nil, 0, false, 10, true },
  { "Spell", "Psychic Scream", 8122, 40205, "Priest", "Rank 1", "The caster lets out a psychic scream, causing 2 enemies within 8 yards to flee for 6 sec.  Damage caused may interrupt the effect.", "Epic", 234, nil, 0, false, 10, true },
  { "Spell", "Mana Burn", 8129, 40206, "Priest", "", "Destroy 10% of the target's mana (up to a maximum of 20% of your own maximum mana). For each mana destroyed in this way, the target takes 0.5 Shadow damage.", "Rare", 218, nil, 0, false, 16, true },
  { "Spell", "Tremor Totem", 8143, 40207, "Shaman", "", "Summons a Tremor Totem with 5 health at the feet of the caster that shakes the ground around it, removing Fear, Charm and Sleep effects from party members within 30 yards.  Lasts 5 min.  This ability is usable while shapeshifted.", "Epic", 31, nil, 0, false, 18, true },
  { "Spell", "Cleansing Totem", 8170, 40208, "Shaman", "", "Summons a Cleansing Totem with 5 health at the feet of the caster that attempts to remove 1 disease and 1 poison effect from party members within 30 yards every 3 seconds.  Lasts 5 min.  This ability is usable while shapeshifted.", "Epic", 124, nil, 0, false, 34, true },
  { "Spell", "Grounding Totem", 8177, 40209, "Shaman", "", "Summons a Grounding Totem with 5 health at the feet of the caster that will redirect one harmful spell from the caster to itself, destroying the totem. Will not redirect area of effect spells. Lasts 45 sec.  This ability is usable while shapeshifted.", "Epic", 78, nil, 0, false, 30, true },
  { "Spell", "Ambush", 8676, 40210, "Rogue", "Rank 1", "Ambush the target, causing 275% weapon damage plus 77 to the target. Must be stealthed and behind the target. Requires a dagger in the main hand. Awards 2 combo points.", "Normal", 50, nil, 3, false, 16, true },
  { "Spell", "Moonfire", 8921, 40211, "Druid", "Rank 1", "Burns the enemy for 9 to 11 Arcane damage and then an additional 9 Arcane damage over 9 sec.", "Normal", 328, nil, 0, false, 1, true },
  { "Spell", "Regrowth", 8936, 40212, "Druid", "Rank 1", "Heals a friendly target for 53 to 60 and another 63 over 21 sec.", "Normal", 452, nil, 0, false, 12, true },
  { "Spell", "Cure Poison", 8946, 40213, "Druid", "", "Cures 1 poison effect on the target.", "Uncommon", 203, nil, 0, false, 14, true },
  { "Spell", "Cower", 8998, 40214, "Druid", "Rank 1", "Cower, causing no damage but lowering your threat a large amount, making enemies less likely to attack you.", "Uncommon", 20, nil, 3, false, 28, true },
  { "Spell", "Pounce", 9005, 40215, "Druid", "Rank 1", "Pounce, stunning the target for 3.50 sec and causing 270 damage over 18 sec. Must be prowling. Awards 1 combo point.", "Normal", 50, nil, 3, false, 36, true },
  { "Spell", "Shackle Undead", 9484, 40216, "Priest", "Rank 1", "Shackles the target undead enemy for up to 30 sec. The shackled unit is unable to move, attack or cast spells.  Any damage caused will release the target.      Only one target can be shackled at a time.", "Normal", 140, nil, 0, false, 20, true },
  { "Spell", "Turn Evil", 10326, 40217, "Paladin", "", "The targeted undead or demon enemy will be compelled to flee for up to 20 sec.      Damage caused may interrupt the effect. Only one target can be turned at a time.", "Rare", 140, nil, 0, false, 24, true },
  { "Spell", "Evocation", 12051, 40218, "Mage", "", "While channeling this spell, you gain 60% of your total mana over 7.81 sec.", "Rare", 0, nil, 0, false, 20, true },
  { "Spell", "Immolation Trap", 13795, 40219, "Hunter", "Rank 1", "Place a fire trap that will burn the first enemy to approach for 691 Fire damage over 15 sec. Trap will exist for 30 sec. Only one trap can be active at a time.", "Normal", 140, nil, 0, false, 16, true },
  { "Spell", "Explosive Trap", 13813, 40220, "Hunter", "Rank 1", "Place a fire trap that explodes when an enemy approaches, causing 251 to 282 Fire damage and burning all enemies for 1010 additional Fire damage over 20 sec to all within 10 yards. Trap will exist for 30 sec. Only one trap can be active at a time.", "Normal", 296, nil, 0, false, 34, true },
  { "Spell", "Divine Spirit", 14752, 40221, "Priest", "Rank 1", "Holy power infuses the target, increasing their Spirit by 17 for 30 min.   Does not stack with other similar effects.", "Uncommon", 406, nil, 0, false, 30, true },
  { "Spell", "Holy Fire", 14914, 40222, "Priest", "Rank 1", "Consumes the enemy in holy flames that cause 93 to 109 Holy damage and an additional 21 Holy damage over 7 sec.", "Normal", 171, nil, 0, false, 16, true },
  { "Spell", "Holy Nova", 15237, 40223, "Priest", "Rank 1", "Causes an explosion of holy light around the caster, causing 23 to 26 Holy damage to all enemy targets within 10 yards and healing all party members within 10 yards for 54 to 63. These effects cause no threat.", "Normal", 312, nil, 0, false, 14, true },
  { "Spell", "Nature's Grasp", 16689, 40224, "Druid", "", "For 45 sec, any time an enemy within 15 yards hits the caster they have a 100% chance to become afflicted by Entangling Roots which roots them in place for 5 sec.     Does not trigger on enemies already affected by a root effect.", "Epic", 0, nil, 0, false, 10, true },
  { "Spell", "Faerie Fire (Feral)", 16857, 40225, "Druid", "", "Decrease the armor of the target by 5% for 40 sec(20 seconds on players) While affected, the target cannot stealth or turn invisible. Deals 185 damage and additional threat when used in Bear Form or Dire Bear Form.   Does not stack with other similar effects.", "Normal", 0, nil, 3, false, 14, true },
  { "Spell", "Hurricane", 16914, 40226, "Druid", "Rank 1", "Creates a violent storm in the target area causing 113 to 114 Nature damage to enemies every 0.98 sec, and increasing the time between attacks of enemies by 20%.    Does not stack with other similar effects.    Lasts 9.77 sec.", "Normal", 1265, nil, 0, false, 40, true },
  { "Spell", "Berserker Rage", 18499, 40227, "Warrior", "", "The warrior enters a berserker rage, removing and granting immunity to Fear, Sap and Incapacitate effects and generating extra rage when taking damage.  Lasts 10 sec.  This ability is usable while shapeshifted.", "Epic", 0, nil, 0, false, 32, true },
  { "Spell", "Ritual of Doom", 18540, 40228, "Warlock", "", "Begins a ritual that sacrifices a random participant's health to summon a doomguard. Requires the caster and 4 additional party members to complete the ritual. In order to participate, all players must right-click the portal and not move until the ritual is complete.", "Rare", 1249, nil, 0, false, 40, true },
  { "Spell", "Teleport: Moonglade", 18960, 40229, "Druid", "", "Teleports the caster to the Moonglade.", "Normal", 120, nil, 0, false, 10, true },
  { "Spell", "Deterrence", 19263, 40230, "Hunter", "", "When activated, increases parry chance by 100%, reduces the chance ranged attacks will hit you by 100% and grants a 100% chance to deflect spells.  While Deterrence is active, you cannot attack.  Lasts 5 sec.", "Legendary", 0, nil, 0, false, 36, true },
  { "Spell", "Flash of Light", 19750, 40231, "Paladin", "Rank 1", "Heals a friendly target for 90 to 104.", "Normal", 109, nil, 0, false, 20, true },
  { "Spell", "Divine Intervention", 19752, 40232, "Paladin", "", "You sacrifice yourself to remove the targeted party member from harm's way. Enemies will stop attacking the protected party member, who will be immune to all harmful attacks but will not be able to take any action for 3 min.", "Normal", 0, nil, 0, false, 30, true },
  { "Spell", "Tranquilizing Shot", 19801, 40233, "Hunter", "", "Attempts to remove 1 Enrage and 1 Magic effect from an enemy target.", "Epic", 124, nil, 0, false, 44, true },
  { "Spell", "Track Humanoids", 19883, 40234, "Hunter", "", "Shows the location of all nearby humanoids on the minimap. Only one form of tracking can be active at a time.", "Rare", 0, nil, 0, false, 10, true },
  { "Spell", "Track Hidden", 19885, 40235, "Hunter", "", "Greatly increases stealth detection and shows hidden units within detection range on the minimap.     Only one form of tracking can be active at a time.", "Rare", 0, nil, 0, false, 24, true },
  { "Spell", "Retaliation", 20230, 40236, "Warrior", "", "Instantly counterattack any enemy that strikes you in melee for 12 sec.  Melee attacks made from behind cannot be counterattacked.  A maximum of 20 attacks will cause retaliation.", "Epic", 0, nil, 1, false, 20, true },
  { "Spell", "Intercept", 20252, 40237, "Warrior", "", "Charge an enemy, causing 123 damage (based on attack power) and stunning it for 3 sec.    This ability is usable while shapeshifted.", "Epic", 10, nil, 1, false, 20, true },
  { "Spell", "Reincarnation", 20608, 40239, "Shaman", "Passive", "Allows you to resurrect yourself upon death with 20% health and mana.    This has a 30 minute cooldown.", "Rare", 0, nil, 0, false, 10, true },
  { "Spell", "Distracting Shot", 20736, 40240, "Hunter", "", "Distracts the target to attack you, but has no effect if the target is already attacking you. Lasts 6 sec.", "Normal", 109, nil, 0, false, 12, true },
  { "Spell", "Maim", 22570, 40241, "Druid", "Rank 1", "Finishing move that causes damage and incapacitates the target. Causes more damage and lasts longer per combo point:    1 point  : 396-446 damage, 1 sec    2 points: 480-530 damage, 2 sec    3 points: 564-614 damage, 3 sec    4 points: 648-698 damage, 4 sec    5 points: 732-782 damage, 5 sec    Non-player victim spellcasting is also interrupted for 3 sec.     Any damage caused will interrupt the incapacitating effect.    Does not break from periodic damage.", "Epic", 35, nil, 3, false, 44, true },
  { "Spell", "Barkskin", 22812, 40242, "Druid", "", "The caster's skin becomes as tough as bark.  All damage taken is reduced by 30%.  While protected, damaging attacks will not cause spellcasting delays. Lasts 12 sec.    This spell is usable while stunned, frozen, incapacitated, feared or asleep.     This ability is usable while shapeshifted.", "Epic", 0, nil, 0, false, 36, false },
  { "Spell", "Spell Reflection", 23920, 40244, "Warrior", "", "Raise your shield, reflecting the next spell cast on you. Lasts 5 sec.", "Epic", 15, nil, 1, false, 50, true },
  { "Spell", "Shield Slam", 23922, 40245, "Warrior", "Rank 1", "Slam the target with your shield, causing 294 to 307 damage, modified by your shield block value, and dispels 1 magic effect on the target. Causes a high amount of threat.", "Normal", 20, nil, 1, false, 40, true },
  { "Spell", "Righteous Fury", 25780, 40246, "Paladin", "", "Your threat generated is significantly increased.    Teaches you Hand of Reckoning .   Also increases your chance to block Fierce Blows.", "Uncommon", 0, nil, 0, false, 1, true },
  { "Spell", "Consecration", 26573, 40247, "Paladin", "Rank 1", "Consecrates the land beneath the Paladin, doing 214 Holy damage over 8 sec to enemies who enter the area.", "Normal", 343, nil, 0, false, 1, true },
  { "Spell", "Deadly Throw", 26679, 40248, "Rogue", "Rank 1", "Finishing move that reduces the movement of the target by 50% for 6 sec and causes increased thrown weapon damage:     1 point  : 28-44 damage     2 points: 47-63 damage     3 points: 66-82 damage     4 points: 85-101 damage     5 points: 104-120 damage", "Rare", 35, nil, 3, false, 24, true },
  { "Spell", "Seed of Corruption", 27243, 40249, "Warlock", "Rank 1", "Imbeds a demon seed in the enemy target, causing 480 Shadow damage over 18 sec.  When the target takes 0 total damage or dies, the seed will inflict 571 to 655 Shadow damage to all enemies within 15 yards of the target.", "Normal", 531, nil, 0, false, 40, true },
  { "Spell", "Innervate", 29166, 40250, "Druid", "", "Causes the target to regenerate mana equal to 225% of the caster's base mana pool over 10 sec.", "Rare", 0, nil, 0, false, 40, true },
  { "Spell", "Incinerate", 29722, 40251, "Warlock", "Rank 1", "Deals 102 to 121 Fire damage to your target and an additional 25 to 31 Fire damage if the target is affected by an Immolate spell.", "Normal", 218, nil, 0, false, 18, true },
  { "Spell", "Soulshatter", 29858, 40252, "Warlock", "", "Reduces threat by 50% for all enemies within 50 yards.", "Rare", 406, nil, -2, false, 32, true },
  { "Spell", "Ritual of Souls", 29890, 40253, "Warlock", "Rank 1", "Begins a ritual that creates a Soulwell. Raid members can click the Soulwell to acquire a Major Healthstone. The Soulwell lasts for 3 min or 25 charges.     Requires the caster and 2 additional party members to complete the ritual. In order to participate, all players must right-click the soul portal and not move until the ritual is complete.", "Uncommon", 1249, nil, 0, false, 34, true },
  { "Spell", "Spellsteal", 30449, 40254, "Mage", "", "Steals a beneficial magic effect from the target.  This effect lasts a maximum of 2 min.", "Epic", 312, nil, 0, false, 50, true },
  { "Spell", "Arcane Blast", 30451, 40255, "Mage", "Rank 1", "Blasts the target with energy, dealing 171 to 195 Arcane damage.      Casting this increases all Arcane damage by 15% and its mana cost by 150%. Stacks up to 4 and lasts 6 sec, removed if you cast another Arcane ability that deals damage.", "Normal", 156, nil, 0, false, 18, true },
  { "Spell", "Ice Lance", 30455, 40256, "Mage", "Rank 1", "Deals 36 to 40 Frost damage to an enemy target.  Causes triple damage against Frozen targets.", "Normal", 93, nil, 0, false, 22, true },
  { "Spell", "Cloak of Shadows", 31224, 40257, "Rogue", "", "Instantly removes all existing harmful spell effects, Increases your chance to resist all spells by 90% for 5 sec.     Does not remove effects that prevent you from using Cloak of Shadows.", "Legendary", 0, nil, 0, false, 50, true },
  { "Spell", "Righteous Defense", 31789, 40258, "Paladin", "", "Transfers the next melee or ranged attack made against an ally. In addition, while active 20% of the threat they generate is transferred to you instead.  Casting this spell with an enemy target will redirect it to whatever they are targeting.    This cannot be used in Battlegrounds or Arenas", "Normal", 0, nil, 0, false, 12, true },
  { "Spell", "Avenging Wrath", 31884, 40259, "Paladin", "", "Increases all damage and healing caused by 20% for 20 sec.   Cannot be used within 30 sec of being the target of Divine Shield, Divine Protection, or Hand of Protection, or of using Lay on Hands on oneself.    Does not stack with other similar effects.", "Epic", 124, nil, 0, false, 50, true },
  { "Spell", "Mass Dispel", 32374, 40260, "Priest", "", "Dispels magic in a 15 yard radius, removing 1 harmful spell from each friendly target and 1 beneficial spell from each enemy target.  Affects a maximum of 10 friendly targets and 10 enemy targets.  This dispel is potent enough to remove Magic effects that are normally undispellable, including Divine Shield, Ice Block and Cyclone.    Mass Dispel can remove Stealth from targets within the spell.", "Epic", 781, nil, 0, false, 40, true },
  { "Spell", "Shadow Word: Death", 32379, 40261, "Priest", "Rank 1", "A word of dark binding that inflicts 192 to 222 Shadow damage to the target.  If the target is not killed by Shadow Word: Death, the caster takes damage equal to the damage inflicted upon the target after a short delay.", "Rare", 187, nil, 0, false, 40, true },
  { "Spell", "Binding Heal", 32546, 40262, "Priest", "Rank 1", "Heals a friendly target and the caster for 399 to 458. Low threat.", "Normal", 421, nil, 0, false, 40, true },
  { "Spell", "Envenom", 32645, 40263, "Rogue", "Rank 1", "Finishing move that consumes your Deadly Poison doses on the target and deals instant poison damage.     After the Envenom attack you have an additional 15% chance to apply Deadly Poison and a 75% increased frequency of applying Instant Poison for 1 sec plus an additional 1 sec per combo point.  One dose is consumed for each combo point:    1 dose:  83 damage    2 doses: 207 damage    3 doses: 372 damage    4 doses: 578 damage    5 doses: 826 damage", "Normal", 35, nil, 3, false, 36, true },
  { "Spell", "Prayer of Mending", 33076, 40264, "Priest", "Rank 1", "Places a spell on the target that heals them for 101 the next time they take damage.  When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump.      This spell can only be placed on one target at a time.", "Rare", 234, nil, 0, false, 40, true },
  { "Spell", "Lacerate", 33745, 40265, "Druid", "Rank 1", "Lacerates the enemy target, dealing 7 damage and making them bleed for 35 damage over 15 sec and causing a high amount of threat.  Damage increased by attack power.      Stacks up to 3 times on the same target.", "Normal", 15, nil, 1, false, 10, true },
  { "Spell", "Lifebloom", 33763, 40266, "Druid", "Rank 1", "Heals the target for 84 over 7 sec.      When Lifebloom completes its duration or is dispelled, the target instantly heals themself for 190 to 191 and the Druid regains half the cost of the spell.      This effect can stack up to 3 times on the target.", "Normal", 437, nil, 0, false, 36, true },
  { "Spell", "Cyclone", 33786, 40267, "Druid", "", "Tosses the enemy target into the air, preventing all action but making them invulnerable for up to 6 sec. Only one target can be affected by your Cyclone at a time.", "Epic", 124, nil, 0, false, 50, true },
  { "Spell", "Flight Form", 33943, 40268, "Druid", "Shapeshift", "Shapeshift into flight form, increasing movement speed by 150% and allowing you to fly. Cannot use in combat. Can only use this form in Outland or Northrend.    The act of shapeshifting frees the caster of movement impairing and Polymorph effects.", "Normal", 203, nil, 0, false, 70, false },
  { "Spell", "Kill Command", 34026, 40269, "Hunter", "", "Give the command to kill, increasing your tamed beast's damage done from special attacks by 40% for 30 sec. Each special attack done by the tamed beast reduces the damage bonus by 10%.  This ability is usable while shapeshifted.", "Rare", 46, nil, 0, false, 40, true },
  { "Spell", "Victory Rush", 34428, 40270, "Warrior", "", "Instantly attack the target causing 465 damage.  Can only be used within 20 sec after you kill an enemy that yields experience or honor. Damage is based on your attack power.", "Normal", 0, nil, 1, false, 1, true },
  { "Spell", "Shadowfiend", 34433, 40271, "Priest", "", "Creates a shadowy fiend to attack the target.  Caster receives 5% mana when the Shadowfiend attacks. Damage taken by area of effect attacks is reduced. Lasts 15 sec.", "Rare", 0, nil, 0, false, 50, true },
  { "Spell", "Misdirection", 34477, 40272, "Hunter", "", "The current party or raid member targeted will receive the threat caused by your spells and attacks for 4 sec afterwards.", "Uncommon", 140, nil, 0, false, 44, true },
  { "Spell", "Totemic Recall", 36936, 40273, "Shaman", "", "Returns your totems to the earth, giving you 50% of the mana required to cast each totem destroyed by Totemic Recall.  This ability is usable while shapeshifted.", "Normal", 0, nil, 0, false, 30, true },
  { "Spell", "Conjure Refreshment", 42951, 40274, "Mage", "Rank 1", "Conjures 20 Mana Berries providing the mage and her allies with something to eat.  Conjured items disappear if logged out for more than 15 minutes.", "Normal", 624, nil, 0, false, 50, true },
  { "Spell", "Ritual of Refreshment", 43601, 40275, "Mage", "Rank 1", "Begins a ritual to create a refreshment table. Raid members can click to receive Conjured Mana Berries.     Requires the caster and 2 others to complete. Participants must right-click the portal and remain still.    Lasts 3 min or 50 charges.", "Normal", 1249, nil, 0, false, 50, true },
  { "Spell", "Frostfire Bolt", 44614, 40276, "Mage", "Rank 1", "Launches a bolt of frostfire at the enemy, causing 183 to 211 Frostfire damage, slowing movement speed by 40% and causing an additional 60 Frostfire damage over 9 sec. This spell will be checked against the lower of the target's Frost and Fire resists.", "Normal", 218, nil, 0, false, 32, true },
  { "Spell", "Ice Block", 45438, 40277, "Mage", "", "You become encased in a block of ice, protecting you from all attacks for 10 sec, but during that time you cannot attack, move or cast spells.      Causes Hypothermia, preventing you from recasting Ice Block for 30 sec.", "Legendary", 15, nil, 0, false, 30, true },
  { "Spell", "Demonic Circle: Summon", 48018, 40278, "Warlock", "", "You summon a Demonic Circle at your feet, lasting 6 min. You can only have one Demonic Circle active at a time.", "Legendary", 234, nil, 0, false, 50, true },
  { "Spell", "Nourish", 50464, 40279, "Druid", "Rank 1", "Heals a friendly target for 383 to 447. Heals for an additional 20% if you have a Rejuvenation, Regrowth, Lifebloom, or Wild Growth effect active on the target.", "Normal", 281, nil, 0, false, 44, true },
  { "Spell", "Revive", 50769, 40280, "Druid", "Rank 1", "Returns the spirit to the body, restoring a dead target to life with 65 health and 120 mana.  Cannot be cast when in combat.", "Normal", 1124, nil, 0, false, 12, true },
  { "Spell", "Hex", 51514, 40281, "Shaman", "", "Transforms the enemy into a frog. While hexed, the target cannot attack or cast spells. Damage caused may interrupt the effect. Lasts 30 sec. Only one target can be hexed at a time. Only works on Humanoids and Beasts.", "Epic", 46, nil, 0, false, 50, true },
  { "Spell", "Dismantle", 51722, 40282, "Rogue", "", "Disarm the enemy, removing their weapons, shields, or other equipment carried for 6 sec.", "Epic", 25, nil, 3, false, 20, true },
  { "Spell", "Fan of Knives", 51723, 40283, "Rogue", "", "Instantly throw both weapons at all targets within 8 yards, causing 105% weapon damage with daggers, and 70% weapon damage with all other weapons.", "Normal", 50, nil, 3, false, 50, true },
  { "Spell", "Water Shield", 52127, 40284, "Shaman", "Rank 1", "The caster is surrounded by 5 globes of water, granting 10 mana per 5 sec. When a spell, melee or ranged attack hits the caster, 40 mana is restored to the caster. This expends one water globe. Only one globe will activate every few seconds. Lasts 10 min.", "Rare", 0, nil, 0, false, 20, true },
  { "Spell", "Master's Call", 53271, 40286, "Hunter", "", "Your pet attempts to remove all root and movement impairing effects from itself and its owner, and causes your pet and its target to be immune to all such effects for 4 sec.", "Epic", 109, nil, 0, false, 50, true },
  { "Spell", "Kill Shot", 53351, 40287, "Hunter", "Rank 1", "You attempt to finish the wounded target off, firing a ranged attack dealing 200% weapon damage plus 26. Kill Shot can only be used on enemies that have 20% or less health.", "Normal", 109, nil, 0, false, 32, true },
  { "Spell", "Shield of Righteousness", 53600, 40288, "Paladin", "", "Slam the target with your shield, causing Holy damage based on your block value plus an additional 123. This ability will also heal you based on your spell damage.", "Normal", 93, nil, 0, false, 1, true },
  { "Spell", "Sacred Shield", 53601, 40289, "Paladin", "Rank 1", "Each time the target takes damage they gain a Sacred Shield, absorbing 110 damage and increasing the paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. They cannot gain this effect more than once every 6 sec. Lasts 30 sec.      This spell cannot be on more than one target at any one time.", "Epic", 187, nil, 0, false, 50, true },
  { "Spell", "Divine Plea", 54428, 40290, "Paladin", "", "You gain 25% of your total mana over 15 sec, but reduces your healing by 50%.", "Epic", 0, nil, 0, false, 50, true },
  { "Spell", "Mirror Image", 55342, 40291, "Mage", "", "Creates 3 copies of the caster nearby, which cast spells and attack the mage's enemies.  Lasts 30 sec.", "Legendary", 156, nil, 0, false, 50, true },
  { "Spell", "Enraged Regeneration", 55694, 40292, "Warrior", "", "You regenerate 30% of your total health over 10 sec.  This ability requires an Enrage effect, consumes all Enrage effects and prevents any from affecting you for the full duration.", "Epic", 15, nil, 1, false, 50, true },
  { "Spell", "Steady Shot", 56641, 40293, "Hunter", "Rank 1", "A steady shot that causes 125% weapon damage plus 9. Causes an additional 10 to slowed targets.", "Normal", 78, nil, 0, false, 1, true },
  { "Spell", "Heroic Throw", 57755, 40294, "Warrior", "", "Throws your weapon at the enemy causing 523 damage (based on attack power).  This ability causes high threat.", "Normal", 0, nil, 1, false, 50, true },
  { "Spell", "Tricks of the Trade", 57934, 40295, "Rogue", "", "The party or raid member you have targeted receives the threat caused by your next damaging attack and all threat you cause for 6 sec. Their damage is increased by 15%.", "Epic", 15, nil, 3, false, 50, true },
  { "Spell", "Wind Shear", 57994, 40296, "Shaman", "", "Instantly blasts the target with a gust of wind, causing no damage but interrupting spellcasting and preventing spells of that school of magic from being cast for 2 sec.   This ability shares a cooldown with other interrupts.", "Epic", 124, nil, 0, false, 12, true },
  { "Spell", "Freezing Arrow", 60192, 40297, "Hunter", "Rank 1", "Fire a freezing arrow that places a Freezing Trap at the target location, freezing the first enemy that approaches, preventing all action for up to 20 sec.  Any damage caused will break the ice.  Trap will exist for 30 sec. Only one trap can be active at a time.", "Epic", 46, nil, 0, false, 60, true },
  { "Spell", "Swipe (Cat)", 62078, 40298, "Druid", "", "Swipe nearby enemies, inflicting 140% weapon damage.", "Normal", 50, nil, 3, false, 1, true },
  { "Spell", "Call Stabled Pet", 62757, 40299, "Hunter", "", "Choose one of your stabled pets to replace your current pet. The selected pet busts out of its stable to join you no matter where you are.  Cannot be used in combat.", "Normal", 0, nil, 0, false, 50, true },
  { "Spell", "Shattering Throw", 64382, 40300, "Warrior", "", "Throws your weapon at the enemy causing 523 damage (based on attack power) and removing any invulnerabilities.     If no invulnerability is removed, you lower the target's armor by 20% for 10 seconds and reduce the cooldown of your next Shattering Throw by 30 seconds.", "Epic", 25, nil, 1, false, 40, true },
  { "Spell", "Divine Hymn", 64843, 40301, "Priest", "Rank 1", "Heals 3 nearby lowest health friendly party or raid targets within 40 yards for 896 to 984 every 1.95 sec for 7.81 sec, and increases healing done to them by 10% for 8 sec. Maximum of 12 heals. The Priest must channel to maintain the spell.", "Epic", 984, nil, 0, false, 50, true },
  { "Spell", "Hymn of Hope", 64901, 40302, "Priest", "", "Restores 3% mana to 3 nearby low mana friendly party or raid targets every 1.95 sec for 7.81 sec, and increases their total maximum mana by 20% for 8 sec. Maximum of 12 mana restores. The Priest must channel to maintain the spell.", "Epic", 0, nil, 0, false, 50, true },
  { "Spell", "Call of the Elements", 66842, 40303, "Shaman", "", "Simultaneously places up to 4 totems specified in the Totem Bar.", "Normal", 0, nil, 0, false, 14, true },
  { "Spell", "Call of the Ancestors", 66843, 40304, "Shaman", "", "Simultaneously places up to 4 totems specified in the Totem Bar. Can call different totems than Call of the Elements.", "Normal", 0, nil, 0, false, 22, true },
  { "Spell", "Call of the Spirits", 66844, 40305, "Shaman", "", "Simultaneously places up to 4 totems specified in the Totem Bar. Can call different totems than Call of the Elements or Call of the Ancestors.", "Normal", 0, nil, 0, false, 28, true },
  { "Spell", "Portal Mastery", 818045, 40307, "Mage", "", "Gives the ability to learn Portal and Teleport spells.  You can learn the various Teleports and Portals in many towns and cities!", "Uncommon", 0, nil, 0, false, 20, true },
  { "Spell", "Tame Beast Abilities", 965200, 40308, "Hunter", "", "Teaches you the necessary abilities to tame a pet companion.  Teaches you Tame Beast, Call Pet, Dismiss Pet, Feed Pet, Revive Pet and Beast Lore.", "Epic", 0, nil, 0, false, 1, false },
  { "Spell", "Auto shot", 965202, 40309, "Hunter", "", "Automatically shoots the target until cancelled. Increases your ranged Attack Speed by 33% and scales with Ranged Attack Power.", "Normal", 0, nil, 0, false, 1, true },
  { "Spell", "Devastate", 20243, 40715, "Warrior", "Rank 1", "Sunder the target's armor causing the Sunder Armor effect. In addition, causes 120% weapon damage (96% if a two-handed weapon is equipped) plus 4 for each application of Sunder Armor on the target. The Sunder Armor effect can stack up to 5 times.      Sunder Armor  Sunders the target's armor, reducing it by 4%. Stacks up to 5 times and lasts for 30 sec. Does not stack with other similar effects.", "Normal", 15, nil, 1, false, 10, true },
  { "Spell", "Crusader Strike", 35395, 40848, "Paladin", "", "An instant strike that causes 75% weapon damage.", "Normal", 78, nil, 0, false, 1, true },
  { "Spell", "Lava Lash", 60103, 41029, "Shaman", "", "You charge your off-hand weapon with lava, instantly dealing 100% off-hand Weapon damage as Firestrike damage.     The damage increased by 25% if your off-hand weapon is enchanted with Flametongue.", "Normal", 62, nil, 0, false, 1, true },
  { "Spell", "Track Beasts", 1494, 41124, "Hunter", "", "Shows the location of all nearby beasts on the minimap and increases damage dealt to beasts by 1%.  Only one form of tracking can be active at a time.", "Normal", 0, nil, 0, false, 1, true },
  { "Spell", "Track Demons", 19878, 41127, "Hunter", "", "Shows the location of all nearby demons on the minimap and increases damage dealt to demons by 1%. Only one form of tracking can be active at a time.", "Normal", 0, nil, 0, false, 32, true },
  { "Spell", "Track Dragonkin", 19879, 41128, "Hunter", "", "Shows the location of all nearby dragonkin on the minimap and increases damage dealt to dragonkin by 1%. Only one form of tracking can be active at a time.", "Normal", 0, nil, 0, false, 50, true },
  { "Spell", "Track Elementals", 19880, 41129, "Hunter", "", "Shows the location of all nearby elementals on the minimap and increases damage dealt to elementals by 1%. Only one form of tracking can be active at a time.", "Normal", 0, nil, 0, false, 26, true },
  { "Spell", "Track Giants", 19882, 41130, "Hunter", "", "Shows the location of all nearby giants on the minimap and increases damage dealt to giants by 1%. Only one form of tracking can be active at a time.", "Normal", 0, nil, 0, false, 40, true },
  { "Spell", "Track Undead", 19884, 41131, "Hunter", "", "Shows the location of all nearby undead on the minimap and increases damage dealts to undead by 1%. Only one form of tracking can be active at a time.", "Normal", 0, nil, 0, false, 18, true },
  { "Spell", "Flame Ascendance", 760000, 41282, "Shaman", "", "Transform into a being of raw elemental energy for 15 sec, casting Flame Shock on up to 10 nearby enemies within 10 yards if known. Chain Lightning becomes Lava Beam. Lava Burst's cooldown is reduced by 50%.        Lava Beam  Unleash a blast of superheated flame at the enemy, dealing 252 Firestorm damage and then jumping to additional nearby enemies. Affects 3 total targets.    Lava Beam cannot be cast unless you're affected by Flame Ascendance.", "Epic", 109, nil, 0, false, 34, true },
  { "Spell", "Cloudburst Totem", 760009, 41283, "Shaman", "", "Summons a totem with 5 health for 15 sec that stores 30% of your Nature healing. When it expires or is recalled, it heals injured allies within 40 yards, divided evenly. Recasting the spell recalls the totem and releases the healing.", "Epic", 46, nil, 0, false, 28, true },
  { "Spell", "Frozen Orb", 760014, 41284, "Mage", "Rank 1", "Launches a Frozen Orb forward from the caster's position, that deals 79 Frost damage to all nearby enemy targets every 1 sec for 8 sec.     Targets damaged by the Frost Orb are slowed by 40% for 2 sec.", "Epic", 218, nil, 0, false, 30, true },
  { "Spell", "Divine Star", 760060, 41285, "Priest", "Rank 1", "Fires a Divine Star in front of you, traveling 30 yards, healing all allies within 5 yards of its path for 12.  After reaching its destination it will return to its original position, also healing all allies in its path.", "Rare", 218, nil, 0, false, 30, true },
  { "Spell", "Meteor", 760040, 41286, "Mage", "Rank 1", "Calls down a meteor which lands at the target location after 3 seconds, dealing 187 Fire damage within 8 yards, and burns the ground for 199 Fire damage over 6 sec to all enemies in the area.", "Epic", 249, nil, 0, false, 36, true },
  { "Spell", "Mass Invisibility", 760052, 41287, "Mage", "", "You and your allies within 40 yards instantly become invisible for 5 sec. The effect is cancelled if you perform any actions. While invisible, you can only see other invisible targets and those who can see invisible. Removes invulnerabilities when used.", "Legendary", 0, nil, 0, false, 50, true },
  { "Spell", "Angelic Feather", 760053, 41288, "Priest", "", "Place a feather at the target location, lasting for 15 sec. If allies walk through it, they gain 50% increased movement speed for 4 sec.  Max 3 charges. 20 second recharge timer.", "Legendary", 156, nil, 0, false, 28, true },
  { "Spell", "Grappling Hook", 760056, 41289, "Rogue", "", "Launch a grappling hook and pull yourself to the target location. For 3 sec after using it you can recast it, pulling yourself to an enemy and rooting them for 1 sec. Does not break stealth.", "Legendary", 0, nil, 0, false, 28, true },
  { "Spell", "Roll the Bones", 760080, 41290, "Rogue", "", "Roll the dice of fate, providing a random lesser or great combat enhancement for 10 sec. Only one enhancement can be active at the same time.    This ability is usable while shapeshifted.", "Epic", 0, nil, 0, false, 26, true },
  { "Spell", "Ironfur", 760100, 41291, "Druid", "", "Reduces damage taken by 4% plus an additional 4% per active application for 6 sec. Each application has an individual duration.  Max 3 charges. 10 second recharge timer.", "Epic", 40, nil, 1, false, 40, true },
  { "Spell", "Gloomblade", 760050, 41292, "Rogue", "Rank 1", "Punctures the target with your shadow-infused blade, causing 90% weapon damage as Shadow and inflicting Gloomblade for 6 sec, causing your melee abilities on the target to trigger additional 101 Shadow damage. Awards 1 combo point.", "Normal", 40, nil, 3, false, 26, true },
  { "Spell", "Light of Dawn", 760106, 41293, "Paladin", "Rank 1", "Unleashes a wave of Holy energy, healing up to 5 injured allies within a 30 yd frontal cone for 66 to 77.", "Rare", 187, nil, 0, false, 30, true },
  { "Spell", "Flourish", 760107, 41294, "Druid", "Rank 1", "Heals a friendly target for 215 to 263 and increases all healing done by your Nature healing over time effects on the target by 100% for 4 sec.", "Normal", 281, nil, 0, false, 32, true },
  { "Spell", "Sundering", 760121, 41295, "Shaman", "Rank 1", "Shatters a line of earth in front of you, causing 621 Firestrike damage and Incapacitating any enemy hit for 3 sec. This effect does not break from periodic Fire damage. Also, resets the cooldown of Lava Burst.", "Epic", 109, nil, 0, false, 34, true },
  { "Spell", "Void Eruption", 760122, 41296, "Priest", "Rank 1", "Releases an explosive blast of pure void energy, causing Shadow damage to up to 10 enemies within 10 yards of your target. The power drawn from the Void increases your periodic Shadow Priest damage by 20% for 5 sec, increased by 0.5 sec for each enemy hit.  While in Shadowform this spell also applies Shadow Word: Pain (if known) to all enemies hit.", "Epic", 0, nil, 0, false, 28, true },
  { "Spell", "Nature Ward", 760210, 41297, "Druid", "Rank 1", "Absorbs 290 Nature damage.  Lasts 30 sec.  This ability is usable while shapeshifted.", "Rare", 187, nil, 0, false, 20, true },
  { "Spell", "Rune of Swordshattering", 53323, 41839, "DeathKnight", "", "Affixes your two-handed rune weapon with a rune that increases Parry chance by 4% and reduces the duration of Disarm effects by 50%.      Requires a Rune Forge.", "Epic", 0, nil, 0, false, 20, false },
  { "Spell", "Rune of Lichbane", 53331, 41840, "DeathKnight", "", "Affixes your rune weapon with a rune that adds 2% extra weapon damage as Fire damage or 4% versus Undead targets.     Requires a Rune Forge.", "Epic", 0, nil, 0, false, 20, false },
  { "Spell", "Rune of Cinderglacier", 53341, 41841, "DeathKnight", "", "Affixes your rune weapon with a rune that has a chance to cause your target to take 20% increased Frost and Shadow damage from you.  Requires a Rune Forge.", "Epic", 0, nil, 0, false, 20, false },
  { "Spell", "Rune of Spellshattering", 53342, 41842, "DeathKnight", "", "Affixes your two-handed rune weapon with a rune that deflects 4% of all spell damage and reduces the duration of Silence effects by 50%.     Requires a Rune Forge.", "Epic", 0, nil, 0, false, 20, false },
  { "Spell", "Rune of Razorice", 53343, 41843, "DeathKnight", "", "Affixes your weapon with a rune that causes 2% extra weapon damage as Frost damage and increases enemies' vulnerability to your Frost attacks.    Requires a Rune Forge.", "Epic", 0, nil, 0, false, 20, false },
  { "Spell", "Rune of the Fallen Crusader", 53344, 41844, "DeathKnight", "", "Affixes your rune weapon with a rune that has a chance to heal you for 3% of your maximum health and increase total Strength by 15% for 15 sec.    Requires a Rune Forge.", "Epic", 0, nil, 0, false, 20, false },
  { "Spell", "Rune of the Stoneskin Gargoyle", 62158, 41845, "DeathKnight", "", "Affixes your two-handed rune weapon with a rune that increases Defense by 25 and total Stamina by 2%.    Requires a Rune Forge.", "Epic", 0, nil, 0, false, 20, false },
  { "Spell", "Rune of the Nerubian Carapace", 70164, 41846, "DeathKnight", "", "Affixes your rune weapon with a rune that increases Defense by 13 and total Stamina by 1%.    Requires a Rune Forge.", "Epic", 0, nil, 0, false, 20, false },
  { "Spell", "Barbed Shot", 984828, 41875, "Hunter", "", "Fire a shot that tears through your enemy, causing them to bleed over 8 sec.    Sends your pet into a bloodrush, increasing attack speed by 20% for 8 sec, stacking up to 3 times.    Max 2 charges. 12 second recharge timer.", "Rare", 140, nil, 0, false, 40, true },
  { "Spell", "Avatar", 886380, 41876, "Warrior", "", "Transform into an unstoppable colossus for 12 sec, causing you to deal 15% increased Physical damage and take 20% less damage.    While in this state you move at 80% speed which cannot be reduced or increased. You are also immune to immobilizing effects.", "Legendary", 0, nil, 0, false, 40, true },
  { "Spell", "Water Elemental Totem", 2896, 41878, "Shaman", "", "Summons an elemental totem that calls forth a greater water elemental to rain destruction on the caster's enemies. Lasts 2 min.    This ability is usable while shapeshifted.  This uses Fire Elemental Totem modifiers.", "Epic", 359, nil, 0, false, 40, true },
  { "Spell", "Air Elemental Totem", 2897, 41879, "Shaman", "", "Summons an elemental totem that calls forth a greater air elemental to rain destruction on the caster's enemies. Lasts 2 min.    This ability is usable while shapeshifted.  This uses Fire Elemental Totem modifiers.", "Epic", 359, nil, 0, false, 40, true },
  { "Spell", "Feline Grace", 20719, 41892, "Druid", "Passive", "Reduces damage from falling.", "Normal", 0, nil, 0, false, 40, true },
  { "Spell", "Death Gate", 50977, 41909, "DeathKnight", "", "Opens a gate which the Death Knight can use to return to Ebon Hold.", "Normal", 0, nil, 5, false, 71, false },
  { "Spell", "Ferocious Bite", 22568, 41910, "Druid", "Rank 1", "Finishing move that causes damage per combo point and converts each extra point of energy (up to a maximum of 30 extra energy) into 3.2 additional damage.    1 point  : 89-94 damage    2 points: 172-177 damage    3 points: 256-261 damage    4 points: 339-344 damage    5 points: 423-428 damage", "Normal", 35, nil, 3, false, 10, true },
  { "Spell", "Hammer of Wrath", 24275, 41911, "Paladin", "Rank 1", "Hurls a hammer that strikes an enemy for 660 to 697 Holy damage. Only usable on enemies that have 20% or less health.", "Normal", 187, nil, 0, false, 44, true },
  { "Spell", "Shadowflame", 47897, 41912, "Warlock", "Rank 1", "Targets in a cone in front of the caster take 71 to 77 Shadowflame damage and an additional 64 Shadowflame damage over 8 sec.", "Normal", 390, nil, 0, false, 36, true },
  { "Spell", "Unholy Frenzy", 91232, 41913, "DeathKnight", "", "Increases the attack rate of your Demon or Undead pet by 50% but drains 1% of its health every 1 seconds. Lasts 30 sec.", "Rare", 0, nil, 0, false, 26, true },
  { "Spell", "Mind Sear", 48045, 41914, "Priest", "Rank 1", "Causes an explosion of shadow magic around the enemy target, causing 51 to 59 Shadow damage every 0.98 sec for 4.88 sec to all enemies within 10 yards around the target.", "Normal", 437, nil, 0, false, 36, true },
  { "Spell", "Lava Burst", 51505, 41915, "Shaman", "Rank 1", "You hurl molten lava at the target, dealing 188 to 235 Fire damage. If your Flame Shock is on the target, Lava Burst will deal a critical strike.", "Normal", 156, nil, 0, false, 22, true },
  { "Spell", "Dominate Undead", 891, 41916, "DeathKnight", "", "Teaches you the necessary abilities to Dominate an Undead companion.  Teaches you Dominate Undead, Raise Undead, Dismiss Undead, Revive Undead and Undead Lore.        Dominate Undead  Begins dominating an undead to be your companion.     Your armor is reduced by 100% while you focus on dominating the undead for 20 sec.     If you lose the undead's attention for any reason, the domination process will fail. Each type of undead has unique abilities that you will be able to make use of.", "Epic", 749, nil, 0, false, 1, false },
  { "Spell", "Path of Frost", 3714, 41917, "DeathKnight", "", "Surrounds the caster with a freezing aura beneath her feet, allowing her and her party or raid to walk on water for 10 min. Works while mounted. Any damage will cancel the effect.", "Normal", 0, nil, 5, false, 30, true },
  { "Spell", "Army of the Dead", 42650, 41918, "DeathKnight", "", "Summons an entire legion of Ghouls to fight for you over 4 sec. The Ghouls will swarm the area, taunting and fighting anything they can.  While channeling Army of the Dead, you take less damage equal to your Dodge plus Parry chance.", "Legendary", 0, nil, 5, false, 34, true },
  { "Spell", "Death and Decay", 43265, 41919, "DeathKnight", "Rank 1", "Corrupts the ground at the targeted area, causing 62 Shadow damage every sec that targets remain in the area for 10 sec. This ability produces a high amount of threat.", "Normal", 0, nil, 5, false, 20, true },
  { "Spell", "Plague Strike", 45462, 41920, "DeathKnight", "Rank 1", "A vicious strike that deals 50% weapon damage plus 8 and infects the target with Blood Plague, a disease dealing 67 Shadow damage over time.", "Normal", 0, nil, 5, false, 1, true },
  { "Spell", "Icy Touch", 45477, 41921, "DeathKnight", "Rank 1", "Chills the target for 113 to 114 Frost damage and infects them with Frost Fever, a disease that deals periodic damage and reduces melee and ranged attack speed by 14% for 15 sec. Generates very high threat while in a Tank Stance.", "Normal", 0, nil, 5, false, 1, true },
  { "Spell", "Chains of Ice", 45524, 41922, "DeathKnight", "Rank 1", "Shackles the target with frozen chains, reducing their movement by 45%, and infects them with Frost Fever. The target regains 4% of their movement each second for 10 sec.", "Epic", 0, nil, 5, false, 14, true },
  { "Spell", "Blood Tap", 45529, 41923, "DeathKnight", "", "Immediately activates a Blood Rune and converts it into a Death Rune for the next 20 sec.  Death Runes count as a Blood, Frost or Unholy Rune.", "Epic", 203, nil, -2, false, 18, true },
  { "Spell", "Blood Strike", 45902, 41924, "DeathKnight", "Rank 1", "Instantly strike the enemy, causing 40% weapon damage plus 12, total damage increased by 12.5% for each of your diseases on the target.", "Normal", 0, nil, 5, false, 1, true },
  { "Spell", "Raise Dead", 46584, 41925, "DeathKnight", "", "Raises a Ghoul to fight by your side. You can have a maximum of one Ghoul at a time.  Lasts 1 min.", "Epic", 0, nil, 5, false, 18, true },
  { "Spell", "Strangulate", 47476, 41926, "DeathKnight", "", "Strangulates an enemy, silencing them for 5 sec.  Non-player victim spellcasting is also interrupted for 3 sec.", "Epic", 0, nil, 5, false, 22, true },
  { "Spell", "Mind Freeze", 47528, 41927, "DeathKnight", "", "Smash the target's mind with cold, interrupting spellcasting and preventing any spell in that school from being cast for 4 sec.    This ability shares a cooldown with other interrupts.", "Epic", 20, nil, 1, false, 14, true },
  { "Spell", "Grave Coil", 47541, 41928, "DeathKnight", "Rank 1", "Fire a blast of unholy energy, causing 26 Shadow damage to an enemy target or healing 39 damage from a friendly Undead target.    Ancient Death Knights remember this dark spell as Death Coil", "Normal", 40, nil, 1, false, 12, true },
  { "Spell", "Empower Rune Weapon", 47568, 41929, "DeathKnight", "", "Empower your rune weapon, immediately activating all your runes and generating 25 rage.", "Epic", 0, nil, 5, false, 30, true },
  { "Spell", "Frost Presence", 48263, 41930, "DeathKnight", "", "Increases Stamina by 4% and significantly increases threat generated.   Increases the Armor contribution Cloth, Leather, Mail and Plate items by 30%   Reduces damage taken by 2%.    Only one Presence may be active at a time.", "Rare", 0, nil, 5, false, 1, true },
  { "Spell", "Unholy Presence", 48265, 41931, "DeathKnight", "", "Infuses you with unholy fury, increasing attack speed by 5%, movement speed by 15%, and reducing the global cooldown of all Death Knight abilities by 0.5 sec.     Only one Presence can be active at a time.", "Rare", 0, nil, 5, false, 28, true },
  { "Spell", "Blood Presence", 48266, 41932, "DeathKnight", "", "Strengthens you with the presence of blood, increasing damage by 2% and heals you for 1% of your damage dealt.    Only one Presence may be active at a time.    Heals up to a maximum of 5% of your health per hit.", "Rare", 0, nil, 5, false, 1, true },
  { "Spell", "Anti-Magic Shell", 48707, 41933, "DeathKnight", "", "Surrounds you in an Anti-Magic Shell, absorbing 75% of the damage dealt by harmful spells (up to a maximum of 50% of your health) and preventing application of harmful magical effects.      20% of the absorbed damage by Anti-Magic Shell is granted as additional rage. Lasts 5 sec.", "Epic", 20, nil, 1, false, 22, true },
  { "Spell", "Blood Boil", 48721, 41934, "DeathKnight", "Rank 1", "Boils the blood of all enemies within 10 yards, dealing 103 to 112 Shadow damage.  Deals additional damage to targets infected with Blood Plague or Frost Fever.", "Normal", 0, nil, 5, false, 16, true },
  { "Spell", "Death Pact", 48743, 41935, "DeathKnight", "Rank 1", "Sacrifices an undead minion, healing you for 20% of its maximum health.", "Epic", 40, nil, 1, false, 22, true },
  { "Spell", "Icebound Fortitude", 48792, 41936, "DeathKnight", "", "Freeze your blood to become immune to Stun effects and reduce all damage taken by 30% plus additional damage reduction based on Defense for 12 sec.", "Legendary", 20, nil, 1, false, 34, true },
  { "Spell", "Obliterate", 49020, 41937, "DeathKnight", "Rank 1", "A brutal instant attack that deals 80% weapon damage plus 28, total damage increased 12.5% per each of your diseases on the target, but consumes the diseases.", "Normal", 0, nil, 5, false, 20, true },
  { "Spell", "Death Grip", 49576, 41939, "DeathKnight", "", "Harness the unholy energy that surrounds and binds all matter, drawing the target towards you and forces them to attack you for 3 sec.", "Epic", 0, nil, 5, false, 20, true },
  { "Spell", "Death Strike", 49998, 41940, "DeathKnight", "Rank 1", "A deadly attack that deals 75% weapon damage plus 23 and heals you for 5% of your maximum health for each of your diseases on the target.", "Rare", 0, nil, 5, false, 14, true },
  { "Spell", "Pestilence", 50842, 41941, "DeathKnight", "", "Spreads existing Blood Plague and Frost Fever infections from your target to all other enemies within 10 yards.", "Normal", 0, nil, 5, false, 10, true },
  { "Spell", "Rune Strike", 56815, 41943, "DeathKnight", "", "Strike the target for 150% weapon damage plus 153. Only usable after you dodge or parry an attack. Can't be dodged, blocked, or parried. This attack causes a high amount of threat.", "Normal", 20, nil, 1, false, 32, true },
  { "Spell", "Horn of Winter", 57330, 41944, "DeathKnight", "Rank 1", "Increases the Strength and Agility of all party or raid members within 30 yards by 2 and generates 10 rage. Lasts 30 min.", "Uncommon", 0, nil, 5, false, 1, true },
  { "Spell", "Raise Ally", 61999, 41945, "DeathKnight", "", "Raises the corpse of a raid or party member to fight by your side. The player will have control over the Ghoul for 5 min.", "Uncommon", 0, nil, 5, false, 24, true },
  { "Spell", "Skull Banner", 954514, 41946, "Warrior", "", "Throw down a war banner at your feet that increases the melee and ranged critical strike chance of party or raid members within 40 yards of the banner by 20%. Lasts 10 sec.  Allies receiving this effect will become Fatigued and unable to benefit from Skull Banner for 3 min.  You can Intervene to your war banner.  This ability is usable while shapeshifted.", "Epic", 0, nil, 1, false, 40, true },
  { "Spell", "Heroic Leap", 86358, 41947, "Warrior", "", "Leap through the air toward a target location, slamming down with destructive force to deal Physical damage and slow all enemies within 8 yards by 50% for 2 sec. While in the air you are immune to crowd control effects.  Usable while shapeshifted.", "Legendary", 0, nil, 0, false, 30, false },
  { "Spell", "Colossus Smash", 86361, 41948, "Warrior", "Rank 1", "Smashes a target for 150% weapon damage, which ignores armor, to weaken their defenses, allowing your attacks to bypass 30% of their armor for 6 sec.", "Rare", 20, nil, 1, false, 30, true },
  { "Spell", "Brilliance Aura", 91234, 41949, "Mage", "", "Restores 2% missing mana every 1 second to all party members within 35 yards for 15 sec.", "Uncommon", 0, nil, 0, false, 16, true },
  { "Spell", "Blinding Light", 954500, 41950, "Paladin", "", "Emits dazzling light in all directions, blinding enemies within 10 yards, causing them to wander disoriented for 6 sec.", "Epic", 124, nil, 0, false, 34, true },
  { "Spell", "Combat Readiness", 86378, 41951, "Rogue", "", "Enter a state of heightened defensive awareness. Each time you're hit by a spell or ability, your overall damage taken is reduced by 5%(3% versus players) for 10 sec. Stacks up to 5 times. Lasts 20 sec or until you have not been attacked for 10 sec.  This ability is usable while shapeshifted.", "Epic", 0, nil, 0, false, 36, true },
  { "Spell", "Smoke Bomb", 954501, 41952, "Rogue", "", "Creates a cloud of thick smoke in an 8 yard radius around you for 5 sec. Enemies are unable to target into or out of the smoke cloud.   This ability is usable while shapeshifted.", "Legendary", 0, nil, 3, false, 36, true },
  { "Spell", "Tame Dragonkin", 91634, 41953, "Mage", "", "Teaches you the necessary abilities to tame a Dragonkin companion.  Teaches you Tame Dragonkin, Call Dragonkin, Dismiss Dragonkin, Revive Dragonkin and Dragonkin Lore.        Tame Dragonkin  Begins taming a dragonkin to be your companion.    Your armor is reduced by 10% while you focus for 20 sec.    If you lose the dragonkin's attention, the taming process will fail.", "Epic", 749, nil, 0, false, 1, false },
  { "Spell", "Leap of Faith", 86381, 41954, "Priest", "", "Pulls the spirit of a party or raid member, moving them to you. The same target can only be affected by this once every 30 seconds.", "Legendary", 187, nil, 0, false, 40, true },
  { "Spell", "Void Shift", 954522, 41955, "Priest", "", "You and the currently targeted party or raid member swap health percentages. Increases the health percentage of you and your ally to 25% if below that amount.  After casting or being targeted by Void Shift you cannot cast or be targeted by it for 1 min.", "Legendary", 156, nil, 0, false, 30, true },
  { "Spell", "Capacitor Totem", 954518, 41956, "Shaman", "Rank 1", "Summons an Air totem with 5 health within 20 yards that gathers electrical energy from the surrounding air and then explodes after 2 sec to deal Nature damage and stun all enemies within 8 yards for 4 sec.  Deals 300% increased damage versus targets permanently immune to stuns.  This ability is usable while shapeshifted.", "Epic", 78, nil, 0, false, 36, true },
  { "Spell", "Bind Elemental", 954520, 41957, "Shaman", "", "Binds the target hostile elemental for up to 50 sec. The bound unit is unable to move, attack or cast spells. Any damage caused will release the target. Only one target can be bound at a time.", "Rare", 124, nil, 0, false, 20, true },
  { "Spell", "Windwalk Totem", 954510, 41958, "Shaman", "", "Summons an Air Totem with 5 health at the feet of the caster for 6 sec, granting party members within 10 yards Windwalk. Their movement speed is increased by 20% and cannot go below 100% speed while affected.    This ability is usable while shapeshifted.", "Epic", 78, nil, 0, false, 20, true },
  { "Spell", "Blood Horror", 954516, 41959, "Warlock", "Rank 1", "While channeling, encases yourself in a barrier of blood, making you immune to interrupts, silences and stuns. Any time an enemy within 15 yards deals non-periodic damage to you, you drain their health and cause them to run in horror for 4 sec.", "Epic", 124, nil, 0, false, 40, true },
  { "Spell", "Soul Harvest", 86395, 41960, "Warlock", "", "Increases your magic damage and your pets' damage by 15%. Lasts 6 sec, increased by 3 sec for each target afflicted by your Corruption, Curse of Agony, Immolate, Shadow Word: Pain and Devouring Plague, up to a maximum of 24 sec.   Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Epic", 0, nil, 0, false, 36, true },
  { "Spell", "Demonic Leap", 954521, 41961, "Warlock", "", "Leap into the air upon demonic wings, moving a short distance. If you reactivate it within 1 sec you will leap again.", "Legendary", 78, nil, 0, false, 30, true },
  { "Spell", "Unending Resolve", 954512, 41962, "Warlock", "", "Hardens your skin, reducing all damage taken by 30% and preventing your spells from being interrupted or silenced for 6 sec.", "Legendary", 124, nil, 0, false, 40, true },
  { "Spell", "Hand of Gul'dan", 954611, 41964, "Warlock", "", "Calls down a demonic meteor dealing Shadowflame damage to enemies within 5 yards and summons 4 Wild Imps which burst forth to attack the target for 10 sec.", "Normal", 187, nil, 0, false, 32, true },
  { "Spell", "Efflorescence", 86382, 41965, "Druid", "", "Restores health to allies within 15 yards of the initial target every 2 sec and increases the caster's healing on affected targets by 18% for 6 sec.", "Epic", 124, nil, 0, false, 44, true },
  { "Spell", "Stampeding Roar", 954508, 41966, "Druid", "", "You roar, increasing the movement speed of all party members within 10 yards by 60% for 6 sec. Does not break prowling.", "Epic", 0, nil, 0, false, 28, true },
  { "Spell", "Mass Entanglement", 954507, 41967, "Druid", "", "Roots the target and all enemies within 8 yards in place for 8 sec. 6 sec versus players. Damage may interrupt the effect.  When the effect breaks, the target is slowed by 30% for 3 sec.  Usable while shapeshifted.  This spell cannot miss. ", "Epic", 109, nil, 0, false, 18, true },
  { "Spell", "Ursol's Vortex", 954504, 41968, "Druid", "", "Conjures a vortex of wind for 8 sec around yourself, reducing the movement speed of all enemies within 5 yards by 30%. When an enemy leaves the vortex, winds will pull that enemy back to its center.     Enemies can only get pulled from any vortex once every 8 seconds.  This ability is usable while shapeshifted.", "Epic", 0, nil, 3, false, 40, true },
  { "Spell", "Solar Beam", 954523, 41969, "Druid", "", "You summon a beam of solar light, silencing all enemies under the beam while it is active. Solar Beam lasts for 6 sec.  This ability is usable while shapeshifted.", "Epic", 0, nil, 0, false, 34, true },
  { "Spell", "Mana-forged Barrier", 701463, 41990, "Mage", "", "Your threat generated is significantly increased.    Teaches you Channeled Mana .        Channeled Mana  46 Mana  Taunts the target to attack you, but has no effect if the target is already attacking you.    This spell is learned when you have a Tank Stance and cannot be unlearned. ", "Epic", 0, nil, 0, false, 1, true },
  { "Spell", "Invocation", 986067, 41991, "Mage", "", "Channel potent energies, reducing damage taken by 30% and periodically discharge projectiles of raw mana, dealing high-threat Magic damage to nearby enemies. Lasts 3 seconds.    While channeling you are immune to Stun effects.", "Rare", 0, nil, 0, false, 14, true },
  { "Spell", "Alter Time", 86397, 41992, "Mage", "", "Alter the fabric of time, causing the caster to return to their current location, their health and mana, when cast a second time, or after 4 sec. Any self-applied, magic dispellable effects are also returned to their previous state.  Effect negated if the caster dies within the 4 sec or before the effect occurs, or moves too far away.", "Legendary", 0, nil, 0, false, 40, true },
  { "Spell", "Earthquake", 954524, 41993, "Shaman", "Rank 1", "You cause the earth to tremble at your target location, dealing Nature damage every 1 sec to enemies within an 8 yard radius and reducing their movement speed by 25%. Lasts 8 sec.  Enemies damaged by Earthquake are afflicted with Trembling. At 3 stacks, Trembling stuns the target for 3 sec. This effect can only occur once every 10 sec from any Earthquake effect.", "Epic", 671, nil, 0, false, 20, true },
  { "Spell", "Frenzy Shot", 954587, 41994, "Hunter", "Rank 1", "Fires a shot, dealing 150% weapon damage. This sends your pet into a frenzy, causing its auto attacks to trigger an additional attack that strikes up to 5 nearby enemies for 8 sec.", "Epic", 140, nil, 0, false, 20, true },
  { "Spell", "Arcane Ward", 92171, 42008, "Mage", "Rank 1", "Absorbs 165 Arcane damage. Lasts 30 sec.  This ability is usable while shapeshifted.", "Rare", 249, nil, 0, false, 14, true },
  { "Spell", "Raging Blow", 954836, 42017, "Warrior", "", "A mighty blow that deals 125% weapon damage from both melee weapons. Requires a weapon in the mainhand and off-hand to use.  Becoming Enraged enables one use of Raging Blow. You can store up to 2 charges.    Multiple Raging Blow! charges cannot be gained within the same global cooldown.", "Normal", 30, nil, 1, false, 28, true },
  { "Spell", "Bloodbath", 954814, 42018, "Warrior", "Rank 1", "For the next 5 sec, causes your Physical melee abilities to deal 77 bleed damage over 5 sec and reduces the movement speed of the target by 30% for 3 sec.    This ability can be used while shapeshifted.", "Epic", 0, nil, 0, false, 40, true },
  { "Spell", "Halo", 954803, 42019, "Priest", "Rank 1", "Creates a ring of Holy energy around you that quickly expands and grows in power, healing raid and party members up to 30 yds away. Heals with greater effect the further away the ally is. Also increases the Holy healing taken from the caster by 8%.", "Epic", 593, nil, 0, false, 36, true },
  { "Spell", "Ring of Frost", 954854, 42020, "Mage", "", "Summons a Ring of Frost at the target location. Enemies entering the ring will become frozen for 6 sec. Lasts 8 sec and has an 8 yard radius.", "Epic", 234, nil, 0, false, 36, true },
  { "Spell", "Soul Swap", 954614, 42021, "Warlock", "", "You copy your damage-over-time effects from the target, preserving their power and duration.  For 5 sec afterwards, the next target you cast Soul Swap: Exhale on will be afflicted by the copied damage-over-time effects.  You cannot Soul Swap to the same target.", "Epic", 93, nil, 0, false, 28, true },
  { "Spell", "Air Ascendance", 954831, 42022, "Shaman", "", "You surrender your physical form to the power of the elements, transforming into a being of raw elemental energy for 15 sec.     Your Stormstrike has a 30 yard range and deals extra Elemental damage.    The cooldown of Stormstrike is reset when using any Shaman Shock, Lightning Bolt or Chain Lightning.", "Epic", 109, nil, 0, false, 40, true },
  { "Spell", "Healing Rain", 954861, 42023, "Shaman", "Rank 1", "Calls forth healing rains to blanket the area, restoring health over time up to 5 party or raid members in a 10 yard area every 2 sec for 8 sec. This periodic effect can critically strike.", "Normal", 531, nil, 0, false, 24, true },
  { "Spell", "Light's Hammer", 954801, 42024, "Paladin", "Rank 1", "Hurl a Light-infused hammer into the ground, where it will blast a 10 yard area with Arcing Light for 10 sec.  Deals Holy damage to enemies and reduces their movement speed by 50% for 3 sec. Also heals up to 5 allies every 2 sec.", "Epic", 593, nil, 0, false, 36, true },
  { "Spell", "Execution Sentence", 954817, 42025, "Paladin", "Rank 1", "A hammer slowly falls from the sky, causing Holy damage if the target is an enemy and healing if the target is an ally, over 10 sec.     This culminates in a final burst of damage or healing. Dispelling the effect triggers the final burst.", "Rare", 124, nil, 0, false, 40, true },
  { "Spell", "Burning Rush", 954806, 42026, "Warlock", "", "Drains 5% of your maximum health every 2 seconds to increase your movement speed by 50%. This damage does not break crowd control effects.     Allows you to cast Fire spells while moving, and movement-impairing effects may not reduce you below 100% of normal movement speed. Lasts for 6 sec.", "Legendary", 0, nil, -2, false, 40, true },
  { "Spell", "Crimson Tempest", 954809, 42027, "Rogue", "Rank 1", "Finishing move that slashes at the flesh of all enemies within 8 yards, dealing Physical damage and causing them to bleed per combo point:     1 point: 44 damage and 66 damage over 8 sec     2 points: 97 damage and 98 damage over 8 sec     3 points: 181 damage and 148 damage over 8 sec     4 points: 296 damage and 213 damage over 8 sec     5 points: 441 damage and 296 damage over 8 sec", "Normal", 35, nil, 3, false, 14, true },
  { "Spell", "Shuriken Toss", 954835, 42028, "Rogue", "Rank 1", "A ranged attack that deals 260 to 260 Physical damage to an enemy target. Awards 1 combo point.", "Normal", 50, nil, 3, false, 14, true },
  { "Spell", "Demoralizing Banner", 955062, 42029, "Warrior", "", "Throw down a war banner that decreases the armor of all enemies within 30 yards by 20% and their critical strike chance by 10%. Lasts 15 sec. Does not stack with other similar effects.  You can Intervene to your war banner.  This ability can be used while shapeshifted.", "Epic", 0, nil, 1, false, 32, true },
  { "Spell", "Elemental Blast", 954807, 42030, "Shaman", "Rank 1", "Harness and direct the raw power of the elements towards an enemy target, dealing Elemental damage and increasing the caster's critical strike chance or spell casting speed for 8 seconds.", "Normal", 109, nil, 0, false, 40, true },
  { "Spell", "Starsurge", 954800, 42031, "Druid", "Rank 1", "Deals 218 to 260 Spellstorm damage to the target.", "Normal", 109, nil, 0, false, 28, true },
  { "Spell", "Tether Elemental", 91606, 42032, "Shaman", "", "Teaches you the necessary abilities to tether an Elemental companion.    Teaches you Tether Elemental, Raise Elemental, Dismiss Elemental, Revive Elemental and Elemental Lore.        Tether Elemental  Begins tethering an elemental to be your companion.     Your armor is reduced by 100% while you focus on dominating the elemental for 20 sec.     If you lose the elemental's attention for any reason, the domination process will fail.     Each type of elemental has unique abilities that you will be able to make use of.", "Epic", 749, nil, 0, false, 1, false },
  { "Spell", "Siegebreaker", 954876, 42033, "Warrior", "Rank 1", "Use your full strength to slam the target with your weapon, dealing 150% weapon damage to up to 5 nearby enemies in a conal attack.  If the target is a player, it also knocks them back. Enemies the target collides with are knocked back slightly and take 150% weapon damage.", "Epic", 0, nil, 0, false, 40, true },
  { "Spell", "Arcane Orb", 955032, 42034, "Mage", "Rank 1", "Launches an Arcane Orb forward from your position, traveling up to 35 yards, dealing 415 Arcane damage every 0.5 sec to enemies it passes through and increasing their Arcane damage taken from you by 10%.     Subsequent hits on the same target deals 50% less damage.", "Epic", 281, nil, 0, false, 40, true },
  { "Spell", "Glaive Toss", 954821, 42035, "Hunter", "Rank 1", "You hurl two glaives toward the target, each dealing 75% weapon damage.", "Normal", 156, nil, 0, false, 12, true },
  { "Spell", "Petrification Totem", 956046, 42036, "Shaman", "", "Summons a Petrification Totem with 5 health at your feet for 5 sec, slowing enemies within 8 yards. After 3 seconds, it Petrifies  enemies for 5 seconds.      Petrified  Asleep. Damage taken reduced by 50%. Effect breaks on any damage taken. This ability is usable while shapeshifted.", "Epic", 93, nil, 0, false, 40, true },
  { "Spell", "Hypnosis", 955072, 42037, "Druid", "", "Forces the enemy target to sleep for 30 sec (6 sec versus players). Any damage taken will be increased by 10%, but will awaken the target. Only one target can be forced to sleep at a time.     This spell is castable while moving.", "Epic", 187, nil, 0, false, 30, true },
  { "Spell", "Frost Armor", 168, 42039, "Mage", "Rank 1", "Increases Armor by 36.    If an enemy strikes the caster, they may have their movement slowed by 15% and the time between their attacks increased by 20% for 5 sec.   Lasts until cancelled.    Does not stack with other similar effects. Only one type of Mage armor spell can be active at any time.", "Rare", 374, nil, 0, false, 1, true },
  { "Spell", "Devotion Aura", 465, 42040, "Paladin", "Rank 1", "Gives 40 additional armor to party and raid members within 40 yards.      Players may only have one Aura on them per Paladin at any one time.", "Uncommon", 0, nil, 0, false, 1, true },
  { "Spell", "Fire Ward", 543, 42041, "Mage", "Rank 1", "Absorbs 165 Fire damage.  Lasts 30 sec.  This ability is usable while shapeshifted.", "Rare", 249, nil, 0, false, 14, true },
  { "Spell", "Aspect of the Cheetah", 5118, 42043, "Hunter", "", "You take on the aspects of a cheetah, increasing movement speed by 30%.  If struck, you will be dazed for 4 sec.      Only one Aspect can be active at a time.", "Rare", 0, nil, 0, false, 14, true },
  { "Spell", "Mage Armor", 6117, 42044, "Mage", "Rank 1", "Increases your resistance to all magic by 5 and allows 50% of your mana regeneration to continue while casting. In addition, the duration of all harmful Magic effects used against you is reduced by 30%. Lasts until cancelled.    Only one type of Mage Armor spell can be active at any time.", "Rare", 406, nil, 0, false, 14, true },
  { "Spell", "Frost Ward", 6143, 42045, "Mage", "Rank 1", "Absorbs 165 Frost damage.  Lasts 30 sec.  This ability is usable while shapeshifted.", "Rare", 218, nil, 0, false, 14, true },
  { "Spell", "Retribution Aura", 7294, 42046, "Paladin", "Rank 1", "Causes 11 Holy damage to any enemy that strikes a party or raid member within 40 yards.      Players may only have one Aura on them per Paladin at any one time.", "Uncommon", 0, nil, 0, false, 16, true },
  { "Spell", "Flametongue Weapon", 8024, 42048, "Shaman", "Rank 1", "Imbue your weapon with fire, increasing total Spell power by 7. Each auto attack and melee ability causes 4.2 to 13.0 additional fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. This effect lasts for 2 hours.", "Rare", 93, nil, 0, false, 10, true },
  { "Spell", "Frostbrand Weapon", 8033, 42049, "Shaman", "Rank 1", "Imbue your weapon with frost. Each hit has a chance of causing 31 additional Frost damage and slowing the target's movement speed by 50% for 8 sec. This effect lasts for 2 hours.", "Rare", 93, nil, 0, false, 20, true },
  { "Spell", "Windfury Weapon", 8232, 42050, "Shaman", "Rank 1", "Imbue your weapon with wind.  Each hit has a 20% chance of dealing additional damage equal to two extra attacks with 46 extra attack power.    This effect lasts for 2 hours.", "Rare", 109, nil, 0, false, 30, true },
  { "Spell", "Aspect of the Pack", 13159, 42051, "Hunter", "", "The hunter and raid members within 40 yards take on the aspects of a pack of cheetahs, increasing movement speed by 30%.      If you are struck under the effect of this aspect, you will be dazed for 4 sec.    Only one Aspect can be active at a time.", "Rare", 0, nil, 0, false, 40, true },
  { "Spell", "Aspect of the Beast", 13161, 42052, "Hunter", "", "Take on the Aspects of a Beast, becoming untrackable and increasing melee attack power by 10% for you and your pet.      Only one Aspect can be active at a time.", "Rare", 0, nil, 0, false, 30, false },
  { "Spell", "Aspect of the Monkey", 13163, 42053, "Hunter", "", "The hunter takes on the aspects of a monkey, increasing chance to dodge by 10%.      Only one Aspect can be active at a time.", "Rare", 0, nil, 0, false, 10, true },
  { "Spell", "Aspect of the Hawk", 13165, 42054, "Hunter", "Rank 1", "The hunter takes on the aspects of a hawk, increasing ranged attack power by 11.      Only one Aspect can be active at a time.", "Rare", 0, nil, 0, false, 1, true },
  { "Spell", "Concentration Aura", 19746, 42055, "Paladin", "", "All party or raid members within 40 yards lose 35% less casting or channeling time when damaged.    Players may only have one Aura on them per Paladin at any one time.", "Uncommon", 0, nil, 0, false, 1, true },
  { "Spell", "Shadow Resistance Aura", 19876, 42056, "Paladin", "Rank 1", "Gives 30 additional Shadow resistance to all party and raid members within 40 yards.      Players may only have one Aura on them per Paladin at any one time.", "Uncommon", 0, nil, 0, false, 28, true },
  { "Spell", "Frost Resistance Aura", 19888, 42057, "Paladin", "Rank 1", "Gives 30 additional Frost resistance to all party and raid members within 40 yards.      Players may only have one Aura on them per Paladin at any one time.", "Uncommon", 0, nil, 0, false, 32, true },
  { "Spell", "Fire Resistance Aura", 19891, 42058, "Paladin", "Rank 1", "Gives 30 additional Fire resistance to all party and raid members within 40 yards.      Players may only have one Aura on them per Paladin at any one time.", "Uncommon", 0, nil, 0, false, 36, true },
  { "Spell", "Judgement of Light", 20271, 42060, "Paladin", "", "Unleashes the energy of a Seal spell to judge an enemy for 20 sec, granting auto attacks and auto shots made against the judged enemy a chance of healing the attacker for 2% of their base health.      Refer to individual Seals for additional Judgement effect.    Only one Judgement per Paladin can be active at any one time.", "Rare", 78, nil, 0, false, 1, true },
  { "Spell", "Fel Armor", 28176, 42061, "Warlock", "Rank 1", "Surrounds you with fel energy, increasing spell damage by 40 plus 30% of your Spirit.   Restores 2% of your max health every 5 sec.     Only one Armor spell can be active at a time. Lasts until cancelled.", "Rare", 437, nil, 0, false, 40, true },
  { "Spell", "Molten Armor", 30482, 42062, "Mage", "Rank 1", "Causes 88 Fire damage when hit.    Increases your critical strike rating by 10% of your Spirit.    Reduces the chance you are critically hit by 5%.      Lasts until cancelled.    Only one type of Mage Armor spell can be active at any time.", "Rare", 437, nil, 0, false, 44, true },
  { "Spell", "Crusader Aura", 32223, 42063, "Paladin", "", "Increases the mounted speed by 20% for all party and raid members within 40 yards.  Players may only have one Aura on them per Paladin at any one time.     This does not stack with other movement speed increasing effects.", "Uncommon", 0, nil, 0, false, 60, true },
  { "Spell", "Aspect of the Viper", 34074, 42064, "Hunter", "", "The hunter takes on the aspect of the viper, causing ranged and melee attacks a chance to regenerate mana.    Damage and healing done reduced by 40%.     You gain 4% of maximum mana every 3 sec.   Only one Aspect can be active at a time.", "Rare", 0, nil, 0, false, 20, true },
  { "Spell", "Earthliving Weapon", 51730, 42065, "Shaman", "Rank 1", "Imbue your weapon with earthen life. Increases healing done by 26 and each direct heal has a 20% chance to proc Earthliving on the target, healing an additional 64 over 12 sec. This effect lasts for 2 hours.", "Rare", 93, nil, 0, false, 30, true },
  { "Spell", "Judgement of Justice", 53407, 42066, "Paladin", "", "Unleashes the energy of a Seal spell to judge an enemy for 20 sec, preventing them from fleeing and limiting their movement speed.      Refer to individual Seals for additional Judgement effect.    Only one Judgement per Paladin can be active at any one time.", "Rare", 78, nil, 0, false, 28, true },
  { "Spell", "Judgement of Wisdom", 53408, 42067, "Paladin", "", "Unleashes the energy of a Seal spell to judge an enemy for 20 sec, giving each attack a chance to restore 2% of the attacker's base mana.     Refer to individual Seals for additional Judgement effect.    Only one Judgement per Paladin can be active at any one time.", "Rare", 78, nil, 0, false, 1, true },
  { "Spell", "Aspect of the Dragonhawk", 61846, 42068, "Hunter", "Rank 1", "The hunter takes on the aspects of a dragonhawk, increasing ranged attack power by 120 and chance to dodge by 10%.    Only one Aspect can be active at a time.", "Rare", 0, nil, 0, false, 60, true },
  { "Spell", "Defensive Stance", 71, 42069, "Warrior", "", "Significantly Increases your threat generation.    Increases your armor by 10% and decreases damage taken by 10%.    Your damage and healing done is decreased by 5%.     Teaches you Taunt .", "Rare", 0, nil, 1, false, 1, true },
  { "Spell", "Commanding Shout", 469, 42070, "Warrior", "Rank 1", "Increases maximum health of all party and raid members within 30 yards by 266. Lasts 30 min.   Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Uncommon", 10, nil, 1, false, 60, true },
  { "Spell", "Summon Felhunter", 691, 42071, "Warlock", "Summon", "Summons a Felhunter under the command of the Warlock.", "Epic", 1249, nil, 0, false, 30, true },
  { "Spell", "Summon Succubus", 712, 42072, "Warlock", "Summon", "Summons a Succubus under the command of the Warlock.", "Epic", 1249, nil, 0, false, 20, true },
  { "Spell", "Cat Form", 768, 42073, "Druid", "Shapeshift", "Shapeshift into cat form, increasing melee attack power by 60 plus 25% of Agility. Allows the use of various cat abilities.", "Epic", 546, nil, 0, false, 1, true },
  { "Spell", "Demoralizing Shout", 1160, 42074, "Warrior", "Rank 1", "Reduces the attack power of all enemies within 10 yards by 35 for 30 sec.   Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Uncommon", 10, nil, 1, false, 10, true },
  { "Spell", "Freezing Trap", 1499, 42075, "Hunter", "Rank 1", "Place a frost trap that freezes the first enemy that approaches, preventing all action for up to 10 sec.(8 seconds against players).    Any damage caused will break the ice.   Trap will exist for 30 sec.   Only one trap can be active at a time.", "Epic", 46, nil, 0, false, 20, true },
  { "Spell", "Create Spellstone", 2362, 42076, "Warlock", "Rank 1", "While applied to target weapon it increases damage dealt by periodic spells by 2% and spell haste rating by 7. This effect lasts for 2 hours.    You can only benefit from one Warlock weapon enchant at a time.", "Rare", 702, nil, 0, false, 28, true },
  { "Spell", "Battle Stance", 2457, 42077, "Warrior", "", "A balanced combat stance that increases the armor penetration of all of physical attacks by 10%.", "Rare", 0, nil, 1, false, 1, true },
  { "Spell", "Berserker Stance", 2458, 42078, "Warrior", "", "An aggressive stance. Critical hit chance is increased by 3% and all damage taken is increased by 5%.", "Rare", 0, nil, 1, false, 30, true },
  { "Spell", "Searing Totem", 3599, 42079, "Shaman", "Rank 1", "Summons a Searing Totem with 5 health at your feet for 45 sec that repeatedly attacks an enemy within 20 yards for 11 to 14 Fire damage.  This ability is usable while shapeshifted.", "Rare", 109, nil, 0, false, 1, true },
  { "Spell", "Wrath of Air Totem", 3738, 42080, "Shaman", "", "Summons a Wrath of Air Totem with 5 health at the feet of the caster. The totem provides 5% spell haste to all party and raid members within 50 yards. Lasts 5 min.   Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Uncommon", 171, nil, 0, false, 40, true },
  { "Spell", "Slice and Dice", 5171, 42081, "Rogue", "Rank 1", "Finishing move that increases melee attack speed by 20%. Lasts longer per combo point:     1 point  : 9 seconds     2 points: 12 seconds     3 points: 15 seconds     4 points: 18 seconds     5 points: 21 seconds    This ability is usable while shapeshifted.", "Rare", 25, nil, 3, false, 1, true },
  { "Spell", "Healing Stream Totem", 5394, 42082, "Shaman", "Rank 1", "Summons a Healing Stream Totem with 5 health at the feet of the caster for 5 min that heals group members within 30 yards for 6 every 2 seconds.  This ability is usable while shapeshifted.", "Uncommon", 46, nil, 0, false, 16, true },
  { "Spell", "Mana Spring Totem", 5675, 42084, "Shaman", "Rank 1", "Summons a Mana Spring Totem with 5 health at the feet of the caster for 5 min that restores 16 mana every 5 seconds to all party and raid members within 30 yards.   Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Uncommon", 62, nil, 0, false, 26, true },
  { "Spell", "Stoneclaw Totem", 5730, 42085, "Shaman", "Rank 1", "Summons a Stoneclaw Totem with 206 health at the feet of the caster for 15 sec that taunts creatures within 8 yards to attack it.  Enemies attacking the Stoneclaw Totem have a 50% chance to be stunned for 3 sec. Stoneclaw totem also protects all your totems, causing them to absorb 21 damage.  This ability is usable while shapeshifted.", "Uncommon", 93, nil, 0, false, 1, true },
  { "Spell", "Create Firestone", 6366, 42086, "Warlock", "Rank 1", "While applied to target weapon it increases damage dealt by spells by 1% and spell critical strike rating by 7. This effect lasts for 2 hours.     You can only benefit from one Warlock weapon enchant at a time.", "Rare", 843, nil, 0, false, 28, true },
  { "Spell", "Stoneskin Totem", 8071, 42088, "Shaman", "Rank 1", "Summons a Stoneskin Totem with 5 health at the feet of the caster. The totem protects party and raid members within 50 yards, increasing armor by 95. Lasts 5 min.   This ability is usable while shapeshifted.", "Uncommon", 156, nil, 0, false, 1, true },
  { "Spell", "Strength of Earth Totem", 8075, 42089, "Shaman", "Rank 1", "Summons a Strength of Earth Totem with 5 health at the feet of the caster. The totem increases the Strength and Agility of all party and raid members within 50 yards by 8. Lasts 5 min.   Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Uncommon", 156, nil, 0, false, 10, true },
  { "Spell", "Frost Resistance Totem", 8181, 42090, "Shaman", "Rank 1", "Summons a Frost Resistance Totem with 5 health at the feet of the caster for 5 min. The totem increases party and raid members' frost resistance by 30, if within 50 yards.  This ability is usable while shapeshifted.", "Uncommon", 124, nil, 0, false, 24, true },
  { "Spell", "Fire Resistance Totem", 8184, 42091, "Shaman", "Rank 1", "Summons a Fire Resistance Totem with 5 health at the feet of the caster for 5 min that increases the fire resistance of party and raid members within 50 yards by 30.  This ability is usable while shapeshifted.", "Uncommon", 124, nil, 0, false, 28, true },
  { "Spell", "Magma Totem", 8190, 42092, "Shaman", "Rank 1", "Summons a Magma Totem with 5 health at the feet of the caster for 20 sec that causes 38 Fire damage to creatures within 8 yards every 2 seconds.  This ability is usable while shapeshifted.", "Rare", 421, nil, 0, false, 26, true },
  { "Spell", "Flametongue Totem", 8227, 42093, "Shaman", "Rank 1", "Summons a Flametongue Totem with 5 health at the feet of the caster.  Party and raid members within 50 yards of the totem have their Intellect increased by 2 and spell power increased by 2.  Lasts 5 min.   Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Rare", 171, nil, 0, false, 10, true },
  { "Spell", "Windfury Totem", 8512, 42094, "Shaman", "", "Summons a Windfury Totem with 5 health at the feet of the caster. The totem provides 16% melee haste to all party and raid members within 50 yards.  Lasts 5 min.  This ability is usable while shapeshifted.", "Uncommon", 171, nil, 0, false, 32, true },
  { "Spell", "Expose Armor", 8647, 42095, "Rogue", "", "Finishing move that exposes the target, reducing armor by 20% and lasting longer per combo point:    1 point  : 6 sec.    2 points: 12 sec.    3 points: 18 sec.    4 points: 24 sec.    5 points: 30 sec.   Does not stack with other similar effects.", "Rare", 25, nil, 3, false, 14, true },
  { "Spell", "Nature Resistance Totem", 10595, 42096, "Shaman", "Rank 1", "Summons a Nature Resistance Totem with 5 health at the feet of the caster for 5 min that increases the nature resistance of party and raid members within 50 yards by 30.  This ability is usable while shapeshifted.", "Uncommon", 124, nil, 0, false, 30, true },
  { "Spell", "Frost Trap", 13809, 42097, "Hunter", "", "Place a frost trap that creates an ice slick around itself for 30 sec when the first enemy approaches it. All enemies within 10 yards will be slowed by 50% while in the area of effect. Trap will exist for 30 sec. Only one trap can be active at a time.", "Epic", 31, nil, 0, false, 20, true },
  { "Spell", "Blessing of Might", 19740, 42098, "Paladin", "Rank 1", "Places a Blessing on the friendly target, increasing their Strength and Agility by 2 for 30 min.   Does not stack with other similar effects.", "Uncommon", 78, nil, 0, false, 1, true },
  { "Spell", "Blessing of Wisdom", 19742, 42099, "Paladin", "Rank 1", "Places a Blessing on the friendly target, restoring 10 mana every 5 seconds for 30 min.   Does not stack with other similar effects.", "Uncommon", 78, nil, 0, false, 1, true },
  { "Spell", "Seal of Justice", 20164, 42100, "Paladin", "", "Fills the Paladin with the spirit of justice for until cancelled, giving each melee attack a chance to stun for 2 sec. This effect has a 10 second cooldown. Only one Seal can be active at any one time.  Unleashing this Seal's energy will deal 167 Holy damage to an enemy.", "Rare", 218, nil, 0, false, 22, true },
  { "Spell", "Seal of Light", 20165, 42101, "Paladin", "", "Fills you with divine light for until cancelled, giving each melee auto attack a chance to heal you for 74. This effect can only occur once every 2 seconds. Only one Seal can be active at any one time.    Unleashing this Seal's energy will deal 167 Holy damage to an enemy.", "Rare", 218, nil, 0, false, 30, true },
  { "Spell", "Seal of Wisdom", 20166, 42102, "Paladin", "", "Fills you with divine wisdom for until cancelled, giving each melee auto attack a chance to restore 4% of your total mana. Only one Seal can be active at any one time.    Unleashing this Seal's energy will deal 167 Holy damage to an enemy.", "Rare", 218, nil, 0, false, 10, true },
  { "Spell", "Blessing of Kings", 20217, 42103, "Paladin", "", "Places a Blessing on the friendly target, increasing total stats by 10% for 30 min.    Does not stack with other similar effects.", "Uncommon", 93, nil, 0, false, 20, true },
  { "Spell", "Seal of Righteousness", 21084, 42104, "Paladin", "", "Fills you with holy spirit for until cancelled, granting each main hand auto attack and Paladin melee ability 24 additional Holy damage. Only one Seal can be active at any one time.  Unleashing this Seal's energy will cause 209 Holy damage to an enemy.", "Rare", 218, nil, 0, false, 1, true },
  { "Spell", "Seal of Vengeance", 31801, 42105, "Paladin", "", "Fills you with holy power, causing main hand auto and Paladin melee abilities to apply Holy Vengeance, which deals 77 additional Holy damage over 15 sec.    Holy Vengeance can stack up to 5 times. Once stacked to 5 times, each of your main hand auto attacks and Paladin melee abilities deals damage as additional Holy damage. Only one Seal can be active on the caster at any one time. Lasts until cancelled.  Unleashing this Seal's energy will deal 137 Holy damage to an enemy, increased by 10% for each application of Holy Vengeance on the target.", "Rare", 218, nil, 0, false, 44, true },
  { "Spell", "Snake Trap", 34600, 42106, "Hunter", "", "Place a trap that will release several venomous snakes to attack the first enemy to approach. The snakes will die after 15 sec. Trap will exist for 30 sec. Only one trap can be active at a time.", "Epic", 140, nil, 0, false, 60, true },
  { "Spell", "Recuperate", 965425, 42107, "Rogue", "", "Finishing move that consumes combo points on your target to restore 3% of your maximum health every 3 sec. Lasts longer per combo point:    1 point : 3 seconds    2 points: 6 seconds    3 points: 9 seconds    4 points: 12 seconds    5 points: 15 seconds", "Rare", 25, nil, 3, false, 1, true },
  { "Spell", "Meditate", 965426, 42108, "Rogue", "", "Finishing move that consumes combo points on any nearby target to restore 6% of your base mana every 2 sec. Lasts longer per combo point:    1 point  : 18% base mana over 6  secs    2 points: 36% base mana over 12  secs     3 points: 54% base mana over 18  secs    4 points: 72% base mana over 24  secs    5 points: 90% base mana over 30 secs", "Rare", 30, nil, 3, false, 10, true },
  { "Spell", "Summon Voidwalker", 697, 42113, "Warlock", "Summon", "Summons a Voidwalker under the command of the Warlock.", "Epic", 1249, nil, 0, false, 10, true },
  { "Spell", "Shadow Ward", 6229, 42114, "Warlock", "Rank 1", "Absorbs 290 Shadow damage. Lasts 30 sec.  This ability is usable while shapeshifted.", "Rare", 187, nil, 0, false, 32, true },
  { "Spell", "Summoner's Armor", 701521, 42115, "Warlock", "", "Empowers your tamed beast, tamed dragonkin, dominated undead, enslaved demon, summoned demon, wild imp or tethered elemental, increasing their critical strike chance with spells and abilities by 2% and their spell damage done by 3%.  Only one type of Warlock Armor spell can be active at any time.", "Rare", 484, nil, 0, false, 1, true },
  { "Spell", "Divine Missiles", 275434, 42121, "Classless", "Rank 1", "Launches Divine Missiles at the enemy, causing 43 Divine damage every 0.98 sec for 2.93 sec.    This uses Arcane Missiles modifiers.", "Normal", 485, nil, 0, false, 10, true },
  { "Spell", "Divine Blast", 275433, 42122, "Classless", "Rank 1", "Blasts the target with energy, dealing 210 Divine damage.     Casting this increases all Arcane damage by 15% and its mana cost by 150%. Stacks up to 4 and lasts 6 sec, removed if you cast another Arcane ability that deals damage.     This uses Arcane Blast modifiers.", "Normal", 109, nil, 0, false, 18, true },
  { "Spell", "Divine Barrage", 275465, 42123, "Classless", "Rank 1", "Launches several missiles at the enemy target, causing 294 Divine damage.     This uses Arcane Barrage modifiers.", "Normal", 281, nil, 0, false, 40, true },
  { "Spell", "Poison Mastery", 2842, 42435, "Rogue", "", "You gain Poison Mastery when learning any Rogue Poison.     This Mastery automatically unlocks additional Essential Rogue Poisons when you reach their Class Point requirements at no additional ability essence cost.     Instant Poison  Coats a melee or ranged weapon with a poison that deals nature damage.      Crippling Poison  Coats a weapon with crippling poison that slows the target.     Mind-numbing Poison  Coats a weapon with mind-numbing poison that reduces their casting speed.     Deadly Poison  Coats your weapon with a deadly poison that causes your targets to take Nature damage over times and stacks up.      Wound Poison  Coats your weapon with a poison that deals Nature damage and reduces the target's healing received.      Anesthetic Poison  Coats your weapon with poison that deals Nature damage and dispels Enrage effects on your target.", "Rare", 0, nil, 0, false, 16, true },
  { "Spell", "Tracking Mastery", 801494, 42436, "Hunter", "", "You gain Tracking Mastery when learning any Tracking Ability.     This Mastery automatically unlocks additional Tracking Abilities when you reach their Class Point requirements at no additional ability essence cost.      Track Beasts  Shows the location of all nearby beasts on the minimap and increases damage dealt to beasts by 1%.      Track Humanoids  Shows the location of all nearby humanoids on the minimap.      Track Undead  Shows the location of all nearby undead on the minimap and increases damage dealts to undead by 1%.      Track Elementals  Shows the location of all nearby elementals on the minimap and increases damage dealt to elementals by 1%.      Track Demons  Shows the location of all nearby demons on the minimap and increases damage dealt to demons by 1%.      Track Giants  Shows the location of all nearby giants on the minimap and increases damage dealt to giants by 1%.      Track Dragonkin  Shows the location of all nearby dragonkin on the minimap and increases damage dealt to dragonkin by 1%.      Track Hidden  Greatly increases stealth detection and shows hidden units within detection range on the minimap.     Only one form of tracking can be active at a time.", "Uncommon", 0, nil, 0, false, 10, true },
  { "Spell", "Runeforging Mastery", 53428, 42437, "DeathKnight", "", "You gain Runeforging Mastery when learning any Runeforge Spell.     This Mastery automatically unlocks Runeforge Spells when you reach their Class Point requirements at no additional ability essence cost.        Rune of Swordshattering  Affixes your two-handed weapon with a rune that increases parry chance and reduces the duration of disarms.      Rune of Lichbane  Affixes your weapon with a rune that causes you to deal Fire damage with your attacks, increased versus undead.      Rune of Cinderglacier  Affixes your weapon with a rune that has a chance to increase the damage of your next 2 attacks that deal Frost or Shadow damage.      Rune of Spellshattering  Affixes your two-handed weapon with a rune that deflects spell damage and reduces the duration of silence efffects.      Rune of Razorice  Affixes your weapon with a rune that causes extra Frost damage when you attack and causes them to be more vulnerable to your Frost attacks.      Rune of the Fallen Crusader  Affixes your weapon with a rune that has a chance to heal you and increase your Strength.      Rune of the Stoneskin Gargoyle  Affixes your two-handed weapon with a rune that increases your defense and Stamina.      Rune of the Nerubian Carapace  Affixes your weapon with a rune that increases your defense and Stamina.", "Rare", 0, nil, 0, false, 20, true },
  { "Spell", "Aether Strike", 903000, 43000, "Classless", "Rank 1", "An instant arcane-infused strike that causes 3 Spellstrike damage in addition to 65% of your normal weapon damage (85% of that amount if a Two-Handed weapon is equipped). Awards 1 combo point.    This uses Sinister Strike modifiers.", "Normal", 45, nil, 3, false, 1, true },
  { "Spell", "Void Strike", 903012, 43001, "Classless", "Rank 1", "An instant shadow-infused strike that causes 3 Shadowstrike damage in addition to 65% of your normal weapon damage (85% of that amount if a Two-Handed weapon is equipped). Awards 1 combo point.    This uses Sinister Strike modifiers.", "Normal", 45, nil, 3, false, 1, true },
  { "Spell", "Cinder Strike", 903024, 43002, "Classless", "Rank 1", "An instant fire-infused strike that causes 3 Firestrike damage in addition to 65% of your normal weapon damage (85% of that amount if a Two-Handed weapon is equipped). Awards 1 combo point.    This uses Sinister Strike modifiers.", "Normal", 45, nil, 3, false, 1, true },
  { "Spell", "Rime Strike", 903036, 43003, "Classless", "Rank 1", "An instant frost-infused strike that causes 3 Froststrike damage in addition to 65% of your normal weapon damage (85% of that amount if a Two-Handed weapon is equipped). Awards 1 combo point.    This uses Sinister Strike modifiers.", "Normal", 45, nil, 3, false, 1, true },
  { "Spell", "Volt Strike", 903048, 43004, "Classless", "Rank 1", "An instant storm-infused strike that causes 3 Stormstrike damage in addition to 65% of your normal weapon damage (85% of that amount if a Two-Handed weapon is equipped). Awards 1 combo point.    This uses Sinister Strike modifiers.", "Normal", 45, nil, 3, false, 1, true },
  { "Spell", "Frost Shot", 903060, 43005, "Classless", "Rank 1", "A steady shot laced with frost that causes 80% weapon damage as Froststrike damage and deals 6 additional Froststrike damage. Causes an additional 5 Froststrike damage to slowed targets.    This uses Steady Shot modifiers.", "Normal", 78, nil, 0, false, 1, true },
  { "Spell", "Holy Shot", 903068, 43006, "Classless", "Rank 1", "A steady shot blessed with light that causes 80% weapon damage as Holystrike damage and deals 6 additional Holystrike damage. Causes an additional 5 Holystrike damage to slowed targets.    This uses Steady Shot modifiers.", "Normal", 78, nil, 0, false, 1, true },
  { "Spell", "Flare Shot", 903076, 43007, "Classless", "Rank 1", "A steady shot wreathed in cinders that causes 80% weapon damage as Firestrike damage and deals 6 additional Firestrike damage. Causes an additional 5 Firestrike damage to slowed targets.    This uses Steady Shot modifiers.", "Normal", 78, nil, 0, false, 1, true },
  { "Spell", "Locust Shot", 903092, 43009, "Classless", "Rank 1", "A steady shot charged with storm energy that causes 80% weapon damage as Stormstrike damage and deals 6 additional Stormstrike damage. Causes an additional 5 Stormstrike damage to slowed targets.    This uses Steady Shot modifiers.", "Normal", 78, nil, 0, false, 1, true },
  { "Spell", "Arcane Slam", 903100, 43010, "Classless", "Rank 1", "Slams the opponent with arcane force, causing 65% weapon damage plus 11 Spellstrike damage.    This uses Slam modifiers.", "Normal", 15, nil, 1, false, 1, true },
  { "Spell", "Shadow Slam", 903110, 43011, "Classless", "Rank 1", "Slams the opponent with shadow force, causing 65% weapon damage plus 11 Shadowstrike damage.    This uses Slam modifiers.", "Normal", 15, nil, 1, false, 1, true },
  { "Spell", "Burning Slam", 903120, 43012, "Classless", "Rank 1", "Slams the opponent with fire force, causing 65% weapon damage plus 11 Firestrike damage.    This uses Slam modifiers.", "Normal", 15, nil, 1, false, 1, true },
  { "Spell", "Frozen Slam", 903130, 43013, "Classless", "Rank 1", "Slams the opponent, causing 65% weapon damage plus 11 Froststrike damage.    This uses Slam modifiers.", "Normal", 15, nil, 1, false, 1, true },
  { "Spell", "Storm Slam", 903140, 43014, "Classless", "Rank 1", "Slams the opponent, causing 65% weapon damage plus 11 Stormstrike damage.    This uses Slam modifiers.", "Normal", 15, nil, 1, false, 1, true },
  { "Spell", "Manareaver", 903150, 43015, "Classless", "", "An instant arcane strike that causes 50% weapon damage as Spellstrike damage.    This uses Crusader Strike modifiers.", "Normal", 78, nil, 0, false, 1, true },
  { "Spell", "Dawnreaver", 903158, 43016, "Classless", "", "An instant holy strike that causes 50% weapon damage as Holystrike damage.    This uses Crusader Strike modifiers.", "Normal", 78, nil, 0, false, 1, true },
