  { "Spell", "Gaze of C'Thun", 280970, 138266, "Classless", "Rank 1", "This spell belongs to  Cultist     Set C'Thun's Gaze upon an enemy or ally, jumping to 1 additional nearby target. Deals 231 Shadow damage to enemies or heals allies for 48.", "Epic", 234, nil, 0, false, 10, true },
  { "Spell", "Reave", 280990, 138267, "Classless", "Rank 1", "This spell belongs to  Bloodmage     Lacerate an enemy, dealing 65% Weapon Damage plus 26.    If you are behind the enemy or the enemy is bleeding, deal 100% additional Shadow damage for each matching condition. If the enemy is below 35% health, deal 125% additional Shadow damage.", "Epic", 35, nil, 1, false, 10, true },
  { "Spell", "Bushcraft", 280984, 138268, "Classless", "", "This spell belongs to  Ranger     Gain the ability to craft Crude Leather  from the Leather obtained from Skinning, gives you a chance to find it when Skinning beasts, and increases your Skinning speed.    Allows you to craft items that require Crude Leather .", "Epic", 0, nil, 0, false, 8, true },
  { "Spell", "Infused Aegis", 281050, 138269, "Classless", "", "This spell belongs to  Starcaller     Instantly counterattack any enemy that strikes you from the front in melee for Arcane damage, lasting 10 sec. Can only occur once per sec per enemy.", "Epic", 0, nil, 0, false, 10, true },
  { "Spell", "Volcanic Shell", 281060, 138270, "Classless", "Rank 1", "This spell belongs to  Pyromancer     Conjure a shield of magma and fire around you, absorbing 520 damage. Lasts 10 sec.", "Epic", 234, nil, 0, false, 29, true },
  { "Spell", "Pillar of Flame", 281070, 138271, "Classless", "Rank 1", "This spell belongs to  Pyromancer     Create a pillar of lava beneath an enemy, dealing 39 Fire damage.    Deals an additional 95 Fire damage to enemies near the primary target.", "Epic", 296, nil, 0, false, 25, true },
  { "Spell", "Spore", 281090, 138273, "Classless", "Rank 1", "This spell belongs to  Venomancer     Inject an enemy with parasitic spores, dealing 97 Shadow damage, plus an additional 84 to 98 over 21 sec.    After 10 sec, drop a Mushroom  below the target that explodes after 2 sec, dealing 65 Nature damage to nearby enemies.", "Epic", 234, nil, 0, false, 10, true },
  { "Spell", "Mycelial Ring", 281100, 138274, "Classless", "Rank 1", "This spell belongs to  Venomancer     Create an 8 yd ring beneath you for 10 sec that deals 25 Nature damage every 1 sec to enemies inside and immediately grows 12 Mushrooms  in a circle around you.    At the end of the duration, up to 15 allies inside are healed for 307.    Can be used in any form.      Mycelial Ring Mushroom Explosion  Drop a Mushroom  near the target that explodes after 2 sec, dealing 303 Plague Damage to all nearby enemies.", "Epic", 281, nil, 0, false, 25, true },
  { "Spell", "Destabilize Time", 281110, 138275, "Classless", "", "This spell belongs to  Chronomancer     Reduces enemy casting speed by 10% for 20 sec, increasing by 10% every time they cast.    Gaining stacks does not extend the duration of the spell.", "Epic", 343, nil, 0, false, 25, true },
  { "Spell", "Dimensional Divergence", 281120, 138276, "Classless", "", "This spell belongs to  Chronomancer     Swap places with a target.    If they're an enemy, you steal 80% of their movement speed for 3 sec.", "Epic", 493, nil, 0, false, 20, true },
  { "Spell", "Mountain Fury", 281140, 138278, "Classless", "Rank 1", "This spell belongs to  Primalist     Move the earth, dealing 245 Physical damage to up to 12 enemies in a 10 yd frontal cone, pulling them toward you, repeating every 2 sec for 4 sec.  Each time an enemy is pulled toward you, you gain 2% reduced damage taken for 3 sec, stacking 5 times.", "Epic", 30, nil, 1, false, 25, true },
  { "Spell", "Earth's Embrace", 281150, 138279, "Classless", "", "This spell belongs to  Primalist     Encapsulate your body in amber, becoming immune to all Physical attacks and spells for 8 sec, and healing you for 305 every 2 sec, but making you unable to move or act.  Usable while stunned, feared, or polymorphed.", "Epic", 515, nil, 0, false, 25, true },
  { "Spell", "Boulder Dash", 281160, 138280, "Classless", "", "This spell belongs to  Primalist     Raise a boulder out of the ground and encase yourself within it, preventing you from attacking or casting spells.  For 10 sec, you roll forward at 70% increased movement speed, dealing 259 Physical damage to enemies you roll over, and you are immune to crowd control effects.", "Epic", 546, nil, 0, false, 10, true },
  { "Spell", "Speed Rune", 281170, 138281, "Classless", "", "This spell belongs to  Runemaster     Conjure a path of runes in the direction you are facing for 10 sec, increasing the movement speed of allies by 70%.    This effect can persist for a short duration after leaving the runic path.", "Epic", 273, nil, 0, false, 10, true },
  { "Spell", "Hemostasis", 281190, 138283, "Classless", "", "This spell belongs to  Bloodmage     Trap an enemy in a blood orb, horrifying them in place for 4 sec.    Reactivating this ability within 4 sec, instantly pops the Hemostasis , dealing 653 Shadow damage and reducing their healing received by 60% for 10 sec.", "Epic", 846, nil, -2, false, 29, true },
  { "Spell", "Hemal Excision", 281200, 138284, "Classless", "", "This spell belongs to  Bloodmage     Cut into an ally's vital essence, siphoning all curse effects from them. You may reactivate this ability again within 10 sec to place these curse effects on an enemy.", "Epic", 846, nil, -2, false, 25, true },
  { "Spell", "Grove Guardian", 281210, 138285, "Classless", "", "This spell belongs to  Primalist     Mark a location as your Grove  for 20 sec.   Allies within gain 30% movement speed and are healed for 412 every 5 sec, removing 1 poison and disease effect.   Enemies within are slowed by 30% and take 973 Nature damage every 5 sec and are rooted for 2 sec.", "Epic", 437, nil, 0, false, 30, true },
  { "Spell", "Spirit Charge", 281220, 138286, "Classless", "Rank 1", "This spell belongs to  Primalist     Charge to an ally's aid, healing them for 55 and dealing 69 Nature damage to enemies within 5 yds of them.", "Epic", 249, nil, 0, false, 10, true },
  { "Spell", "Seismic Tremor", 281240, 138288, "Classless", "Rank 1", "This spell belongs to  Primalist     Send a tremor through the earth at an enemy, dealing 195 Physical damage, plus an additional 200 over 24 sec. Damage is dealt slowly at first, and builds up over time.     Shares a cooldown with other |CffffffffSeismic  spells.", "Epic", 187, nil, 0, false, 10, true },
  { "Spell", "Spite", 281250, 138289, "Classless", "", "This spell belongs to  Barbarian     Quickly unleash 3 ranged attacks at your target and then fling yourself back a great distance, dealing 125% Ranged Weapon Damage.", "Epic", 30, nil, 3, false, 20, true },
  { "Spell", "Ancient of Lore", 281260, 138290, "Classless", "", "This spell belongs to  Primalist     Funnel nature's energies into yourself, transforming into an Ancient of Lore  for 20 sec.    While active, your stats are increased by 10% and nearby party members have their costs reduced by 30%.    While transformed, your movement speed is reduced by 50%.    Applies |CffffffffAncient Weariness  to nearby party members, preventing them from benefiting from another Ancient form for 10 min.", "Epic", 0, nil, 1, false, 40, true },
  { "Spell", "Ancient of War", 281261, 138291, "Classless", "", "This spell belongs to  Primalist     Funnel nature's fury into yourself, transforming into an Ancient of War  for 20 sec.    While active, nearby party members have their critical strike chance increased by 20%.    While transformed, your movement speed is reduced by 50%.    Applies |CffffffffAncient Weariness  to nearby party members, preventing them from benefiting from another Ancient form for 10 min.", "Epic", 0, nil, 0, false, 40, true },
  { "Spell", "Bomb Toss", 281270, 138292, "Classless", "Rank 1", "This spell belongs to  Tinker     Lob a bomb at an enemy, dealing 217 Fire damage and reducing their armor by 5% for 15 sec, stacking 4 times.", "Epic", 93, nil, 0, false, 10, true },
  { "Spell", "Radiance", 281280, 138293, "Classless", "", "This spell belongs to  Sun Cleric     Every 2 sec you burst with light, healing nearby allies for 140 and damaging nearby enemies for 194. Lasts 10 sec.", "Epic", 468, nil, 0, false, 29, true },
  { "Spell", "My Greatest Invention!", 281290, 138294, "Classless", "", "Requires   Path of Healing   This spell belongs to  Tinker     Show off your Greatest Invention , healing party and raid members in a 30 yd radius for 634 every 1.50 sec for 9 sec.", "Epic", 418, nil, 0, false, 30, true },
  { "Spell", "Build: Oil-Spill Pylon", 289010, 138298, "Classless", "", "This spell belongs to  Tinker     Build an Oil-Spill Pylon  at target location for 10 sec, spilling oil in an 8 yd radius that reduces enemies movement speed by 60% and increases their Fire damage taken by you by 5%.", "Epic", 187, nil, 0, false, 25, true },
  { "Spell", "Malediction", 289020, 138299, "Classless", "", "This spell belongs to  Bloodmage     Condemn an enemy, dealing 318 Shadow damage over 12 sec and increasing the damage they take from your next 5 direct damage spells by 20%.", "Epic", 25, nil, 1, false, 25, true },
  { "Spell", "Netherstrike", 289030, 138300, "Classless", "Rank 1", "This spell belongs to  Cultist     Strike an enemy quickly for 100% Shadow Weapon Damage, purging 1 beneficial magic effect from them.    Only usable on enemies below 35% health.", "Epic", 191, nil, 0, false, 10, true },
  { "Spell", "Voidborne", 289040, 138301, "Classless", "", "This spell belongs to  Cultist     Tap into your inner voidborne rage, increasing your damage dealt and critical strike chance by 25%, and granting you immunity to stun effects for 10 sec.", "Epic", 80, nil, -2, false, 25, true },
  { "Spell", "Hoarfrost", 289080, 138304, "Classless", "Rank 1", "This spell belongs to  Runemaster     Slash in a frozen fury in front of you, dealing 110 Frost Damage to up to 3 nearby enemies, plus an additional 110 every 3 sec for 21 sec.     Enemies hit by the initial strike are frozen in place for 3 sec.", "Epic", 156, nil, 0, false, 10, true },
  { "Spell", "Fracture", 289090, 138305, "Classless", "Rank 1", "This spell belongs to  Runemaster     Strike an enemy with frozen fury, dealing 691 Frost damage.    Damage dealt is guaranteed to critically strike against frozen targets.", "Epic", 468, nil, 0, false, 20, true },
  { "Spell", "Sun Down", 289100, 138306, "Classless", "Rank 1", "This spell belongs to  Sun Cleric     Bring the wrath of the sun down upon an enemy after 2 sec, dealing 363 Holyflame Damage and scorching the earth beneath them for 9 sec.    While inside, enemies are struck by a Solar Flare  every 3 sec.    Solar Flare  Deals 43 Holyflame Damage and reduces the target's chance to hit by 3% for 10 sec.", "Epic", 390, nil, 0, false, 25, true },
  { "Spell", "Ancient Curse", 289120, 138308, "Classless", "Rank 1", "This spell belongs to  Cultist     Curse an enemy, dealing 145 Shadow damage and increasing all Shadow damage they take from you by 10% for 10 sec.", "Epic", 296, nil, 0, false, 25, true },
  { "Spell", "Twilight Shieldtoss", 289130, 138309, "Classless", "Rank 1", "This spell belongs to  Cultist     Hurl a cursed shield, dealing 40 Shadow damage to up to 3 enemies, reduced by 20% with each jump.", "Epic", 234, nil, 0, false, 10, true },
  { "Spell", "Rocket Launcher", 289140, 138310, "Classless", "Rank 1", "This spell belongs to  Tinker     Fire a powerful rocket at an enemy that deals 303 Fire damage.", "Epic", 124, nil, 0, false, 10, true },
  { "Spell", "Deathball", 289170, 138313, "Classless", "", "This spell belongs to  Tinker     Launch 3 Deathballs  in a line, increasing in speed the further they travel.    They explode when they come into contact with an enemy, dealing 917 Fire damage to nearby enemies, increased based on distance traveled.", "Epic", 412, nil, 0, false, 40, true },
  { "Spell", "Build: Spider Bomb", 289180, 138314, "Classless", "Rank 1", "This spell belongs to  Tinker     Build a Spider Bomb  that will immediately run towards your target and detonate, dealing 357 Fire damage in an 8 yd radius.", "Epic", 124, nil, 0, false, 10, true },
  { "Spell", "Build: Firepot Drone", 289190, 138315, "Classless", "", "This spell belongs to  Tinker     3 Charges, 10 sec recharge   Build a Firepot Drone  that flies towards your target, dropping a bomb along its path and exploding upon landing, dealing 288 Fire damage in a 5 yd radius, leaving oil on the ground for 6 sec that slows enemies within by 30%.", "Epic", 93, nil, 0, false, 10, true },
  { "Spell", "Build: Spider Bomb Factory", 289200, 138316, "Classless", "", "This spell belongs to  Tinker     Build a Spider Bomb Factory  in front of you for 20 sec.    For the duration, using damaging spells and abilities will summon 2 Spider Bombs  that immediately run towards your target and detonate, dealing Fire damage.    This can not occur more than once every 4 seconds.", "Epic", 546, nil, 0, false, 40, true },
  { "Spell", "Primordial Pulse", 289230, 138318, "Classless", "Rank 1", "This spell belongs to  Runemaster     Inscribe an area with runes for 2 sec, dealing 25 Elemental Damage every 0.50 sec to up to 5 enemies inside.", "Epic", 312, nil, 0, false, 25, true },
  { "Spell", "Starcall", 289250, 138320, "Classless", "", "This spell belongs to  Starcaller     Smash up to 8 enemies, dealing 158 Arcane damage, scaling with block value, and reducing their attack speed by 20% for 10 sec.", "Epic", 156, nil, 0, false, 10, true },
  { "Spell", "Reign of Dread", 288912, 138321, "Warlock", "Rank 1", "Surge into the air and scorch all enemies below with 95 to 115 Shadowflame damage over 2 sec.    Can be channeled while moving. While airborne, your movement speed is reduced by 25% and melee attacks against you have 60% increased chance to miss.", "Epic", 234, nil, 0, false, 20, true },
  { "Spell", "Witchblood Tonic", 289260, 138322, "Classless", "", "This spell belongs to  Witch Hunter     Drink a shadowy tonic, removing all curse effects from you and reducing all Magic damage taken by 40% for 10 sec.    Shares a cooldown with other Tonics .", "Epic", 50, nil, 1, false, 20, true },
  { "Spell", "Vampiric Tonic", 289261, 138323, "Classless", "", "This spell belongs to  Witch Hunter     Drink a vampiric tonic, causing Physical damage dealt to heal you for 10% of the damage dealt for 15 sec. This healing cannot exceed 10% of your maximum health per heal.    Shares a cooldown with other Tonics .", "Epic", 50, nil, 1, false, 20, true },
  { "Spell", "Daring Escape", 289263, 138324, "Classless", "", "This spell belongs to  Witch Hunter     Jump backwards, causing all ranged attacks to miss you for 2 sec.", "Epic", 328, nil, 0, false, 25, true },
  { "Spell", "Pyro Tonic", 289265, 138325, "Classless", "", "This spell belongs to  Witch Hunter     Drink a fiery tonic, increasing damage done by 5% and your critical strike chance by 5% for 15 sec.    Shares a cooldown with other Tonics .", "Epic", 50, nil, 1, false, 25, true },
  { "Spell", "Holy Water Tonic", 289266, 138326, "Classless", "", "This spell belongs to  Witch Hunter     Smash a holy water tonic beneath you, stunning all Undead and Demon enemies within 8 yds for 6 sec and increasing your damage dealt against Undead and Demons by 15% for 20 sec.    Shares a cooldown with other Tonics .", "Epic", 50, nil, 1, false, 20, true },
  { "Spell", "Surging Tonic", 289268, 138327, "Classless", "", "This spell belongs to  Witch Hunter     Drink a bitter tonic, increasing your haste by 15% and reducing the cost of all abilities by 20% for 15 sec.    Shares a cooldown with other Tonics .", "Epic", 50, nil, 1, false, 20, true },
  { "Spell", "Dark Tonic", 289270, 138328, "Classless", "Rank 1", "This spell belongs to  Witch Hunter     Drink a dark tonic, healing you for 1144, scaling with your Stamina, and increasing your maximum health by 15% for 15 sec.    Shares a cooldown with other Tonics .", "Epic", 50, nil, 1, false, 20, true },
  { "Spell", "Pyroblast", 11366, 40316, "Mage", "Rank 1", "Hurls an immense fiery boulder that causes 148 to 192 Fire damage and an additional 52 Fire damage over 12 sec.", "Normal", 343, nil, 0, false, 16, true },
  { "Spell", "Blast Wave", 11113, 40319, "Mage", "Rank 1", "A wave of flame radiates outward from the caster, damaging all enemies caught within the blast for 82 to 94 Fire damage, knocking them back and dazing them for 6 sec.", "Epic", 109, nil, 0, false, 22, true },
  { "Spell", "Combustion", 11129, 40323, "Mage", "", "When activated, this spell increases your critical strike damage bonus with Fire damage spells by 50%, and causes each of your Fire damage spell hits to increase your critical strike chance with Fire damage spells by 10%.  This effect lasts until you have caused 3 non-periodic critical strikes with Fire spells.", "Epic", 0, nil, 0, false, 30, true },
  { "Spell", "Icy Veins", 12472, 40334, "Mage", "", "Hastens your spellcasting, increasing spell casting speed by 20% and reducing the pushback suffered from damaging attacks while casting by 100%. Lasts 20 sec.    Does not stack with other similar cast speed increasing effects.", "Epic", 46, nil, 0, false, 16, true },
  { "Spell", "Ice Barrier", 11426, 40336, "Mage", "Rank 1", "Instantly shields you, absorbing 460 damage.  Lasts 1 min.  While the shield holds, spellcasting will not be delayed by damage.", "Epic", 328, nil, 0, false, 30, true },
  { "Spell", "Cold Snap", 11958, 40337, "Mage", "", "When activated, this spell resets the cooldown on all Frost spells you recently cast.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Presence of Mind", 12043, 40346, "Mage", "", "When activated, your next spell within 10 sec with a casting time less than 10 sec becomes instant.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Arcane Power", 12042, 40347, "Mage", "", "When activated, your spells and abilities deal 20% more magic damage while costing 20% more mana to cast.  This effect lasts 15 sec.   Does not stack with other similar effects.  This ability can be used while in Cat, Bear, Moonkin or Tree of Life Shapeshifts.", "Epic", 0, nil, 0, false, 30, false },
  { "Spell", "Sweeping Strikes", 12328, 40360, "Warrior", "", "While active, casting a melee ability that deals damage will cause a Sweeping Strike, dealing 40% weapon damage to 5 nearby enemies, further increased by attack power. Lasts 10 sec.    Can't be active at the same time as Blade Flurry.    This ability is usable while shapeshifted.", "Epic", 30, nil, 1, false, 22, true },
  { "Spell", "Mortal Strike", 12294, 40362, "Warrior", "Rank 1", "A vicious strike that deals 100% weapon damage plus 55 and wounds the target, reducing the effectiveness of any healing by 50% for 10 sec.   Does not stack with other similar effects.", "Normal", 30, nil, 1, false, 30, true },
  { "Spell", "Vigilance", 50720, 40372, "Warrior", "", "Focus your protective gaze on a group or raid target to reduce their damage taken by 3% and transfer 10% of the threat they cause to you.    Each time they are hit by an attack your Taunt and Growl cooldown is refreshed. Lasts 30 min. This effect can only be on one target at a time.", "Rare", 0, nil, 0, false, 30, true },
  { "Spell", "Concussion Blow", 12809, 40376, "Warrior", "", "Stuns the opponent for 5 sec and deals 389 damage. (based on attack power).     Causes a High amount of threat.", "Epic", 15, nil, 1, false, 22, true },
  { "Spell", "Last Stand", 12975, 40377, "Warrior", "", "When activated, this ability temporarily grants you 30% of your maximum health for 20 sec.  After the effect expires, the health is lost.    This ability is usable while shapeshifted.", "Epic", 0, nil, 0, false, 16, true },
  { "Spell", "Piercing Howl", 12323, 40384, "Warrior", "", "Causes all enemies within 10 yards to be Dazed, reducing movement speed by 50% for 6 sec.  This ability is usable while shapeshifted.", "Rare", 10, nil, 1, false, 16, true },
  { "Spell", "Bloodthirst", 23881, 40387, "Warrior", "", "Instantly attack the target causing 562 damage. Each bleed applied by you increases the damage of Bloodthirst by 8%, up to a maximum of 40%. In addition, the next 3 successful melee attacks will restore 1% of max health. This effect lasts 8 sec. Damage is based on your attack power.  This ability is usable while shapeshifted.", "Normal", 20, nil, 1, false, 30, true },
  { "Spell", "Adrenaline Rush", 13750, 40396, "Rogue", "", "Increases your Energy regeneration rate by 100% for 15 sec.  This ability is usable while shapeshifted.", "Epic", 0, nil, 3, false, 30, true },
  { "Spell", "Blade Flurry", 13877, 40400, "Rogue", "", "Increases your melee attack speed by 20%. In addition, attacks strike an additional nearby opponent. Lasts 20 sec.    Can't be active at the same time as Sweeping Strikes.     This ability is usable while shapeshifted.", "Epic", 25, nil, 3, false, 22, true },
  { "Spell", "Cold Blood", 14177, 40421, "Rogue", "", "When activated, your next direct damage Rogue ability has 100% increased critical strike chance, 20% increased damage (10% versus players) and is usable from 10 yards.     When consumed you will gain 4% melee and ranged critical strike chance for 15 sec.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Preparation", 14185, 40424, "Rogue", "", "When activated, this ability immediately resets the cooldown on your Evasion, Sprint, Vanish, Cold Blood and Shadowstep abilities.  This ability is usable while shapeshifted.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Riposte", 14251, 40425, "Rogue", "", "A strike that becomes active after parrying an opponent's attack.  This attack deals 150% weapon damage and slows their melee attack speed by 20% for 30 sec. Awards 1 combo point. Does not stack with other similar effects.", "Normal", 10, nil, 3, false, 16, true },
  { "Spell", "Ghostly Strike", 14278, 40426, "Rogue", "", "A strike that deals 125% weapon damage (180% if a dagger is equipped, 100% if a Two-Handed weapon is equipped).     Increases your chance to dodge (or parry if a single Two-Handed weapon is equipped) by 10% for 8 sec. Awards 1 combo point.", "Rare", 40, nil, 3, false, 16, true },
  { "Spell", "Power Infusion", 10060, 40428, "Priest", "", "Infuses the target with power, increasing spell casting speed by 20% and reducing the cost of all magic spells and abilities by 20%. Lasts 15 sec.", "Epic", 249, nil, 0, false, 30, true },
  { "Spell", "Inner Focus", 14751, 40435, "Priest", "", "When activated, reduces the mana cost of your next spell or magic ability by 100% and increases its critical effect chance by 25% if it is capable of a critical effect.", "Epic", 0, nil, 0, false, 16, true },
  { "Spell", "Premeditation", 14183, 40440, "Rogue", "", "When used, adds 2 combo points to your target. Must be stealthed. You must add to or use those combo points within 20 sec or the combo points are lost.  This ability is usable while shapeshifted.", "Rare", 0, nil, 3, false, 30, true },
  { "Spell", "Desperate Prayer", 19236, 40452, "Priest", "Rank 1", "Heals you for 110 to 150. If used while below 50% health, it guarantees a critical heal.", "Epic", 374, nil, 0, false, 16, true },
  { "Spell", "Vampiric Embrace", 15286, 40461, "Priest", "", "Fills you with the embrace of Shadow energy, causing you to be healed for 15% and other party members to be healed for 3% of any single-target Priest Shadow spell damage you deal.     Either heal cannot exceed 5% of the maximum health of the caster.   This ability is usable while shapeshifted.", "Rare", 0, nil, 0, false, 30, true },
  { "Spell", "Mind Flay", 15407, 40462, "Priest", "Rank 1", "Assault the target's mind with Shadow energy, causing 45 Shadow damage over 2.93 sec and slowing their movement speed by 50%.", "Normal", 140, nil, 0, false, 16, true },
  { "Spell", "Shadowform", 15473, 40463, "Priest", "", "Assume a Shadowform, increasing your Shadow damage by 15%.    You may not cast Healing or Priest Holy spells while in this form except for Cure Disease and Abolish Disease.    Grants the periodic damage from your Shadow Word: Pain, Devouring Plague, and Vampiric Touch spells the ability to critically hit and benefit from haste.", "Legendary", 203, nil, 0, false, 22, true },
  { "Spell", "Silence", 15487, 40464, "Priest", "", "Silences the target, preventing them from casting spells for 5 sec. Non-player victim spellcasting is also interrupted for 3 sec.", "Epic", 225, nil, 0, false, 22, true },
  { "Spell", "Elemental Mastery", 16166, 40472, "Shaman", "", "When activated, your next Lightning Bolt, Chain Lightning or Lava Burst becomes instant and costs no mana. In addition, you gain 10% spell haste for 15 sec.   Does not stack with other similar cast speed increasing effects.", "Epic", 0, nil, 0, false, 30, false },
  { "Spell", "Tidal Force", 55198, 40476, "Shaman", "", "Call upon the power of the Tides to empower your heals for 10 sec.  Healing Wave: Heals the target again for 30% of the original amount healed after 1 second.  Lesser Healing Wave: Increases your healing on the target by 5% for 8 seconds, stacks up to 3 times.  Chain Heal: No longer diminishes in healing with each jump.  Healing Rain: Duration is increased by 50%.", "Epic", 0, nil, 0, false, 16, true },
  { "Spell", "Mana Tide Totem", 16190, 40482, "Shaman", "", "Summons a Mana Tide Totem with 10% of the caster's health at the feet of the caster for 12 sec that restores 5% of total mana every 3 seconds to group members within 30 yards.  This ability is usable while shapeshifted.", "Rare", 0, nil, 0, false, 30, true },
  { "Spell", "Nature's Swiftness", 16188, 40483, "Shaman", "", "When activated, your next Shaman Nature spell with a base casting time less than 10 sec. becomes instant and increases your cast speed by 10% for 20 sec. Does not stack with other similar cast speed increasing effects.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Hemorrhage", 16511, 40503, "Rogue", "Rank 1", "An instant strike that deals 100% weapon damage and applies Hemorrhage, increasing Physical damage taken by up to 9. Lasts 10 charges or 15 sec. Awards 1 combo point.    Deals 175% weapon damage if a dagger is equipped and 85% if a two-hander is equipped.", "Normal", 35, nil, 3, false, 22, true },
  { "Spell", "Insect Swarm", 5570, 40514, "Druid", "Rank 1", "The enemy target is swarmed by insects, decreasing their chance to hit by 3% and causing 156 Nature damage over 12 sec.", "Normal", 124, nil, 0, false, 22, true },
  { "Spell", "Moonkin Form", 24858, 40518, "Druid", "Shapeshift", "Increases armor from cloth and leather by 150%, damage taken while stunned is reduced by 15%. Your direct damaging spells have a 33% chance to regenerate 2% of your total mana.   All party and raid members gain 5% increased spell critical effect chance. Does not stack with similar effects.  Casting any healing spell will take you out of Moonkin Form.", "Legendary", 203, nil, 0, false, 30, true },
  { "Spell", "Feral Charge", 49377, 40528, "Druid", "", "Teaches Feral Charge (Bear) and Feral Charge (Cat).         Feral Charge - Bear  Causes you to charge an enemy gaining 15 rage, immobilizing them for 3 sec and interrupting any spell being cast for 4 sec.    This shares a cooldown with other Feral Charges.      Feral Charge - Cat  Causes you to leap behind an enemy, dazing them for 3 sec.  This shares a cooldown with other Feral Charges.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Leader of the Pack", 17007, 40532, "Druid", "", "While in Cat, Bear or Dire Bear Form, the Leader of the Pack increases ranged and melee critical strike chance of all party and raid members by 5%.    Does not stack with other similar effects.", "Rare", 0, nil, 0, false, 30, true },
  { "Spell", "Natural Alacrity", 17116, 40543, "Druid", "", "When activated, your next Druid Nature spell with a base casting time less than 10 sec. becomes instant. In addition, the effectiveness of your Nature healing spells are increased by 10% for 20 sec.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Swiftmend", 18562, 40547, "Druid", "", "Consumes a Rejuvenation or Regrowth effect on a friendly target to instantly heal them an amount equal to 12 sec. of Rejuvenation or 18 sec. of Regrowth.", "Normal", 249, nil, 0, false, 30, true },
  { "Spell", "Stormstrike", 17364, 40549, "Shaman", "Rank 1", "Instantly attack with both weapons for 100% weapon damage.  In addition, the next 4 sources of Nature damage dealt to the target from the Shaman are increased by 20%. Lasts 12 sec.", "Normal", 124, nil, 0, false, 30, true },
  { "Spell", "Shadowburn", 17877, 40554, "Warlock", "Rank 1", "Instantly blasts the target for 171 Shadowflame damage.     If the target dies within 5 sec of Shadowburn, and yields experience or honor, the caster gains a Soul Shard.", "Normal", 312, nil, 0, false, 22, true },
  { "Spell", "Conflagrate", 17962, 40559, "Warlock", "", "Consumes an Immolate or Shadowflame effect on the enemy target to instantly deal damage equal to 60% of your Immolate or Shadowflame, and causes an additional 40% damage over 6 sec. This periodic damage may critically strike.", "Normal", 249, nil, 0, false, 30, true },
  { "Spell", "Dark Pact", 18220, 40573, "Warlock", "Rank 1", "Drains 282 of your summoned demon's mana, returning 100% to you.", "Rare", 0, nil, 0, false, 30, true },
  { "Spell", "Curse of Exhaustion", 18223, 40577, "Warlock", "", "Reduces the target's movement speed by 30% for 12 sec.", "Epic", 93, nil, 0, false, 22, true },
  { "Spell", "Survival Instincts", 61336, 40583, "Druid", "", "Increases your maximum health by 20% and triples effectiveness of Nurturing Instinct's increased healing received effect for 20 sec. Only usable while in Cat, Bear or Dire Bear Form. After the effect expires, the health is lost.", "Epic", 0, nil, 3, false, 16, true },
  { "Spell", "Fel Domination", 18708, 40592, "Warlock", "", "Your next Imp, Voidwalker, Succubus, Felhunter or Felguard Summon spell has its casting time reduced by 5.5 sec and its Mana cost reduced by 50%.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Soul Link", 19028, 40601, "Warlock", "", "When active, 20% of all damage taken by the caster is taken by your Summoned or Enslaved Demon. That damage cannot be prevented. Lasts as long as the demon is active, controlled and you are within 30 yards of it.  Cannot Soul Link a Summoned Imp.", "Rare", 249, nil, 0, false, 16, true },
  { "Spell", "Counterattack", 19306, 40611, "Hunter", "Rank 1", "A strike that becomes active after parrying an opponent's attack. This attack deals 1012 damage and immobilizes the target for 5 sec.     Counterattack cannot be blocked, dodged, or parried.", "Normal", 46, nil, 0, false, 22, true },
  { "Spell", "Black Arrow", 3674, 40613, "Hunter", "Rank 1", "Fires a Black Arrow at the target, increasing all damage done by you to the target by 6% and dealing 136 Shadow damage every 3 over 15 sec.", "Normal", 93, nil, 0, false, 36, true },
  { "Spell", "Wyvern Sting", 19386, 40614, "Hunter", "Rank 1", "A stinging shot that puts the target to sleep for 30 sec. (6 seconds against players) Any damage will cancel the effect.  When the target wakes up, the Sting causes 300 Nature damage over 6 sec. Only one Sting per Hunter can be active on the target at a time.", "Epic", 124, nil, 0, false, 30, true },
  { "Spell", "Aimed Shot", 19434, 40619, "Hunter", "Rank 1", "An aimed shot that deals 100% weapon damage plus 5 and reduces healing done to that target by 50%. Lasts 10 sec.   Does not stack with other similar effects.", "Rare", 124, nil, 0, false, 16, true },
  { "Spell", "Readiness", 23989, 40625, "Hunter", "", "When activated, this ability immediately resets the cooldown on your other Hunter abilities except Bestial Wrath.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Bestial Wrath", 19574, 40632, "Hunter", "", "Send your tamed beast or tamed dragonkin into a rage causing 50% additional damage for 10 sec.  While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed.  Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Legendary", 156, nil, 0, false, 30, true },
  { "Spell", "Intimidation", 19577, 40633, "Hunter", "", "Command your tamed beast to intimidate the target, causing a high amount of threat and stunning the target for 3 sec. Lasts 15 sec.", "Epic", 124, nil, 0, false, 22, true },
  { "Spell", "Holy Shield", 20925, 40653, "Paladin", "Rank 1", "Increases chance to block by 30% for 10 sec. Each block expends a charge and deals 50 holy damage to the attacker. 8 charges.", "Rare", 156, nil, 0, false, 30, true },
  { "Spell", "Divine Favor", 20216, 40655, "Paladin", "", "When activated, gives your next Holy spell a 100% critical effect chance and 50% increased healing.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Aura Mastery", 31821, 40656, "Paladin", "", "Causes your Concentration Aura to make all affected targets immune to Silence and Interrupt effects and improve the effect of all other auras by 100%.  Lasts 6 sec.", "Epic", 0, nil, 0, false, 16, true },
  { "Spell", "Repentance", 20066, 40657, "Paladin", "", "Puts the enemy target in a state of meditation, incapacitating them for up to 1 min (6 seconds on players), and removing the effect of Righteous Vengeance.  Any damage caused will awaken the target. Usable against Demons, Dragonkin, Giants, Humanoids and Undead.", "Epic", 140, nil, 0, false, 30, true },
  { "Spell", "Holy Shock", 20473, 40669, "Paladin", "Rank 1", "Blasts the target with Holy energy, causing 191 to 216 Holy damage to an enemy, or 301 to 327 healing to an ally.", "Normal", 281, nil, 0, false, 30, true },
  { "Spell", "Lightwell", 724, 40690, "Priest", "Rank 1", "Creates a Holy Lightwell.    Lightwell will attempt to heal a nearby party or raid member within 20 yards every second if they have less than 50% health for 877.    Lightwell lasts for 30 seconds or until it heals 10 times.", "Epic", 265, nil, 0, false, 30, true },
  { "Spell", "Rampage", 29801, 40709, "Warrior", "Passive", "Increases ranged and melee critical strike chance of all party and raid members within 100 yds by 5%.    Does not stack with other similar effects.", "Rare", 0, nil, 0, false, 36, true },
  { "Spell", "Unstable Affliction", 30108, 40719, "Warlock", "Rank 1", "Shadow energy slowly destroys the target, causing 550 damage over 14.65 sec.  In addition, if the Unstable Affliction is dispelled it will cause 990 damage to the dispeller and silence them for 5 sec. This spell benefits from haste.", "Normal", 234, nil, 0, false, 36, true },
  { "Spell", "Shadowfury", 30283, 40722, "Warlock", "Rank 1", "Shadowfury is unleashed, causing 225 to 263 Shadow damage and stunning all enemies within 8 yds for 3 sec.", "Epic", 421, nil, 0, false, 36, true },
  { "Spell", "Shamanistic Rage", 30823, 40734, "Shaman", "", "Reduces all damage taken by 30% and gives your successful melee attacks a chance to regenerate mana equal to 15% of your attack power. This spell is usable while stunned. Lasts 15 sec.    This ability is usable while Shapeshifted.", "Rare", 0, nil, 0, false, 36, false },
  { "Spell", "Earth Shield", 974, 40738, "Shaman", "Rank 1", "Protects the target with an earthen shield. Lasts 10 min or 6 charges.     Attacks heal the shielded target for 53 (increased by 25% against monsters) and reduce casting or channel time lost when damaged by 34%.     This effect can only occur once every 3 seconds.    Earth Shield can only be placed on one target at a time.", "Rare", 234, nil, 0, false, 36, true },
  { "Spell", "Shadowstep", 36554, 40751, "Rogue", "", "Attempts to step through the shadows and reappear behind your enemy and increases movement speed by 70% for 3 sec.    Using it while not in combat reduces its cooldown by 5 sec.  This ability is usable while shapeshifted.", "Epic", 10, nil, 3, false, 36, true },
  { "Spell", "Mutilate", 1329, 40754, "Rogue", "Rank 1", "Instantly attacks with both weapons for 100% weapon damage plus an additional 36 with each weapon. Awards 2 combo points.    Damage is increased by 20% against Poisoned targets.", "Normal", 60, nil, 3, false, 36, true },
  { "Spell", "Slow", 31589, 40763, "Mage", "", "Reduces target's movement speed by 60%, increases the time between ranged attacks by 60% and increases casting time by 30%.  Lasts 15 sec(10 versus players) Slow can only affect one target at a time.   Does not stack with other similar effects.", "Epic", 187, nil, 0, false, 36, true },
  { "Spell", "Dragon's Breath", 31661, 40769, "Mage", "Rank 1", "Targets in a cone in front of the caster take 179 to 216 Fire damage and are Disoriented for 5 sec.  Any direct damaging attack will revive targets.  Turns off your attack when used.", "Epic", 109, nil, 0, false, 36, true },
  { "Spell", "Summon Water Elemental", 31687, 40774, "Mage", "", "Summon a Water Elemental to fight for the caster for 45 sec.", "Epic", 249, nil, 0, false, 36, true },
  { "Spell", "Divine Illumination", 31842, 40780, "Paladin", "", "Reduces resource cost of all magic spells and abilities by 60% and increases the critical effect chance of Holy healing spells by 20% for 15 sec.", "Rare", 0, nil, 0, false, 36, true },
  { "Spell", "Avenger's Shield", 31935, 40785, "Paladin", "Rank 1", "Hurls a holy shield at the enemy, dealing 512 to 608 Holy damage, Dazing them and then jumping to additional nearby enemies.  Affects 3 total targets. Lasts 10 sec.", "Epic", 406, nil, 0, false, 36, true },
  { "Spell", "Pain Suppression", 33206, 40803, "Priest", "", "Instantly reduces a friendly target's threat by 5%, reduces all damage taken by 40% for 8 sec. Pain Suppression has a 60% chance to resist Dispel mechanics.", "Legendary", 124, nil, 0, false, 36, true },
  { "Spell", "Vampiric Touch", 34914, 40806, "Priest", "Rank 1", "Causes 340 Shadow damage over 15 sec to your target.     When you deal damage with Mind Blast to a target afflicted by your Vampiric Touch, you gain Replenishment .    If Vampiric Touch is dispelled it will cause 544 damage to the afflicted target.       Replenishment  Replenishes 1% of maximum mana per 5 sec on up to 10 party members for 15 sec.", "Normal", 249, nil, 0, false, 36, true },
  { "Spell", "Force of Nature", 33831, 40813, "Druid", "", "Summons 3 treants to attack enemy targets for 30 sec. Shares a cooldown with other Force of Nature spells.  Can't be used while having an active pet.    This ability is usable while shapeshifted.", "Epic", 187, nil, 0, false, 36, true },
  { "Spell", "Tree of Life", 65139, 40817, "Druid", "", "Shapeshift into the Tree of Life.   While in this form you increase healing received by 6% for all party and raid members.  Does not stack with similar effects.  Tree of Life reduces the mana cost of your healing over time spells by 20%.   While in this form, you can only cast healing spells in addition to Innervate, Barkskin, Nature's Grasp, Thorns spells, and non-offensive spells usable while shapeshifted.  If your Primary Stat is Spirit, shapeshifting into Tree of Life will free you from all movement impairing effects.", "Legendary", 0, nil, 0, false, 36, true },
  { "Spell", "Silencing Shot", 34490, 40833, "Hunter", "", "A shot that deals 75% weapon damage and silences the target for 2 sec. Non-player victim spellcasting is also interrupted for 3 sec.     Silencing Shot cannot trigger any procs.    This ability shares a cooldown with other interrupts.", "Epic", 93, nil, 0, false, 36, true },
  { "Spell", "Scatter Shot", 19503, 40839, "Hunter", "", "A short-range shot that deals 50% weapon damage and disorients the target for 4 sec.  Any damage caused except for Piercing Shots and Serpent Sting will remove the effect. Turns off your attack when used.", "Epic", 124, nil, 0, false, 16, true },
  { "Spell", "Circle of Healing", 34861, 40840, "Priest", "Rank 1", "Heals up to 5 friendly party or raid members within 15 yards of the target for 161 to 183.", "Normal", 328, nil, 0, false, 36, true },
  { "Spell", "Arcane Barrage", 44425, 40857, "Mage", "Rank 1", "Launches several missiles at the enemy target, causing 265 to 321 Arcane damage.", "Normal", 281, nil, 0, false, 40, true },
  { "Spell", "Living Bomb", 44457, 40862, "Mage", "Rank 1", "The target becomes a Living Bomb, taking 256 Fire damage over 12 sec.  After 12 sec or when the spell is dispelled, the target explodes dealing 120 Fire damage to all enemies within 10 yards.", "Normal", 343, nil, 0, false, 40, true },
  { "Spell", "Deep Freeze", 44572, 40867, "Mage", "Rank 1", "Stuns the target for 5 sec. Only usable on Frozen targets.  Deals 1376 to 1594 damage to monsters permanently immune to stuns.", "Epic", 140, nil, 0, false, 40, true },
  { "Spell", "Bladestorm", 46924, 40872, "Warrior", "", "Instantly Whirlwind up to 4 nearby targets and for the next 6 sec you will perform a whirlwind attack every 1 sec.  While under the effects of Bladestorm, you can move but cannot perform any other abilities but you do not feel pity or remorse or fear and you cannot be stopped unless disarmed or killed.", "Legendary", 25, nil, 1, false, 40, true },
  { "Spell", "Titan's Grip", 46917, 40876, "Warrior", "Rank 1", "Allows you to wield a Two-Handed Axe, Mace, or Sword in each hand.     Also allows for a weapon or shield to be held in the off-hand while a Staff or Polearm is equipped.    Physical damage dealt is reduced by 10%.", "Rare", 0, nil, 0, false, 10, true },
  { "Spell", "Heroic Fury", 60970, 40877, "Warrior", "", "Removes any movement impairing effects and refreshes the cooldown of your Intercept and Siegebreaker abilities.  This ability is usable while shapeshifted.", "Epic", 0, nil, 1, false, 36, true },
  { "Spell", "Single-Minded Fury", 988256, 40878, "Warrior", "Rank 1", "While a one-handed weapon is equipped in both hands, your Mortal Strike, Overpower and Slam deal 5% less damage but will trigger an additional attack with your off-hand weapon.   Cannot be used with daggers.", "Rare", 0, nil, 0, false, 10, true },
  { "Spell", "Shockwave", 46968, 40881, "Warrior", "", "Sends a wave of force in front of the caster, causing 491 damage (based on attack power) and stunning all enemy targets in a frontal cone for 4 sec.", "Epic", 15, nil, 1, false, 40, true },
  { "Spell", "Demonic Empowerment", 47193, 40886, "Warlock", "", "Grants the Warlock's summoned demon Empowerment.  Imp - Increases the Imp's spell critical strike chance by 20% for 30 sec.  Voidwalker - Increases the Voidwalker's health by 20%, and its threat generated from spells and attacks by 20% for 20 sec.  Succubus - Instantly vanishes, causing the Succubus to go into an improved Invisibility state. The vanish effect removes all stuns, snares and movement impairing effects from the Succubus.  Felhunter - Dispels all magical effects from the Felhunter.  Felguard - Increases the Felguard's attack speed by 20% and breaks all stun, snare and movement impairing effects and makes your Felguard immune to them for 15 sec.", "Rare", 93, nil, 0, false, 30, true },
  { "Spell", "Metamorphosis", 47241, 40891, "Warlock", "", "You transform into a Demon for 30 sec.     This form grants you some unique demon abilities in addition to your normal abilities.     You may only use spells and abilities that deal Fire or Shadow damage(and spells usable while shapeshifted) in this form.    This form increases your armor from cloth and leather by 130%.    Increases your damage by 20%.    Reduces the chance you'll be critically hit by melee attacks by 6% and reduces the duration of stun and snare effects by 50%.", "Legendary", 0, nil, 0, false, 40, true },
  { "Spell", "Chaos Bolt", 50796, 40896, "Warlock", "Rank 1", "Sends a bolt of chaotic fire at the enemy, dealing 598 Shadowflame damage. Chaos Bolt cannot be resisted, and pierces through all absorption, deflection, and reflection effects.", "Normal", 109, nil, 0, false, 40, true },
  { "Spell", "Penance", 47540, 40901, "Priest", "Rank 1", "Launches a volley of holy light at the target, causing 250 Holy damage to an enemy, or 125 to 141 healing to an ally instantly and every 0.98 sec for 1.95 sec.", "Normal", 249, nil, 0, false, 40, true },
  { "Spell", "Psychic Horror", 64044, 40910, "Priest", "", "You terrify the target, causing them to tremble in horror for 3 sec, and disarming their main hand and ranged weapons for 10 sec.  This spell cannot miss. ", "Epic", 249, nil, 0, false, 36, true },
  { "Spell", "Guardian Spirit", 47788, 40913, "Priest", "", "Calls upon a guardian spirit to watch over the friendly target. The spirit increases the healing received by the target by 40%, and also prevents the target from dying by sacrificing itself, only up to a maximum of 15% of target's total health. This sacrifice terminates the effect but heals the target of 50% of their maximum health. Lasts 10 sec.", "Legendary", 93, nil, 0, false, 40, true },
  { "Spell", "Wild Growth", 48438, 40919, "Druid", "Rank 1", "Heals up to 5 friendly party or raid members within 15 yards of the target for 686 over 7 sec. The amount healed is applied quickly at first, and slows down as the Wild Growth reaches its full duration.", "Normal", 359, nil, 0, false, 40, true },
  { "Spell", "Typhoon", 50516, 40925, "Druid", "Rank 1", "You summon a violent Typhoon that does 351 Nature damage when in contact with hostile targets, knocking them back and dazing them for 6 sec.", "Epic", 390, nil, 0, false, 36, true },
  { "Spell", "Starfall", 48505, 40928, "Druid", "Rank 1", "You summon a flurry of stars from the sky on all targets within 20 yards of the caster, each dealing 66 to 75 Arcane damage. Also causes 12 Arcane damage to all other enemies within 5 yards of the enemy target. Maximum 20 stars. Lasts 10 sec.      Shapeshifting into an animal form or mounting cancels the effect. Any effect which causes you to lose control of your character will suppress the starfall effect.", "Legendary", 546, nil, 0, false, 40, true },
  { "Spell", "Haunt", 48181, 40934, "Warlock", "Rank 1", "You send a ghostly soul into the target, dealing 212 to 250 Shadow damage and increasing all damage done by your Shadow damage-over-time effects on the target by 20% for 12 sec.    When the Haunt spell ends or is dispelled, the soul returns to you, healing you for 100% of the damage. (up to 20% of your Maximum Health).", "Normal", 187, nil, 0, false, 40, true },
  { "Spell", "Thunderstorm", 51490, 40940, "Shaman", "Rank 1", "You call down a bolt of lightning, energizing you and damaging nearby enemies within 10 yards. Restores 8% mana to you and deals 307 to 348 Nature damage to all nearby enemies, knocking them back 20 yards.    Usable while stunned.", "Epic", 0, nil, 0, false, 40, true },
  { "Spell", "Feral Spirit", 51533, 40945, "Shaman", "", "Summons two Spirit Wolves under the command of the Shaman, lasting 45 sec.  This ability is usable while shapeshifted.", "Legendary", 187, nil, 0, false, 40, true },
  { "Spell", "Riptide", 61295, 40950, "Shaman", "Rank 1", "Heals a friendly target for 117 to 126 and another 205 over 15 sec.  Your next Chain Heal cast on that primary target within 15 sec will consume the healing over time effect and increase the amount of the Chain Heal by 25%.", "Normal", 281, nil, 0, false, 40, true },
  { "Spell", "Hunger For Blood", 51662, 40956, "Rogue", "", "Enrages you, increasing all Physical and Nature damage caused by 10%, lasting for 15 seconds. Also gives you a movement boost of 30% for 5 seconds. Requires any bleed to be active on the target to be used.   This ability is usable while shapeshifted.", "Epic", 15, nil, 3, false, 40, false },
  { "Spell", "Killing Spree", 51690, 40961, "Rogue", "", "Step through the shadows from enemy to enemy within 10 yards, attacking an enemy for 130% weapon damage (195% with Daggers) every 0.5 sec with both weapons until 5 assaults are made.  Can hit the same target multiple times.  Cannot hit invisible or stealthed targets.", "Legendary", 0, nil, 3, false, 40, true },
  { "Spell", "Shadow Dance", 51713, 40966, "Rogue", "", "Enter the Shadow Dance for 8 sec, allowing the use of Sap, Garrote, Ambush, Cheap Shot, Premeditation, Pickpocket, Disarm Trap, Ravage and Pounce regardless of being stealthed or prowled.", "Epic", 0, nil, 3, false, 40, true },
  { "Spell", "Cleanse Spirit", 51886, 40968, "Shaman", "", "Cleanse the spirit of a friendly target, removing 1 poison effect, 1 disease effect, and 1 curse effect.", "Rare", 109, nil, 0, false, 30, true },
  { "Spell", "Chimera Shot", 53209, 40975, "Hunter", "", "Deals 230% ranged weapon damage, refreshing the current Stings on your target and triggering extra effects if the Stings are active:  Serpent Sting - Instantly deals 90% of the damage done by your Serpent Sting.  Viper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.   Scorpid Sting - Disarms the target for 10 sec. This effect cannot occur more than once per 1 minute.", "Normal", 187, nil, 0, false, 40, true },
  { "Spell", "Beast Mastery", 53270, 40979, "Hunter", "", "Requires   Tame Beast Abilities   You master the art of Beast training, teaching you the ability to tame Exotic pets and increasing your total amount of Pet Skill Points by 6.", "Epic", 0, nil, 0, false, 40, true },
  { "Spell", "Explosive Shot", 53301, 40985, "Hunter", "Rank 1", "You fire an explosive charge into the enemy target, dealing 596 Fire damage to the target.    Nearby enemies are also hit, for 40% of damage dealt.     The charge will blast the target every second for an additional 2 sec.", "Normal", 109, nil, 0, false, 40, true },
  { "Spell", "Divine Storm", 53385, 40989, "Paladin", "", "An instant weapon attack that causes 110% of weapon damage to up to 4 enemies within 8 yards. The Divine Storm heals up to 3 party or raid members for 25% of the damage caused.", "Normal", 187, nil, 0, false, 40, true },
  { "Spell", "Beacon of Light", 53563, 40995, "Paladin", "", "The target becomes a Beacon of Light to all members of your party or raid within a 60 yard radius. Any direct heals you cast on party or raid members will also heal the Beacon for 25% of the amount healed. Lasts 15 sec.     Only one target can be the Beacon of Light at a time.", "Rare", 546, nil, 0, false, 40, true },
  { "Spell", "Hammer of the Righteous", 53595, 40999, "Paladin", "", "Hammer the current target and up to 2 additional nearby targets, causing 4 times your main hand damage per second as Holy damage.", "Normal", 93, nil, 0, false, 40, true },
  { "Spell", "Focus Magic", 54646, 41007, "Mage", "", "Increases the target's chance to critically hit with spells by 3%.      When the target critically hits the caster's chance to critically hit with spells is increased by 3% for 10 sec.     Cannot be cast on self.", "Uncommon", 93, nil, 0, false, 16, true },
  { "Spell", "Divine Sacrifice", 64205, 41040, "Paladin", "", "30% of all damage taken by party members within 30 yards is redirected to the caster (up to a maximum of 40% of the caster's health times the number of party members).  Damage which reduces the caster below 20% health will break the effect.  Lasts 10 sec.", "Epic", 0, nil, 0, false, 16, true },
  { "Spell", "Threat of Thassarian", 65661, 41116, "DeathKnight", "Rank 1", "When dual-wielding your, Plague Strike, Death Strike, Blood Strike, Frost Strike, Obliterate and Rune Strike hits also strike with your off-hand weapon.", "Rare", 0, nil, 0, false, 10, true },
  { "Spell", "Death Wish", 812292, 41877, "Warrior", "", "When activated you become enraged, increasing your physical damage by 15% but increasing all damage taken by 5%. Lasts 30 sec.  This ability is usable while shapeshifted.", "Epic", 10, nil, 1, false, 22, true },
  { "Spell", "Rune Tap", 48982, 41970, "DeathKnight", "", "Converts 1 Blood Rune into 10% of your maximum health.", "Rare", 0, nil, 5, false, 16, true },
  { "Spell", "Mark of Blood", 49005, 41971, "DeathKnight", "", "Place a Mark of Blood on an enemy.  Whenever the marked enemy deals damage to a target, that target is healed for 4% of its maximum health.  Lasts for 20 sec or up to 20 hits.", "Epic", 0, nil, 5, false, 22, true },
  { "Spell", "Hysteria", 49016, 41972, "DeathKnight", "", "Induces a friendly unit into a killing frenzy for 30 sec. The target is Enraged, which increases their physical damage by 15%, but causes them to lose health equal to 1% of their maximum health every second.", "Epic", 0, nil, 5, false, 30, true },
  { "Spell", "Heart Strike", 55050, 41973, "DeathKnight", "Rank 1", "Instantly strike the target and his nearest ally, causing 50% weapon damage plus 69 on the primary target, and 25% weapon damage plus 35 on the secondary target.  Each target takes 10% additional damage for each of your diseases active on that target.", "Normal", 0, nil, 5, false, 36, true },
  { "Spell", "Dancing Rune Weapon", 49028, 41974, "DeathKnight", "", "Summons a second rune weapon that fights on its own for 8 sec, doing the same attacks as you but for 75% reduced damage.", "Epic", 60, nil, 1, false, 40, true },
  { "Spell", "Frost Strike", 49143, 41975, "DeathKnight", "Rank 1", "Instantly strike the enemy, causing 55% weapon damage plus 31 as Frost damage.", "Normal", 40, nil, 1, false, 36, true },
  { "Spell", "Unbreakable Armor", 51271, 41976, "DeathKnight", "", "Reinforces your armor with a thick coat of ice, increasing your armor by 25% and increasing your Strength by 20% for 20 sec.", "Epic", 0, nil, 5, false, 34, true },
  { "Spell", "Deathchill", 49796, 41977, "DeathKnight", "", "When activated, makes your next Icy Touch, Howling Blast, Frost Strike or Obliterate a critical hit if used within 30 sec.", "Epic", 0, nil, 0, false, 22, true },
  { "Spell", "Master of Ghouls", 52143, 41978, "DeathKnight", "", "Reduces the cooldown on Raise Dead by 60 sec, and the Ghoul summoned by your Raise Dead spell is considered a pet under your control.  Unlike normal Death Knight Ghouls, your pet does not have a limited duration.", "Rare", 1, nil, 6, false, 24, true },
  { "Spell", "Corpse Explosion", 49158, 41979, "DeathKnight", "Rank 1", "Cause a corpse to explode for 166 Shadow damage to all enemies within 10 yards.  Will use a nearby corpse if the target is not a corpse.  Does not affect mechanical or elemental corpses.", "Normal", 40, nil, 1, false, 16, true },
  { "Spell", "Howling Blast", 49184, 41980, "DeathKnight", "Rank 1", "Blast the target with a frigid wind dealing 324 to 334 Frost damage to all enemies within 10 yards.", "Normal", 0, nil, 5, false, 40, true },
  { "Spell", "Hungering Cold", 49203, 41981, "DeathKnight", "Rank 1", "Purges the earth around the you of all heat. Enemies within 10 yards are trapped in ice, preventing them from performing any action for 10 sec and infecting them with Frost Fever. Enemies are considered Frozen, but any damage other than diseases will break the ice.", "Legendary", 40, nil, 1, false, 30, true },
  { "Spell", "Summon Gargoyle", 49206, 41982, "DeathKnight", "", "A Gargoyle flies into the area and bombards the target with Nature damage, increased by your attack power.  Persists for 30 sec.", "Epic", 60, nil, 1, false, 40, true },
  { "Spell", "Bone Shield", 49222, 41983, "DeathKnight", "", "Your are surrounded by 3 whirling bones.  While at least 1 bone remains, you take 20% less damage from all sources and deals 2% more damage with all attacks, spells and abilities.  Each damaging attack that lands consumes 1 bone.  Lasts 5 min.", "Epic", 0, nil, 5, false, 34, true },
  { "Spell", "Vampiric Blood", 55233, 41984, "DeathKnight", "", "Temporarily grants you 15% of your maximum health and increases the amount of health generated through your Death Knight spells and effects by 35% for 10 sec. After the effect expires, the health is lost.", "Epic", 0, nil, 5, false, 34, true },
  { "Spell", "Ghoul Frenzy", 63560, 41985, "DeathKnight", "", "Grants your Ghoul pet 25% haste for 30 sec and heals it for 60% of its health over the duration.", "Normal", 0, nil, 5, false, 30, true },
  { "Spell", "Lichborne", 49039, 41986, "DeathKnight", "", "Draw upon unholy energy to become undead for 10 sec.  While undead, you are immune to Charm, Fear and Sleep effects.", "Epic", 0, nil, 0, false, 16, true },
  { "Spell", "Scourge Strike", 55090, 41987, "DeathKnight", "Rank 1", "An unholy strike that deals 70% of weapon damage as Physical damage plus 102.  In addition, for each of your diseases on your target, you deal an additional 12% of the Physical damage done as Shadow damage.", "Normal", 0, nil, 5, false, 36, true },
  { "Spell", "Anti-Magic Zone", 51052, 41988, "DeathKnight", "Rank 1", "Places a large, stationary Anti-Magic Zone that reduces spell damage done to party or raid members inside it by 75%. The Anti-Magic Zone lasts for 10 sec or until it absorbs 12045 spell damage.", "Legendary", 0, nil, 5, false, 30, true },
