  { "Spell", "Seal of Command", 20375, 42110, "Paladin", "", "All main hand auto attacks and Paladin melee abilities deal 48 to 57 additional Holy damage to the target and up to 2 additional targets. Lasts until cancelled.  Unleashing this Seal's energy will judge an enemy, instantly causing 134 to 143 Holy damage.", "Rare", 218, nil, 0, false, 16, true },
  { "Spell", "Summon Felguard", 30146, 42111, "Warlock", "Summon", "Summons a Felguard under the command of the Warlock.", "Epic", 1249, nil, 0, false, 36, true },
  { "Spell", "Totem of Wrath", 30706, 42112, "Shaman", "Rank 1", "Summons a Totem of Wrath with 5 health at the feet of the caster.     The totem increases Intellect by 22 and spell power by 23 for all party and raid members, and increases critical strike chance against all nearby targets by 3%. Lasts 5 min.   Does not stack with other similar effects.  This ability is usable while shapeshifted.", "Rare", 78, nil, 0, false, 36, true },
  { "Spell", "Aether Mangle", 939000, 50121, "Classless", "Rank 1", "Mangle the target, inflicting Spellstrike damage and causing the target to take 30% additional damage from bleeds for 1 min.   Does not stack with other similar effects.  This ability can be used in Cat Form or Dire Bear Form. This uses Mangle modifiers.", "Normal", 0, nil, 0, false, 36, true },
