  { "Spell", "Dawn Mangle", 939120, 50123, "Classless", "Rank 1", "Mangle the target, inflicting Holystrike damage and causing the target to take 30% additional damage from bleeds for 1 min.   Does not stack with other similar effects.  This ability can be used in Cat Form or Dire Bear Form. This uses Mangle modifiers.", "Normal", 0, nil, 0, false, 36, true },
