  { "Talent", "Favour of the Soulflayer", 275865, 36822, "Classless", "", "Using Hunger for Blood now consumes Bathe in Blood  to trigger Favour of the Soulflayer .        Favour of the Soulflayer  Causes Physical damage to all nearby enemies within 8 yards, increased by consuming your Bathe in Blood stacks.     Increases your Physical critical damage bonus by 30% and Crimson Tempest now benefits from haste and has the ability to critically hit. Lasts 10 sec.", "Legendary", 0, nil, 0, false, 30, true },
  { "Talent", "Onslaught", 275913, 36823, "Classless", "", "Using Colossus Smash now grants you Onslaught .      Onslaught  Your next Execute can be used regardless of the target's health, and its damage is increased by 30%.", "Epic", 0, nil, 0, false, 30, true },
  { "Talent", "Raging Onslaught", 275920, 36828, "Classless", "", "Raging Blow deals 20% increased damage, and has a 20% chance to refund a charge.", "Epic", 0, nil, 0, false, 28, true },
