  { "Talent", "Afflicted Soul", 275968, 36833, "Classless", "", "Dealing damage with Drain Soul now applies Afflicted Soul , and consumes 15 stacks to apply Ruptured Soul .        Ruptured Soul  You deal 25% increased periodic Shadow damage against the target. Lasts 30 sec.", "Legendary", 0, nil, 0, false, 10, true },
  { "Talent", "Biting Drain", 275969, 36834, "Classless", "", "Critical strike damage bonus of your Drain Life and Drain Soul is increased by 35%.", "Epic", 0, nil, 0, false, 10, true },
