  { "Talent", "Fel Core", 276068, 36844, "Classless", "", "Using Bloodthirst increases the chance to trigger Molten Core  by 2%. Stacks up to 10 times and lasts 12 sec.    Your Molten Core  also empowers Chaos Bolt, increasing its damage by 15% and critical strike chance by 10%.", "Epic", 0, nil, 0, false, 40, true },
  { "Talent", "Preservation", 276273, 36858, "Classless", "", "Prayer of Preservation now grants Preservation  to injured allies.      Preservation  Your next direct heal on this ally consumes Preservation , healing 3 nearby additional allies for 129 each, granting Shield of Preservation  and reducing the cooldown of Prayer of Preservation by 2 sec. Lasts for 10 sec.     Shield of Preservation  Reduces the damage taken from area of effect attacks by 30%. Lasts for 3 sec.", "Legendary", 0, nil, 0, false, 30, true },
  { "Talent", "Bloody Resets", 276300, 36860, "Classless", "", "Hemorrhage and Ghostly Strike can now trigger your Sword and Board  talent.", "Rare", 0, nil, 0, false, 40, true },
  { "Talent", "Relentless Reflexes", 276302, 36862, "Classless", "", "Your finishing moves grant Relentless Reflexes , increasing dodge chance by 2% per stack. Stacks up to 5 times and lasts 16 sec.    The duration is not refreshed when gaining stacks.", "Rare", 0, nil, 0, false, 10, true },
  { "Talent", "Violent Combo", 276308, 36863, "Classless", "", "Finishing moves have a 20% chance to grant 2 combo points.", "Rare", 0, nil, 0, false, 40, true },
  { "Talent", "Temporal Distortion", 276361, 36868, "Classless", "", "Your Align, Synchronize and Time-Bind now grant you Temporal Distortion .      Temporal Distortion  Reduces your energy generation by 10%.    Increases the duration of Eternity  by 0.4 sec and its healing by 13%. Stacks up to 20 times and lasts for 30 sec or until you reach 0 energy.", "Legendary", 0, nil, 0, false, 10, true },
  { "Talent", "Eternity", 276362, 36869, "Classless", "", "When your Align, Synchronize or Time-Bind spells reduce you to 0 energy, you gain Eternity .      Eternity  A wave of healing radiates from you, increasing your energy generation by 250% and cast speed by 20%. You restore 5% missing mana every 1.5 sec. Lasts for 2 sec.    Each stack of Temporal Distortion increases Eternity's healing by 13% and duration by 0.3 sec.", "Legendary", 0, nil, 0, false, 10, true },
  { "Talent", "Borrowing Time", 276364, 36870, "Classless", "", "Casting Align, Renew and Synchronize now grants you Borrowed Time .      Borrowed Time  Grants spell haste for your next spell after casting Power Word: Shield.  This effect is not consumed by instant-cast spells.", "Rare", 0, nil, 0, false, 35, true },
  { "Talent", "Aligned with Time", 276367, 36871, "Classless", "", "Time-Bind now increases the healing your ally receives from your Align by 15%.", "Rare", 0, nil, 0, false, 10, true },
  { "Talent", "Edge of Fury", 276397, 36875, "Classless", "", "Killing Spree no longer teleports you to deal its damage.    Dealing damage with Blind Revenge now grants you Edge of Fury .        Edge of Fury  Increases the damage of your next Killing Spree  by 10%. Stacks to 5 times and lasts for 15 sec.", "Rare", 0, nil, 0, false, 40, true },
  { "Talent", "Harbinger of Plague", 276427, 36876, "Classless", "", "Casting Wrath now grants you Harbinger of Plague .    While affected by Harbinger of Plague , Haunt deals 30% of its damage to 10 nearby targets.        Harbinger of Plague  Increases the damage of your diseases and Haunt by 15%. Stacks up to 5 times and lasts for 8 sec.", "Epic", 0, nil, 0, false, 10, true },
  { "Talent", "Holy Shatter", 276466, 36880, "Classless", "", "Critical strikes with Frost spells mark your target.     Critical strikes with Holy spells shatter the mark, dealing 497 Holyfrost damage to 8 nearby enemies.    Marks stack up to 5 and increase the damage the target takes from Holy Shatter by 20%. Lasts 12 seconds.    Scales with Cone of Cold modifiers.", "Legendary", 0, nil, 0, false, 20, true },
  { "Talent", "Demonic Persistence", 276506, 36885, "Classless", "", "Your Wild Imps from Hand of Gul'dan are now overcharged with Fel energy, causing them to deteriorate over time. This causes your Incinerate and Mind Blast to trigger Demonic Persistence .      Demonic Persistence  Sacrifices the lowest-health Wild Imp, dealing 140 to 180 Fire damage to targets within 8 yards. Increases the damage of your active Demon by 20% and your Wild Imps by 20%, stacking up to 4 times. For each demon detonated, your Wild Imps last 1 additional second per stack of Demonic Persistence.  Requires a Demon", "Legendary", 0, nil, 0, false, 32, true },
  { "Talent", "Heretic of Gul'dan", 276516, 36886, "Classless", "", "Dealing damage with spells reduces the cooldown of Hand of Gul'Dan by 0.5 sec.  This effect can only occur once every 1 sec.", "Epic", 0, nil, 0, false, 32, true },
