  { "Talent", "Flame Born", 276550, 36889, "Classless", "", "Critical strikes from Corruption and Unstable Affliction now grant you Flame Born .       Flame Born  Increases the critical strike chance of your next Conflagrate by 15% and periodic damage of your Shadowflame. Stacks up to 4 times and lasts for 15 sec.", "Epic", 0, nil, 0, false, 36, true },
