  { "Talent", "Swashbuckling Duelist", 276668, 36903, "Classless", "", "Requires   Duelist's Glove   A Duelist's Glove is an off-hand item that enables Swashbuckling. It is granted whenever you learn a talent or ability that requires it.    Sinister Strike now grants you Swashbuckling Duelist  for 12 seconds, causing your next Mongoose Bite to unleash a Pirate's Flurry .      Pirate's Flurry  You unleash a flurry of blows, striking your target for 225% weapon damage 3 times over 1 second.", "Legendary", 0, nil, 0, false, 10, true },
  { "Talent", "Defias Gunslinger", 276669, 36904, "Classless", "", "Requires   Duelist's Glove   Sinister Strike now grants you Gunslinger's Strike .      Gunslinger's Strike  Increases the damage of your next Raptor Strike by 50%. Lasts 12 sec.    Damage increased by 30% against players.", "Legendary", 0, nil, 0, false, 10, true },
