  { "Talent", "Grove Ranger", 276890, 36922, "Classless", "", "Requires   Path of Healing   Using Hunter Shots now grants you Grove Ranger .   Stacks up to 2 times.      Grove Ranger  Consumes up to 2 stacks to empower your next Wild Growth, Healing Touch or Regrowth. Consuming 2 stacks doubles the effect.    - Wild Growth : Heals 2 additional targets and its heal radius is increased by 5 yards.    - Healing Touch and Regrowth : Cast time reduced by 50% and mana cost reduced by 30%.    - Healing Touch : Heals an additional target and healing increased by 30%.", "Legendary", 0, nil, 0, false, 10, true },
  { "Talent", "Grove Ranger's Agility", 276896, 36923, "Classless", "", "Requires   Path of Healing   Increases your attack power by 120% of your Agility and your Healing Power by 20% of your Agility.", "Legendary", 0, nil, 0, false, 10, true },
  { "Talent", "Vampire Lord", 276963, 36928, "Classless", "", "Requires   Path of Healing   Dealing damage with your Shadow Priest damage over time spells or healing with Shadow Mend  generates a stack of Vampiric Essence .     Mind Flay  generates 2 stacks per tick.    Each tick of Mind Sear  can consume 3 Vampiric Essence  to heal up to 5 allies for 234 health.    Vampiric Essence  can stack up to 30 times.", "Epic", 0, nil, 0, false, 30, true },
  { "Talent", "En Garde!", 277049, 36933, "Classless", "", "Requires   Duelist's Glove   Requires   Defensive Stance   While Swashbuckling, converts 15% of your Agility into Parry Rating.    Your finishing moves reduce the duration of your active Stagger  effect by 0.6 sec per combo point.", "Epic", 0, nil, 0, false, 18, true },
