  { "Talent", "Soul Void", 277143, 36939, "Classless", "", "Dealing damage with Drain Soul now applies Soul Void. Reaching 10 stacks applies Withered Soul, causing your Drain Life to deal 25% more damage. Lasts 15 sec.     Enemies with Withered Soul do not gain Soul Void.", "Legendary", 0, nil, 0, false, 10, true },
