  { "Talent", "Pack Enhancement", 277190, 36948, "Classless", "", "Dealing damage with Shaman Weapon Enhancements grants you Commands . These stack up to 5 times and last 30 sec. Casting Feral Spirits consumes your Commands , empowering your Feral Spirits based on the Command stacks consumed.      Command of Precision  Granted from dealing damage with Flametongue Weapon.   Consuming this increases critical strike chance of your Feral Spirits by 10% per stack for 30 sec.     Command of Might  Granted from dealing damage with Frostbrand Weapon.   Consuming this increases damage of your Feral Spirits by 10% per stack for 30 sec     Command of Fury  Granted from dealing damage with Windfury Weapon.   Consuming this increases haste of your Feral Spirits by 10% per stack for 30 sec.", "Epic", 0, nil, 0, false, 60, true },
  { "Talent", "Unseen Assassin", 277450, 36957, "Classless", "", "For 3 sec after leaving Stealth or activating Shadow Dance, your Glaive Toss, Deadly Throw and Shuriken Toss only triggers a 0.5 sec global cooldown.    Deadly Throw and Shuriken Toss deal 30% reduced damage against players whilst affected by Unseen Assassin", "Epic", 0, nil, 0, false, 34, true },
  { "Talent", "Toss and Throw", 277455, 36958, "Classless", "", "Using Deadly Throw causes your next three casts of Shuriken Toss or Glaive Toss to generate an additional combo point, cost 20% fewer resources and deal 20% more damage against monsters. Lasts 8 sec.", "Epic", 0, nil, 0, false, 24, true },
  { "Talent", "Physics in Practice", 277460, 36959, "Classless", "", "Your Deadly Throw and Shuriken Toss deal increased damage based on the movement speed bonus of your active Sprint.    The damage increase is 15% as effective versus players.", "Legendary", 0, nil, 0, false, 34, true },
  { "Talent", "Frosty Frost Frostbolt", 277465, 36960, "Classless", "", "Every third Frostbolt hits up to 5 additional enemies near your target, but has its cast time increased by 0.3 sec.", "Epic", 0, nil, 0, false, 10, true },
  { "Talent", "Lich's Calling", 277470, 36961, "Classless", "", "Dealing damage with Cone of Cold, Deep Freeze or Howling Blast afflicts your target with Lich's Calling .        Lich's Calling  Increase the effectiveness of your Frost periodic effects on the target by 30%. Has 8 charges. Lasts 15 sec.", "Legendary", 0, nil, 0, false, 16, true },
  { "Talent", "Master of Kunai", 277475, 36962, "Classless", "", "Using Adrenaline Rush grants Master of Kunai .    Using Shuriken Toss reduces the cooldown of Adrenaline Rush by 3 sec.        Master of Kunai  Your Shuriken Toss and Glaive Toss hit an additional 2 targets. Lasts 20 sec.    Hitting an enemy with Shuriken Toss increases the damage of your next Deadly Throw or Glaive Toss by 70%, stacking up to 3 times.    Increases damage against players by 5% per stack.", "Legendary", 0, nil, 0, false, 30, true },
