  { "Talent", "Icecrown Double-Tap", 277496, 36966, "Classless", "", "Direct Frost spell damage has an 15% chance to grant Icecrown Double-Tap .        Icecrown Double-Tap  Allows your next Kill Shot to be used regardless of the target's health. Lasts 20 sec.", "Epic", 0, nil, 0, false, 36, true },
  { "Talent", "Frozen Munitions", 277499, 36967, "Classless", "", "Hunter attacks grant you a stack of Frozen Munitions . Stacks up to 3 times and lasts 20 sec.        Frozen Munitions  Consumes up to 3 stacks to empower your next Frozen Orb, Frostbolt or Ice Lance. Consuming additional stacks increases the effect.    Frozen Orb -  Direct damage increased by 20%.    Frostbolt -  34% reduced cast time, and 50% increased damage against monsters.    Ice Lance -  Deals 50% increased damage, and its global cooldown is reduced to 1 sec.", "Legendary", 0, nil, 0, false, 10, true },
  { "Talent", "Inner Hunt", 277505, 36968, "Classless", "", "Non-hunter melee abilities grant Inner Hunt .    This effect can only occur once every 8 sec and only from abilities that trigger the global cooldown.      Inner Hunt  Your next Mongoose Bite and Counterattack deals 50% increased damage, ignores 50% of the target's armor and does not trigger its cooldown. Lasts for 15 sec.    Mongoose Bite and Counterattacks damage is increased by 25% versus players.", "Epic", 0, nil, 0, false, 10, true },
  { "Talent", "Magical Ammunition", 277515, 36969, "Classless", "", "Damaging spells grant you Magical Ammunition .        Magical Ammunition  Increases the amount of your next Multi-Shot projectiles by 1. Stacks up to 5 times and lasts 15 sec.", "Epic", 0, nil, 0, false, 18, true },
  { "Talent", "Coldstrike Marksmanship", 277522, 36970, "Classless", "", "Direct Frost Spell critical strikes grant you a charge of Coldstrike Marksmanship .      Coldstrike Marksmanship  Increases the damage of your next Hunter Shot by 20%. Holds 6 charges. Lasts 20 sec.", "Epic", 0, nil, 0, false, 10, true },
