  { "Talent", "Barrage Overload", 277540, 36973, "Classless", "", "When Missile Barrage is consumed, you gain Barrage Overload .      Barrage Overload  Your next Arcane Barrage causes you to overload, unleashing 1 arcane bolt per stack. Stacks up to 6 times. Lasts 10 sec.", "Legendary", 0, nil, 0, false, 36, true },
  { "Talent", "Battle Glaive", 277555, 36975, "Classless", "", "Using 3 Warrior direct damaging abilities in quick succession resets the cooldown of Glaive Toss and increases the damage of your next Glaive Toss by 40%. Lasts 10 sec.  Does not work with \"on next swing\" abilities.", "Epic", 0, nil, 0, false, 14, true },
  { "Talent", "Pack Leader", 277566, 36978, "Classless", "", "When Maelstrom Weapon is consumed at max stacks, you gain Pack Leader .  Pack Leader reduces the healing from Spirit Wolves by 70%.      Pack Leader  Increases the duration of your next Feral Spirits by 2 sec.   Increases the amount of Feral Spirits spawned by 1. Stacks up to 5 times and lasts 25 sec.", "Legendary", 0, nil, 3, false, 40, true },
  { "Talent", "Thousand Cuts", 277588, 36981, "Classless", "", "Dealing damage with Hurricane now increases your Poison and Bleed damage by 4%. Stacks up to 5 times and lasts 12 sec.", "Epic", 0, nil, 3, false, 40, true },
  { "Talent", "Stormforged Edge", 277607, 36987, "Classless", "", "Lightning Bolt, Chain Lightning, Static Shock and Thunderstorm hits increase the damage of your next Stormstrike by 24%. Stacks up to 8. Lasts 8 sec. Duration cannot be refreshed.", "Legendary", 0, nil, 3, false, 10, false },
