  { "Talent", "I'm a Fan of Knives", 277612, 36989, "Classless", "", "Dealing damage with Shuriken Toss and Deadly Throw has a 25% chance to increase the damage of your next Fan of Knives by 25% and its critical strike chance by 25%. Max 3 charges.", "Epic", 0, nil, 3, false, 14, true },
