  { "Talent", "Blood Shield", 288804, 43101, "Classless", "", "Requires Frost Presence.    Death Strike no longer heals you.     Instead it shields you for 5% of your maximum health for each of her diseases on the target.     The shield is capped at 20% of your maximum health, 10% against players.", "Rare", 0, nil, 0, false, 55, true },
  { "Talent", "Runic Defense", 288807, 43103, "Classless", "", "When you dodge, parry, or block, you have a 15% chance to activate and convert a Rune into a Death Rune for 10 seconds. This chance is doubled while Bone Shield is active. This effect can only occur once every 15 sec.", "Rare", 0, nil, 0, false, 38, true },
  { "Talent", "Runic Maelstrom", 288821, 43107, "Classless", "", "Consuming Maelstrom Weapon at maximum stacks empowers your next Scourge Strike, Heart Strike, or Frost Strike within 10 sec, increasing its damage by 30%.", "Rare", 0, nil, 0, false, 40, true },
  { "Talent", "Saronite Phalanx", 288825, 43109, "Classless", "", "Bone Shield holds 1 more charge.     Dodging, parrying, or blocking while Bone Shield is active consumes 1 charge to grant Saronite Phalanx          Saronite Phalanx  Increases the damage of your next Rune Strike, Shield Slam or Shield of Righteousness by 20%. Stacks up to 3. Lasts 12 seconds.", "Rare", 0, nil, 0, false, 55, true },
  { "Talent", "Defile the Grove", 288828, 43110, "Classless", "", "Your Druid periodic damage deals 8% increased damage to targets standing in your Death and Decay.", "Rare", 0, nil, 0, false, 55, true },
  { "Talent", "Rimebound Shadow", 288832, 43112, "Classless", "", "Your Frost spell damage against targets affected by your Frost Fever has a 25% chance to grant Rimebound Shadow .      Rimebound Shadow  Your next Grave Coil triggers a 379 Shadowfrost damage around the target.  This effect can only occur once every 3 sec.", "Epic", 0, nil, 0, false, 55, true },
  { "Talent", "Frozen Grave", 288836, 43113, "Classless", "", "Your Shadow spells against targets affected by your Frost Fever extend Frost Fever by 2 sec, up to 6 sec beyond its normal maximum and grant Frozen Grave .        Frozen Grave  Increases the damage of your next Howling Blast or Icy Touch by 10%. Stacks up to 5. Lasts 12 seconds.", "Rare", 0, nil, 0, false, 55, true },
  { "Talent", "Black Ice Arsenal", 288838, 43114, "Classless", "", "Dealing damage with Howling Blast, Icy Touch, and Frost Strike applies Black Ice .        Black Ice  Increases damage taken from the caster's next Frostbolt and Frostfire Bolt by 10%. Stacks up to 3. Lasts for 12 sec.", "Rare", 0, nil, 0, false, 55, true },
  { "Talent", "Grave Ammunition", 288840, 43115, "Classless", "", "You have a 15% chance for your Frost Fever ticks to load Black-Ice Ammunition  and Blood Plague ticks to load Plague-Tipped Ammunition .       Black-Ice Ammunition  Next Auto shot triggers 33% ranged weapon damage as Shadowfrost damage to enemies within 8 yards of the target.      Plague-Tipped Vulnerability  Next Auto shot increases damage taken from your Frost Fever and Blood Plague by 2% per stack. Stacks up to 10 times.", "Rare", 0, nil, 0, false, 55, true },
  { "Talent", "Runeforged Verdict", 288845, 43116, "Classless", "", "Your Judgements against a target affected by your Frost Fever or Blood Plague extend those diseases by 2 sec, up to 6 sec beyond their normal maximum, and grant Runeforged Verdict .      Runeforged Verdict  Increases direct damage of your next Frost Strike, Heart Strike or Obliterate by 30%.", "Rare", 0, nil, 0, false, 55, true },
